-- AGV Log canonical database baseline
-- Source: reviewed live catalog snapshot
-- Catalog snapshot date: 2026-08-24
-- Baseline version: 20260824224152 (latest applied remote migration at snapshot time)
--
-- This file describes the final schema state. Historical ALTER/DROP/recreate steps
-- were intentionally removed. Business data is intentionally excluded.
-- Platform bootstrap retained here: Storage buckets and Realtime publications.
-- Scheduled cron jobs are kept outside the active migration because the previous
-- definitions embedded environment-specific credentials and tenant identifiers.
--
-- Generated from the live PostgreSQL 17 catalog and reviewed as a single baseline.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;
SET row_security = off;
SET search_path TO public, extensions, pg_catalog;

-- -----------------------------------------------------------------------------
-- Extensions
-- -----------------------------------------------------------------------------

CREATE SCHEMA IF NOT EXISTS extensions;
CREATE SCHEMA IF NOT EXISTS vault;

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pg_stat_statements WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS postgis WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;
CREATE EXTENSION IF NOT EXISTS supabase_vault WITH SCHEMA vault;
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA public;

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------

CREATE TYPE public.app_role AS ENUM ('owner', 'admin', 'operator', 'client', 'driver');

CREATE TYPE public.data_recovery_status AS ENUM ('draft', 'reviewed', 'approved', 'executing', 'completed', 'failed', 'cancelled');

CREATE TYPE public.operation_type AS ENUM ('filial', 'armazenagem', 'frota', 'viagem_direta', 'retira', 'transferencia', 'devolucao', 'redespacho');

CREATE TYPE public.waypoint_type AS ENUM ('origin', 'destination', 'fueling', 'overnight', 'meal', 'client', 'checkpoint', 'other');

-- -----------------------------------------------------------------------------
-- Sequences
-- -----------------------------------------------------------------------------

CREATE SEQUENCE public.freight_tables_table_code_seq AS integer START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1 NO CYCLE;

