CREATE OR REPLACE FUNCTION public.create_tenant_with_owner(_tenant_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user_id uuid;
  _tenant_id uuid;
BEGIN
  _user_id := auth.uid();
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Create tenant
  INSERT INTO public.tenants (name, plan_key)
  VALUES (_tenant_name, 'free')
  RETURNING id INTO _tenant_id;

  -- Create owner membership
  INSERT INTO public.tenant_memberships (tenant_id, user_id, role, active)
  VALUES (_tenant_id, _user_id, 'owner', true);

  RETURN _tenant_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_geofence(_id uuid, _tenant_id uuid, _name text, _category text, _geojson text, _enabled boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _result_id uuid;
BEGIN
  IF NOT is_tenant_admin(_tenant_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  
  IF _id IS NOT NULL THEN
    UPDATE public.geofences
    SET name = _name, category = _category,
        geometry = extensions.ST_GeomFromGeoJSON(_geojson),
        enabled = _enabled
    WHERE id = _id AND tenant_id = _tenant_id
    RETURNING id INTO _result_id;
  END IF;
  
  IF _result_id IS NULL THEN
    INSERT INTO public.geofences (tenant_id, name, category, geometry, enabled)
    VALUES (_tenant_id, _name, _category, extensions.ST_GeomFromGeoJSON(_geojson), _enabled)
    RETURNING id INTO _result_id;
  END IF;
  
  RETURN _result_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.is_point_in_geofence(_geofence_id uuid, _lng double precision, _lat double precision)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    extensions.ST_Contains(
      geometry,
      extensions.ST_SetSRID(extensions.ST_Point(_lng, _lat), 4326)
    ),
    false
  )
  FROM public.geofences
  WHERE id = _geofence_id
$function$;

CREATE OR REPLACE FUNCTION public.count_points_in_geofence(_geofence_id uuid, _points jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  i int;
  total int := 0;
  inside int := 0;
  p jsonb;
  lng double precision;
  lat double precision;
  is_in boolean;
BEGIN
  IF _points IS NULL THEN
    RETURN jsonb_build_object('total',0,'inside',0);
  END IF;
  total := jsonb_array_length(_points);
  IF total = 0 THEN
    RETURN jsonb_build_object('total',0,'inside',0);
  END IF;
  FOR i IN 0..total-1 LOOP
    p := _points->i;
    lng := (p->>'lng')::double precision;
    lat := (p->>'lat')::double precision;
    SELECT extensions.ST_Contains(
      (SELECT geometry FROM public.geofences WHERE id=_geofence_id),
      extensions.ST_SetSRID(extensions.ST_Point(lng, lat), 4326)
    ) INTO is_in;
    IF COALESCE(is_in,false) THEN inside := inside + 1; END IF;
  END LOOP;
  RETURN jsonb_build_object('total', total, 'inside', inside);
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_inventory_balance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _sign integer;
  _now timestamptz := now();
BEGIN
  -- Determine sign based on movement type
  IF NEW.movement_type = 'inbound' THEN
    _sign := 1;
  ELSIF NEW.movement_type = 'outbound' THEN
    _sign := -1;
  ELSIF NEW.movement_type = 'adjustment' THEN
    _sign := 1; -- adjustment quantity can be negative
  ELSIF NEW.movement_type = 'transfer' THEN
    _sign := 0; -- transfers handled separately if needed
  ELSE
    _sign := 0;
  END IF;

  IF _sign = 0 THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.inventory_balances (
    tenant_id, location_id, client_id, item_description,
    quantity, pallet_count, weight_kg, volume_m3,
    first_inbound_at, last_movement_at, updated_at
  )
  VALUES (
    NEW.tenant_id,
    NEW.location_id,
    NEW.client_id,
    NEW.item_description,
    COALESCE(NEW.quantity, 0) * _sign,
    COALESCE(NEW.pallet_count, 0) * _sign,
    COALESCE(NEW.weight_kg, 0) * _sign,
    COALESCE(NEW.volume_m3, 0) * _sign,
    CASE WHEN NEW.movement_type = 'inbound' THEN _now ELSE NULL END,
    _now,
    _now
  )
  ON CONFLICT (tenant_id, location_id, client_id, item_description)
  DO UPDATE SET
    quantity = inventory_balances.quantity + COALESCE(NEW.quantity, 0) * _sign,
    pallet_count = inventory_balances.pallet_count + COALESCE(NEW.pallet_count, 0) * _sign,
    weight_kg = COALESCE(inventory_balances.weight_kg, 0) + COALESCE(NEW.weight_kg, 0) * _sign,
    volume_m3 = COALESCE(inventory_balances.volume_m3, 0) + COALESCE(NEW.volume_m3, 0) * _sign,
    first_inbound_at = COALESCE(inventory_balances.first_inbound_at,
      CASE WHEN NEW.movement_type = 'inbound' THEN _now ELSE NULL END),
    last_movement_at = _now,
    updated_at = _now;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.recalc_load_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.loads SET
    total_pallet_count = COALESCE((SELECT SUM(pallet_count) FROM public.load_items WHERE load_id = COALESCE(NEW.load_id, OLD.load_id)), 0),
    total_weight_kg = COALESCE((SELECT SUM(weight_kg) FROM public.load_items WHERE load_id = COALESCE(NEW.load_id, OLD.load_id)), 0),
    total_volume_m3 = COALESCE((SELECT SUM(volume_m3) FROM public.load_items WHERE load_id = COALESCE(NEW.load_id, OLD.load_id)), 0),
    updated_at = now()
  WHERE id = COALESCE(NEW.load_id, OLD.load_id);
  RETURN COALESCE(NEW, OLD);
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_driver_vehicle_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Avoid recursion: only act on the original update fired by the user
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'vehicles' THEN
    IF OLD.current_driver_id IS NOT NULL AND OLD.current_driver_id IS DISTINCT FROM NEW.current_driver_id THEN
      UPDATE public.drivers SET current_vehicle_id = NULL, updated_at = now()
        WHERE id = OLD.current_driver_id AND current_vehicle_id = NEW.id;
    END IF;
    IF NEW.current_driver_id IS NOT NULL THEN
      UPDATE public.vehicles SET current_driver_id = NULL, updated_at = now()
        WHERE current_driver_id = NEW.current_driver_id AND id != NEW.id;
      UPDATE public.drivers SET current_vehicle_id = NEW.id, updated_at = now()
        WHERE id = NEW.current_driver_id AND COALESCE(current_vehicle_id,'00000000-0000-0000-0000-000000000000'::uuid) IS DISTINCT FROM NEW.id;
    END IF;
  END IF;

  IF TG_TABLE_NAME = 'drivers' THEN
    IF OLD.current_vehicle_id IS NOT NULL AND OLD.current_vehicle_id IS DISTINCT FROM NEW.current_vehicle_id THEN
      UPDATE public.vehicles SET current_driver_id = NULL, updated_at = now()
        WHERE id = OLD.current_vehicle_id AND current_driver_id = NEW.id;
    END IF;
    IF NEW.current_vehicle_id IS NOT NULL THEN
      UPDATE public.drivers SET current_vehicle_id = NULL, updated_at = now()
        WHERE current_vehicle_id = NEW.current_vehicle_id AND id != NEW.id;
      UPDATE public.vehicles SET current_driver_id = NEW.id, updated_at = now()
        WHERE id = NEW.current_vehicle_id AND COALESCE(current_driver_id,'00000000-0000-0000-0000-000000000000'::uuid) IS DISTINCT FROM NEW.id;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.clear_reimport_batch_data(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _dispatch_events integer := 0;
  _dispatch_stops integer := 0;
  _dispatch_trips integer := 0;
  _load_items integer := 0;
  _fiscal_documents integer := 0;
  _loads integer := 0;
  _freight_logs integer := 0;
  _drafts integer := 0;
BEGIN
  IF NOT public.is_tenant_admin(_tenant_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  DELETE FROM public.dispatch_events WHERE tenant_id = _tenant_id;
  GET DIAGNOSTICS _dispatch_events = ROW_COUNT;

  DELETE FROM public.dispatch_stops WHERE tenant_id = _tenant_id;
  GET DIAGNOSTICS _dispatch_stops = ROW_COUNT;

  DELETE FROM public.dispatch_trips WHERE tenant_id = _tenant_id;
  GET DIAGNOSTICS _dispatch_trips = ROW_COUNT;

  DELETE FROM public.load_items WHERE tenant_id = _tenant_id;
  GET DIAGNOSTICS _load_items = ROW_COUNT;

  DELETE FROM public.fiscal_documents WHERE tenant_id = _tenant_id;
  GET DIAGNOSTICS _fiscal_documents = ROW_COUNT;

  DELETE FROM public.loads WHERE tenant_id = _tenant_id;
  GET DIAGNOSTICS _loads = ROW_COUNT;

  DELETE FROM public.freight_calculation_log WHERE tenant_id = _tenant_id;
  GET DIAGNOSTICS _freight_logs = ROW_COUNT;

  DELETE FROM public.route_planning_drafts WHERE tenant_id = _tenant_id;
  GET DIAGNOSTICS _drafts = ROW_COUNT;

  RETURN jsonb_build_object(
    'dispatch_events', _dispatch_events,
    'dispatch_stops', _dispatch_stops,
    'dispatch_trips', _dispatch_trips,
    'load_items', _load_items,
    'fiscal_documents', _fiscal_documents,
    'loads', _loads,
    'freight_calculation_log', _freight_logs,
    'route_planning_drafts', _drafts
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.preview_reimport_cleanup_counts(_tenant_id uuid, _start_date date DEFAULT NULL::date, _end_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _doc_ids uuid[] := ARRAY[]::uuid[];
  _empty_load_ids uuid[] := ARRAY[]::uuid[];
  _dispatch_events integer := 0;
  _dispatch_stops integer := 0;
  _dispatch_trips integer := 0;
  _load_items integer := 0;
  _fiscal_documents integer := 0;
  _loads integer := 0;
  _freight_logs integer := 0;
  _drafts integer := 0;
BEGIN
  IF NOT public.is_tenant_admin(_tenant_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
  INTO _doc_ids
  FROM public.fiscal_documents
  WHERE tenant_id = _tenant_id
    AND (_start_date IS NULL OR issue_date >= _start_date)
    AND (_end_date IS NULL OR issue_date <= _end_date);

  SELECT COALESCE(array_agg(DISTINCT li.load_id), ARRAY[]::uuid[])
  INTO _empty_load_ids
  FROM public.load_items li
  WHERE li.tenant_id = _tenant_id
    AND li.load_id IS NOT NULL
    AND li.fiscal_document_id = ANY(_doc_ids)
    AND NOT EXISTS (
      SELECT 1
      FROM public.load_items remaining
      WHERE remaining.load_id = li.load_id
        AND (remaining.fiscal_document_id IS NULL OR remaining.fiscal_document_id <> ALL(_doc_ids))
    );

  SELECT count(*)::integer INTO _fiscal_documents FROM public.fiscal_documents WHERE id = ANY(_doc_ids);
  SELECT count(*)::integer INTO _load_items FROM public.load_items WHERE tenant_id = _tenant_id AND fiscal_document_id = ANY(_doc_ids);
  SELECT count(*)::integer INTO _loads FROM public.loads WHERE tenant_id = _tenant_id AND id = ANY(_empty_load_ids);
  SELECT count(*)::integer INTO _dispatch_trips FROM public.dispatch_trips WHERE tenant_id = _tenant_id AND load_id = ANY(_empty_load_ids);
  SELECT count(*)::integer INTO _dispatch_stops FROM public.dispatch_stops WHERE tenant_id = _tenant_id AND dispatch_trip_id IN (SELECT id FROM public.dispatch_trips WHERE tenant_id = _tenant_id AND load_id = ANY(_empty_load_ids));
  SELECT count(*)::integer INTO _dispatch_events FROM public.dispatch_events WHERE tenant_id = _tenant_id AND dispatch_trip_id IN (SELECT id FROM public.dispatch_trips WHERE tenant_id = _tenant_id AND load_id = ANY(_empty_load_ids));
  SELECT count(*)::integer INTO _freight_logs FROM public.freight_calculation_log WHERE tenant_id = _tenant_id AND entity_id = ANY(_doc_ids);
  SELECT count(*)::integer INTO _drafts FROM public.route_planning_drafts WHERE tenant_id = _tenant_id AND converted_load_id = ANY(_empty_load_ids);

  RETURN jsonb_build_object(
    'dispatch_events', _dispatch_events,
    'dispatch_stops', _dispatch_stops,
    'dispatch_trips', _dispatch_trips,
    'load_items', _load_items,
    'fiscal_documents', _fiscal_documents,
    'loads', _loads,
    'freight_calculation_log', _freight_logs,
    'route_planning_drafts', _drafts
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.clear_reimport_batch_data(_tenant_id uuid, _start_date date DEFAULT NULL::date, _end_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _doc_ids uuid[] := ARRAY[]::uuid[];
  _empty_load_ids uuid[] := ARRAY[]::uuid[];
  _dispatch_events integer := 0;
  _dispatch_stops integer := 0;
  _dispatch_trips integer := 0;
  _load_items integer := 0;
  _fiscal_documents integer := 0;
  _loads integer := 0;
  _freight_logs integer := 0;
  _drafts integer := 0;
BEGIN
  IF NOT public.is_tenant_admin(_tenant_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
  INTO _doc_ids
  FROM public.fiscal_documents
  WHERE tenant_id = _tenant_id
    AND (_start_date IS NULL OR issue_date >= _start_date)
    AND (_end_date IS NULL OR issue_date <= _end_date);

  SELECT COALESCE(array_agg(DISTINCT li.load_id), ARRAY[]::uuid[])
  INTO _empty_load_ids
  FROM public.load_items li
  WHERE li.tenant_id = _tenant_id
    AND li.load_id IS NOT NULL
    AND li.fiscal_document_id = ANY(_doc_ids)
    AND NOT EXISTS (
      SELECT 1
      FROM public.load_items remaining
      WHERE remaining.load_id = li.load_id
        AND (remaining.fiscal_document_id IS NULL OR remaining.fiscal_document_id <> ALL(_doc_ids))
    );

  DELETE FROM public.dispatch_events
  WHERE tenant_id = _tenant_id
    AND dispatch_trip_id IN (SELECT id FROM public.dispatch_trips WHERE tenant_id = _tenant_id AND load_id = ANY(_empty_load_ids));
  GET DIAGNOSTICS _dispatch_events = ROW_COUNT;

  DELETE FROM public.dispatch_stops
  WHERE tenant_id = _tenant_id
    AND dispatch_trip_id IN (SELECT id FROM public.dispatch_trips WHERE tenant_id = _tenant_id AND load_id = ANY(_empty_load_ids));
  GET DIAGNOSTICS _dispatch_stops = ROW_COUNT;

  DELETE FROM public.dispatch_trips WHERE tenant_id = _tenant_id AND load_id = ANY(_empty_load_ids);
  GET DIAGNOSTICS _dispatch_trips = ROW_COUNT;

  DELETE FROM public.load_items WHERE tenant_id = _tenant_id AND fiscal_document_id = ANY(_doc_ids);
  GET DIAGNOSTICS _load_items = ROW_COUNT;

  DELETE FROM public.freight_calculation_log WHERE tenant_id = _tenant_id AND entity_id = ANY(_doc_ids);
  GET DIAGNOSTICS _freight_logs = ROW_COUNT;

  DELETE FROM public.route_planning_drafts WHERE tenant_id = _tenant_id AND converted_load_id = ANY(_empty_load_ids);
  GET DIAGNOSTICS _drafts = ROW_COUNT;

  DELETE FROM public.fiscal_documents WHERE id = ANY(_doc_ids);
  GET DIAGNOSTICS _fiscal_documents = ROW_COUNT;

  DELETE FROM public.loads WHERE tenant_id = _tenant_id AND id = ANY(_empty_load_ids);
  GET DIAGNOSTICS _loads = ROW_COUNT;

  UPDATE public.loads l
  SET
    total_pallet_count = COALESCE((SELECT SUM(pallet_count) FROM public.load_items WHERE load_id = l.id), 0),
    total_weight_kg = COALESCE((SELECT SUM(weight_kg) FROM public.load_items WHERE load_id = l.id), 0),
    total_volume_m3 = COALESCE((SELECT SUM(volume_m3) FROM public.load_items WHERE load_id = l.id), 0),
    updated_at = now()
  WHERE l.tenant_id = _tenant_id
    AND EXISTS (SELECT 1 FROM public.load_items li WHERE li.load_id = l.id);

  RETURN jsonb_build_object(
    'dispatch_events', _dispatch_events,
    'dispatch_stops', _dispatch_stops,
    'dispatch_trips', _dispatch_trips,
    'load_items', _load_items,
    'fiscal_documents', _fiscal_documents,
    'loads', _loads,
    'freight_calculation_log', _freight_logs,
    'route_planning_drafts', _drafts
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_load_with_next_number(_tenant_id uuid, _origin text DEFAULT NULL::text, _destination text DEFAULT NULL::text, _vehicle_id uuid DEFAULT NULL::uuid, _driver_id uuid DEFAULT NULL::uuid, _trip_id text DEFAULT NULL::text, _notes text DEFAULT NULL::text)
 RETURNS loads
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _next_number text;
  _created public.loads;
BEGIN
  IF NOT public.is_tenant_member(_tenant_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text, 0));
  _next_number := public.peek_next_load_number(_tenant_id);

  INSERT INTO public.loads (
    tenant_id,
    load_number,
    origin,
    destination,
    vehicle_id,
    driver_id,
    trip_id,
    notes,
    created_by
  ) VALUES (
    _tenant_id,
    _next_number,
    _origin,
    _destination,
    _vehicle_id,
    _driver_id,
    _trip_id,
    _notes,
    auth.uid()
  )
  RETURNING * INTO _created;

  RETURN _created;
END;
$function$;

CREATE OR REPLACE FUNCTION public.peek_next_load_number(_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _next_number integer;
BEGIN
  IF NOT public.is_tenant_member(_tenant_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT GREATEST(
    COALESCE(MAX((regexp_match(load_number, '[0-9]+$'))[1]::integer), 1000) + 1,
    1001
  )
  INTO _next_number
  FROM public.loads
  WHERE tenant_id = _tenant_id;

  RETURN _next_number::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$;

CREATE OR REPLACE FUNCTION public.peek_next_pickup_number(_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _next integer;
BEGIN
  IF NOT public.is_tenant_member(_tenant_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT GREATEST(
    COALESCE(MAX((regexp_match(pickup_number, '[0-9]+$'))[1]::integer), 0) + 1,
    1
  ) INTO _next
  FROM public.pickup_orders
  WHERE tenant_id = _tenant_id;
  RETURN _next::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.next_nfse_number(_tenant_id uuid, _branch_code text DEFAULT 'MATRIZ'::text, _series text DEFAULT '1'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _next bigint;
BEGIN
  IF NOT public.is_tenant_member(_tenant_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  INSERT INTO public.nfse_sequences (tenant_id, branch_code, series, next_number)
  VALUES (_tenant_id, COALESCE(_branch_code,'MATRIZ'), COALESCE(_series,'1'), 1)
  ON CONFLICT (tenant_id, branch_code, series) DO NOTHING;

  UPDATE public.nfse_sequences
     SET next_number = next_number + 1,
         updated_at = now()
   WHERE tenant_id = _tenant_id
     AND branch_code = COALESCE(_branch_code,'MATRIZ')
     AND series = COALESCE(_series,'1')
  RETURNING next_number - 1 INTO _next;

  RETURN _next;
END;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_planned_route(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _tenant_id uuid := (_payload->>'tenant_id')::uuid;
  _vehicle_id uuid := NULLIF(_payload->>'vehicle_id','')::uuid;
  _driver_id uuid := NULLIF(_payload->>'driver_id','')::uuid;
  _planned_start_at timestamptz := NULLIF(_payload->>'planned_start_at','')::timestamptz;
  _route_name text := _payload->>'route_name';
  _planning_draft_id uuid := NULLIF(_payload->>'planning_draft_id','')::uuid;
  _load_ids uuid[]; _distinct_load_ids uuid[];
  _stops jsonb := COALESCE(_payload->'stops','[]'::jsonb);
  _trip_id uuid; _primary_load uuid;
  _stop jsonb; _stop_id uuid; _stop_order int;
  _valid_count int; _fd_id uuid; _fd_ids uuid[] := ARRAY[]::uuid[];
  _orphan_count int; _fd_load uuid;
  _lat numeric; _lng numeric;
BEGIN
  IF _tenant_id IS NULL
     OR (NOT public.is_tenant_admin(_tenant_id)
         AND NOT public.has_tenant_role(_tenant_id, 'operator'::app_role)) THEN
    RAISE EXCEPTION 'Não autorizado';
  END IF;
  IF _vehicle_id IS NULL THEN RAISE EXCEPTION 'Veículo obrigatório'; END IF;
  IF _driver_id IS NULL THEN RAISE EXCEPTION 'Motorista obrigatório'; END IF;
  IF _planned_start_at IS NULL THEN RAISE EXCEPTION 'Horário previsto de saída obrigatório'; END IF;

  SELECT ARRAY(SELECT jsonb_array_elements_text(_payload->'load_ids'))::uuid[] INTO _load_ids;
  IF _load_ids IS NULL OR array_length(_load_ids,1) IS NULL THEN
    RAISE EXCEPTION 'Lista de cargas vazia';
  END IF;
  SELECT ARRAY(SELECT DISTINCT unnest(_load_ids)) INTO _distinct_load_ids;
  IF array_length(_distinct_load_ids,1) <> array_length(_load_ids,1) THEN
    RAISE EXCEPTION 'Cargas duplicadas na lista';
  END IF;
  IF jsonb_array_length(_stops) = 0 THEN RAISE EXCEPTION 'Rota sem paradas'; END IF;

  SELECT count(*) INTO _valid_count
  FROM public.loads
  WHERE id = ANY(_load_ids) AND tenant_id = _tenant_id AND trip_id IS NULL;
  IF _valid_count <> array_length(_load_ids,1) THEN
    RAISE EXCEPTION 'Uma ou mais cargas são inválidas, inexistentes ou já despachadas';
  END IF;

  -- Collect FD ids referenced by stops
  _stop_order := 0;
  FOR _stop IN SELECT * FROM jsonb_array_elements(_stops) LOOP
    _stop_order := _stop_order + 1;
    IF COALESCE(trim(_stop->>'destination'),'') = '' THEN
      RAISE EXCEPTION 'Parada %: destino obrigatório', _stop_order;
    END IF;
    IF jsonb_typeof(_stop->'fiscal_document_ids') = 'array' THEN
      FOR _fd_id IN SELECT (jsonb_array_elements_text(_stop->'fiscal_document_ids'))::uuid LOOP
        _fd_ids := _fd_ids || _fd_id;
      END LOOP;
    END IF;
  END LOOP;

  -- 1) FDs must exist + belong to tenant
  IF array_length(_fd_ids,1) IS NOT NULL THEN
    SELECT count(*) INTO _orphan_count
    FROM unnest(_fd_ids) AS x(id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.fiscal_documents fd
      WHERE fd.id = x.id AND fd.tenant_id = _tenant_id
    );
    IF _orphan_count > 0 THEN
      RAISE EXCEPTION 'Documentos fiscais inexistentes ou de outro tenant: %', _orphan_count;
    END IF;

    -- 2) Every FD MUST belong to one of the dispatched loads via load_items
    SELECT count(*) INTO _orphan_count
    FROM unnest(_fd_ids) AS x(id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.load_items li
      WHERE li.fiscal_document_id = x.id
        AND li.load_id = ANY(_load_ids)
    );
    IF _orphan_count > 0 THEN
      RAISE EXCEPTION 'Documento fiscal não pertence às cargas despachadas: % doc(s)', _orphan_count;
    END IF;
  END IF;

  _primary_load := _load_ids[1];

  INSERT INTO public.dispatch_trips(
    tenant_id, vehicle_id, driver_id, load_id, status,
    planned_start_at, notes, created_by
  ) VALUES (
    _tenant_id, _vehicle_id, _driver_id, _primary_load, 'planned',
    _planned_start_at, COALESCE(_route_name,'Rota planejada'), auth.uid()
  ) RETURNING id INTO _trip_id;

  INSERT INTO public.dispatch_trip_loads(tenant_id, dispatch_trip_id, load_id)
  SELECT _tenant_id, _trip_id, unnest(_load_ids);

  UPDATE public.loads
    SET trip_id = _trip_id, vehicle_id = _vehicle_id, driver_id = _driver_id,
        status = 'loading', updated_at = now()
    WHERE id = ANY(_load_ids);

  _stop_order := 0;
  FOR _stop IN SELECT * FROM jsonb_array_elements(_stops) LOOP
    _stop_order := _stop_order + 1;
    _lat := NULLIF(_stop->>'latitude','')::numeric;
    _lng := NULLIF(_stop->>'longitude','')::numeric;

    INSERT INTO public.dispatch_stops(
      tenant_id, dispatch_trip_id, stop_order, destination, client_id,
      planned_arrival_at, estimated_departure_at, service_time_minutes,
      delivery_window_start, delivery_window_end,
      risk_level, risk_reason, notes, status,
      latitude, longitude
    ) VALUES (
      _tenant_id, _trip_id, _stop_order,
      _stop->>'destination',
      NULLIF(_stop->>'client_id','')::uuid,
      NULLIF(_stop->>'planned_arrival_at','')::timestamptz,
      NULLIF(_stop->>'estimated_departure_at','')::timestamptz,
      COALESCE((_stop->>'service_time_minutes')::int, 20),
      NULLIF(_stop->>'delivery_window_start','')::time,
      NULLIF(_stop->>'delivery_window_end','')::time,
      COALESCE(_stop->>'risk_level','normal'),
      _stop->>'risk_reason',
      _stop->>'notes',
      'pending',
      _lat, _lng
    ) RETURNING id INTO _stop_id;

    IF jsonb_typeof(_stop->'fiscal_document_ids') = 'array' THEN
      FOR _fd_id IN SELECT (jsonb_array_elements_text(_stop->'fiscal_document_ids'))::uuid LOOP
        SELECT load_id INTO _fd_load
        FROM public.load_items
        WHERE fiscal_document_id = _fd_id AND load_id = ANY(_load_ids)
        LIMIT 1;
        INSERT INTO public.dispatch_stop_documents(
          tenant_id, dispatch_stop_id, fiscal_document_id, load_id
        ) VALUES (_tenant_id, _stop_id, _fd_id, _fd_load)
        ON CONFLICT DO NOTHING;
      END LOOP;
    END IF;
  END LOOP;

  IF _planning_draft_id IS NOT NULL THEN
    UPDATE public.route_planning_drafts
      SET status='dispatched', converted_load_id=_primary_load, updated_at=now()
      WHERE id=_planning_draft_id AND tenant_id=_tenant_id;
  END IF;

  RETURN _trip_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.detect_payment_method(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  t text;
BEGIN
  IF p_text IS NULL OR length(trim(p_text)) = 0 THEN
    RETURN NULL;
  END IF;
  t := ' ' || upper(p_text) || ' ';
  -- ordem: específico -> genérico
  IF t ~ '\mPIX\M' THEN RETURN 'pix'; END IF;
  IF t ~ '\m(BOLETO|COBRAN[ÇC]A\s*BANC[ÁA]RIA|DUPLICATA)\M' THEN RETURN 'boleto'; END IF;
  IF t ~ '\m(TED|TRANSFER[ÊE]NCIA\s*BANC[ÁA]RIA|TRANSFER[ÊE]NCIA\s*ELETR[ÔO]NICA|TRANSFER[ÊE]NCIA)\M' THEN RETURN 'transferencia'; END IF;
  IF t ~ '\mCHEQUE\M' THEN RETURN 'cheque'; END IF;
  IF t ~ '\m(DINHEIRO|ESP[ÉE]CIE)\M' THEN RETURN 'dinheiro'; END IF;
  IF t ~ '\mCART[ÃA]O\s*(DE\s*)?CR[ÉE]DITO\M' THEN RETURN 'cartao_credito'; END IF;
  IF t ~ '\mCART[ÃA]O\s*(DE\s*)?D[ÉE]BITO\M' THEN RETURN 'cartao_debito'; END IF;
  IF t ~ '\m(FATURADO|FATURA\s*MENSAL)\M' THEN RETURN 'faturado'; END IF;
  IF t ~ '\m(A\s*PRAZO|APRAZO)\M' THEN RETURN 'a_prazo'; END IF;
  IF t ~ '\m(A\s*VISTA|[ÀA]\s*VISTA|AVISTA)\M' THEN RETURN 'a_vista'; END IF;
  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.revert_xml_loads_to_available(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _load_ids uuid[] := ARRAY[]::uuid[];
  _trip_ids uuid[] := ARRAY[]::uuid[];
  _dispatch_events_count integer := 0;
  _dispatch_stops_count integer := 0;
  _dispatch_stop_docs_count integer := 0;
  _dispatch_trip_loads_count integer := 0;
  _dispatch_trips_count integer := 0;
  _loads_updated_count integer := 0;
  _drafts_updated_count integer := 0;
BEGIN
  IF NOT public.is_tenant_member(_tenant_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- 1. Identificar loads com items de fiscal_documents (XML)
  SELECT COALESCE(array_agg(DISTINCT li.load_id), ARRAY[]::uuid[])
  INTO _load_ids
  FROM public.load_items li
  WHERE li.tenant_id = _tenant_id
    AND li.load_id IS NOT NULL
    AND li.fiscal_document_id IS NOT NULL;

  IF array_length(_load_ids, 1) IS NULL OR array_length(_load_ids, 1) = 0 THEN
    RETURN jsonb_build_object(
      'message', 'Nenhum load de XML encontrado para reverter',
      'loads_updated', 0,
      'trips_removed', 0,
      'stops_removed', 0,
      'events_removed', 0,
      'trip_loads_removed', 0,
      'stop_docs_removed', 0,
      'drafts_reset', 0
    );
  END IF;

  -- 2. Identificar trips associadas a esses loads
  SELECT COALESCE(array_agg(DISTINCT dt.id), ARRAY[]::uuid[])
  INTO _trip_ids
  FROM public.dispatch_trips dt
  WHERE dt.tenant_id = _tenant_id
    AND dt.load_id = ANY(_load_ids);

  -- 3. Remover dispatch_events das trips
  IF array_length(_trip_ids, 1) > 0 THEN
    DELETE FROM public.dispatch_events
    WHERE tenant_id = _tenant_id
      AND dispatch_trip_id = ANY(_trip_ids);
    GET DIAGNOSTICS _dispatch_events_count = ROW_COUNT;
  END IF;

  -- 4. Remover dispatch_stop_documents das stops das trips
  IF array_length(_trip_ids, 1) > 0 THEN
    DELETE FROM public.dispatch_stop_documents
    WHERE tenant_id = _tenant_id
      AND dispatch_stop_id IN (
        SELECT id FROM public.dispatch_stops
        WHERE tenant_id = _tenant_id AND dispatch_trip_id = ANY(_trip_ids)
      );
    GET DIAGNOSTICS _dispatch_stop_docs_count = ROW_COUNT;
  END IF;

  -- 5. Remover dispatch_stops das trips
  IF array_length(_trip_ids, 1) > 0 THEN
    DELETE FROM public.dispatch_stops
    WHERE tenant_id = _tenant_id
      AND dispatch_trip_id = ANY(_trip_ids);
    GET DIAGNOSTICS _dispatch_stops_count = ROW_COUNT;
  END IF;

  -- 6. Remover dispatch_trip_loads das trips
  IF array_length(_trip_ids, 1) > 0 THEN
    DELETE FROM public.dispatch_trip_loads
    WHERE tenant_id = _tenant_id
      AND dispatch_trip_id = ANY(_trip_ids);
    GET DIAGNOSTICS _dispatch_trip_loads_count = ROW_COUNT;
  END IF;

  -- 7. Remover dispatch_trips
  IF array_length(_trip_ids, 1) > 0 THEN
    DELETE FROM public.dispatch_trips
    WHERE tenant_id = _tenant_id
      AND id = ANY(_trip_ids);
    GET DIAGNOSTICS _dispatch_trips_count = ROW_COUNT;
  END IF;

  -- 8. Resetar loads: status='planned', limpar trip_id, vehicle_id, driver_id
  UPDATE public.loads
  SET status = 'planned',
      trip_id = null,
      vehicle_id = null,
      driver_id = null,
      updated_at = now()
  WHERE tenant_id = _tenant_id
    AND id = ANY(_load_ids)
    AND (status <> 'planned' OR trip_id IS NOT NULL OR vehicle_id IS NOT NULL OR driver_id IS NOT NULL);
  GET DIAGNOSTICS _loads_updated_count = ROW_COUNT;

  -- 9. Resetar route_planning_drafts convertidos de 'dispatched' para 'draft'
  UPDATE public.route_planning_drafts
  SET status = 'draft',
      converted_load_id = null,
      updated_at = now()
  WHERE tenant_id = _tenant_id
    AND status = 'dispatched'
    AND converted_load_id = ANY(_load_ids);
  GET DIAGNOSTICS _drafts_updated_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'message', 'XMLs revertidos para carga disponível com sucesso',
    'loads_updated', _loads_updated_count,
    'trips_removed', _dispatch_trips_count,
    'stops_removed', _dispatch_stops_count,
    'events_removed', _dispatch_events_count,
    'trip_loads_removed', _dispatch_trip_loads_count,
    'stop_docs_removed', _dispatch_stop_docs_count,
    'drafts_reset', _drafts_updated_count,
    'affected_load_ids', _load_ids,
    'removed_trip_ids', _trip_ids
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_active_trips_live(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _result jsonb;
BEGIN
  IF NOT (public.is_tenant_admin(_tenant_id) OR public.has_tenant_role(_tenant_id,'operator')) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_jsonb(t)), '[]'::jsonb) INTO _result
  FROM (
    SELECT
      dt.id AS trip_id,
      COALESCE(l.load_number, dt.id::text) AS trip_code,
      dt.vehicle_id, v.plate AS vehicle_plate, v.nickname AS vehicle_name,
      dt.driver_id, d.name AS driver_name, d.phone AS driver_phone,
      pl.lat, pl.lng, COALESCE(pl.speed, 0) AS speed_kmh, pl.heading,
      COALESCE(tls.state, 'normal') AS state,
      COALESCE(tls.severity, 'info') AS severity,
      tls.message AS status_message,
      tr.geometry_geojson AS route_geometry_geojson,
      tls.distance_from_route_meters, tls.delay_minutes, tls.stopped_minutes,
      tls.average_speed_kmh, tls.eta_next_stop_at,
      tls.last_signal_at, tls.last_signal_age_seconds,
      pl.captured_at AS position_captured_at,
      (SELECT row_to_jsonb(ns) FROM (
         SELECT s.id, s.stop_order AS sequence, s.destination AS client_name,
                s.planned_arrival_at, s.status
         FROM public.dispatch_stops s
         WHERE s.dispatch_trip_id = dt.id
           AND NOT (s.status = ANY(public.stop_terminal_statuses()))
         ORDER BY s.stop_order ASC LIMIT 1) ns) AS next_stop,
      (SELECT COALESCE(jsonb_agg(row_to_jsonb(ps) ORDER BY (ps.sequence)), '[]'::jsonb)
       FROM (SELECT s.id, s.stop_order AS sequence, s.destination AS client_name,
                    s.actual_arrival_at, s.actual_departure_at, s.status
             FROM public.dispatch_stops s
             WHERE s.dispatch_trip_id = dt.id
               AND s.status = ANY(public.stop_terminal_statuses())
             ORDER BY s.stop_order ASC) ps) AS previous_stops,
      (SELECT COALESCE(jsonb_agg(row_to_jsonb(pe) ORDER BY (pe.sequence)), '[]'::jsonb)
       FROM (SELECT s.id, s.stop_order AS sequence, s.destination AS client_name,
                    s.planned_arrival_at, s.status
             FROM public.dispatch_stops s
             WHERE s.dispatch_trip_id = dt.id
               AND NOT (s.status = ANY(public.stop_terminal_statuses()))
             ORDER BY s.stop_order ASC) pe) AS pending_stops,
      (SELECT COALESCE(jsonb_agg(row_to_jsonb(ld)), '[]'::jsonb)
       FROM (SELECT lo.id, lo.load_number AS code,
                    (SELECT count(*) FROM public.load_items li WHERE li.load_id = lo.id) AS documents_count,
                    lo.total_weight_kg AS total_weight, lo.status
             FROM public.dispatch_trip_loads dtl
             JOIN public.loads lo ON lo.id = dtl.load_id
             WHERE dtl.dispatch_trip_id = dt.id) ld) AS loads
    FROM public.dispatch_trips dt
    LEFT JOIN public.loads l ON l.id = dt.load_id
    LEFT JOIN public.vehicles v ON v.id = dt.vehicle_id
    LEFT JOIN public.drivers d ON d.id = dt.driver_id
    LEFT JOIN public.positions_last pl ON pl.vehicle_id = dt.vehicle_id AND pl.tenant_id = dt.tenant_id
    LEFT JOIN public.trip_live_status tls ON tls.trip_id = dt.id AND tls.tenant_id = dt.tenant_id
    LEFT JOIN public.trip_routes tr ON tr.trip_id = dt.id AND tr.tenant_id = dt.tenant_id AND tr.provider = 'osrm'
    WHERE dt.tenant_id = _tenant_id
      AND dt.status IN ('planned','loading','dispatched','in_progress')
  ) t;

  RETURN COALESCE(_result, '[]'::jsonb);
END; $function$;

CREATE OR REPLACE FUNCTION public.get_open_trip_alerts(_tenant_id uuid)
 RETURNS SETOF trip_alerts
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT * FROM public.trip_alerts
  WHERE tenant_id = _tenant_id AND status = 'open'
    AND (public.is_tenant_admin(_tenant_id) OR public.has_tenant_role(_tenant_id,'operator'))
  ORDER BY
    CASE severity WHEN 'critical' THEN 1 WHEN 'danger' THEN 2 WHEN 'warning' THEN 3
                  WHEN 'info' THEN 4 WHEN 'success' THEN 5 ELSE 6 END,
    opened_at DESC;
$function$;

CREATE OR REPLACE FUNCTION public.user_has_client_access(_client_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.client_portal_access
    WHERE user_id = auth.uid()
      AND client_id = _client_id
      AND active = true
  );
$function$;

CREATE OR REPLACE FUNCTION public.get_user_client_access(_tenant_id uuid)
 RETURNS TABLE(client_id uuid, access_type text, can_view_financial boolean, can_download_documents boolean, can_open_occurrences boolean, can_request_pickup boolean, can_view_vehicle_live boolean, can_view_driver_contact boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT cpa.client_id, cpa.access_type, cpa.can_view_financial, cpa.can_download_documents,
         cpa.can_open_occurrences, cpa.can_request_pickup, cpa.can_view_vehicle_live, cpa.can_view_driver_contact
  FROM public.client_portal_access cpa
  WHERE cpa.tenant_id = _tenant_id
    AND cpa.user_id = auth.uid()
    AND cpa.active = true;
$function$;

CREATE OR REPLACE FUNCTION public.get_client_portal_summary(_tenant_id uuid, _start_date date DEFAULT NULL::date, _end_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _result jsonb;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.client_portal_access
                WHERE tenant_id=_tenant_id AND user_id=auth.uid() AND active=true) THEN
    RETURN jsonb_build_object('in_transit',0,'delivered',0,'delayed',0,'pending_pickup',0,
      'pending_pod',0,'open_occurrences',0,'deliveries_today',0,'deliveries_tomorrow',0);
  END IF;

  WITH fds AS (
    SELECT fd.* FROM public.fiscal_documents fd
    WHERE fd.tenant_id = _tenant_id
      AND public.portal_user_can_access_fiscal_document(_tenant_id, fd.id)
      AND (_start_date IS NULL OR fd.issue_date >= _start_date)
      AND (_end_date   IS NULL OR fd.issue_date <= _end_date)
  )
  SELECT jsonb_build_object(
    'in_transit', (SELECT count(*) FROM fds WHERE status IN ('in_transit','loading','loaded')),
    'delivered',  (SELECT count(*) FROM fds WHERE status = 'delivered'),
    'delayed',    (SELECT count(*) FROM fds fd
                   JOIN public.dispatch_stop_documents dsd ON dsd.fiscal_document_id = fd.id
                   JOIN public.dispatch_stops ds ON ds.id = dsd.dispatch_stop_id
                   WHERE ds.status IN ('pending','arriving','arrived','in_progress')
                     AND ds.planned_arrival_at < now()),
    'pending_pickup', (SELECT count(DISTINCT po.id) FROM public.pickup_orders po
                       WHERE po.tenant_id = _tenant_id AND po.status IN ('pendente','vinculada')
                         AND public.portal_user_can_access_pickup_order(_tenant_id, po.id)),
    'pending_pod', (SELECT count(*) FROM fds fd WHERE fd.status='delivered'
                    AND NOT EXISTS (SELECT 1 FROM public.proof_of_delivery p
                                    WHERE p.fiscal_document_id = fd.id AND p.status IN ('uploaded','validated'))),
    'open_occurrences', (SELECT count(*) FROM public.operational_events oe
                         WHERE oe.tenant_id = _tenant_id AND oe.visible_to_client = true
                           AND oe.public_status = 'open'
                           AND public.portal_user_can_access_operational_event(_tenant_id, oe.id)),
    'deliveries_today', (SELECT count(*) FROM fds fd
                          JOIN public.dispatch_stop_documents dsd ON dsd.fiscal_document_id = fd.id
                          JOIN public.dispatch_stops ds ON ds.id = dsd.dispatch_stop_id
                          WHERE ds.planned_arrival_at::date = CURRENT_DATE),
    'deliveries_tomorrow', (SELECT count(*) FROM fds fd
                             JOIN public.dispatch_stop_documents dsd ON dsd.fiscal_document_id = fd.id
                             JOIN public.dispatch_stops ds ON ds.id = dsd.dispatch_stop_id
                             WHERE ds.planned_arrival_at::date = CURRENT_DATE + 1)
  ) INTO _result;
  RETURN _result;
END; $function$;

CREATE OR REPLACE FUNCTION public.search_client_portal_shipments(_tenant_id uuid, _search text DEFAULT NULL::text, _status text[] DEFAULT NULL::text[], _start_date date DEFAULT NULL::date, _end_date date DEFAULT NULL::date, _city text DEFAULT NULL::text, _state text DEFAULT NULL::text, _has_pod boolean DEFAULT NULL::boolean, _has_occurrence boolean DEFAULT NULL::boolean, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _rows jsonb; _total int; _search_norm text;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.client_portal_access
                WHERE tenant_id=_tenant_id AND user_id=auth.uid() AND active=true) THEN
    RETURN jsonb_build_object('rows','[]'::jsonb,'total',0);
  END IF;
  _search_norm := NULLIF(trim(_search), '');

  WITH base AS (
    SELECT fd.id AS fiscal_document_id, fd.tenant_id, fd.client_id,
      fd.invoice_number, fd.access_key, fd.issue_date, fd.document_type,
      fd.status AS document_status, fd.client_load_number, fd.reference_number,
      fd.remitter, fd.remitter_cnpj, fd.recipient, fd.recipient_cnpj,
      fd.recipient_city, fd.recipient_state, fd.recipient_neighborhood,
      fd.product_summary, fd.pallet_count, fd.weight_kg,
      CASE WHEN public.portal_user_can_view_financial(_tenant_id, fd.id) THEN fd.value END AS value,
      CASE WHEN public.portal_user_can_view_financial(_tenant_id, fd.id) THEN fd.freight_value END AS freight_value,
      fd.load_id, fd.pickup_order_id, fd.updated_at,
      l.load_number, l.status AS load_status, l.trip_id,
      ds.id AS dispatch_stop_id, ds.status AS stop_status,
      ds.planned_arrival_at, ds.actual_arrival_at, ds.actual_departure_at,
      EXISTS (SELECT 1 FROM public.proof_of_delivery p
              WHERE p.fiscal_document_id = fd.id AND p.status IN ('uploaded','validated')) AS has_pod,
      EXISTS (
        SELECT 1 FROM public.operational_events oe
        WHERE oe.tenant_id = _tenant_id AND oe.visible_to_client = true AND oe.public_status = 'open'
          AND (
            oe.fiscal_document_id = fd.id
            OR oe.dispatch_stop_id IN (SELECT dsd.dispatch_stop_id FROM public.dispatch_stop_documents dsd WHERE dsd.fiscal_document_id = fd.id)
            OR (oe.client_id IS NOT NULL AND oe.client_id = fd.client_id
                AND (oe.fiscal_document_id IS NULL OR oe.fiscal_document_id = fd.id))
          )
      ) AS has_open_occurrence,
      public.get_public_shipment_status(fd.id) AS public_status
    FROM public.fiscal_documents fd
    LEFT JOIN public.loads l ON l.id = fd.load_id
    LEFT JOIN public.dispatch_stop_documents dsd ON dsd.fiscal_document_id = fd.id
    LEFT JOIN public.dispatch_stops ds ON ds.id = dsd.dispatch_stop_id
    WHERE fd.tenant_id = _tenant_id
      AND public.portal_user_can_access_fiscal_document(_tenant_id, fd.id)
      AND (_start_date IS NULL OR fd.issue_date >= _start_date)
      AND (_end_date   IS NULL OR fd.issue_date <= _end_date)
      AND (_city  IS NULL OR fd.recipient_city  ILIKE _city)
      AND (_state IS NULL OR fd.recipient_state ILIKE _state)
      AND (_status IS NULL OR fd.status = ANY(_status))
      AND ( _search_norm IS NULL
            OR fd.invoice_number ILIKE '%' || _search_norm || '%'
            OR fd.access_key ILIKE '%' || _search_norm || '%'
            OR fd.client_load_number ILIKE '%' || _search_norm || '%'
            OR fd.reference_number ILIKE '%' || _search_norm || '%'
            OR fd.recipient ILIKE '%' || _search_norm || '%'
            OR fd.recipient_cnpj ILIKE '%' || _search_norm || '%'
            OR fd.recipient_city ILIKE '%' || _search_norm || '%'
            OR COALESCE(l.load_number,'') ILIKE '%' || _search_norm || '%' )
  ),
  filtered AS (
    SELECT * FROM base
    WHERE (_has_pod IS NULL OR has_pod = _has_pod)
      AND (_has_occurrence IS NULL OR has_open_occurrence = _has_occurrence)
  )
  SELECT COALESCE(jsonb_agg(row_to_jsonb(f) ORDER BY f.issue_date DESC NULLS LAST, f.updated_at DESC), '[]'::jsonb),
         (SELECT count(*) FROM filtered)
  INTO _rows, _total
  FROM (SELECT * FROM filtered ORDER BY issue_date DESC NULLS LAST, updated_at DESC
        LIMIT _limit OFFSET _offset) f;

  RETURN jsonb_build_object('rows', _rows, 'total', _total);
END; $function$;

CREATE OR REPLACE FUNCTION public.get_client_portal_shipment_detail(_fiscal_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _fd public.fiscal_documents; _tenant uuid; _can_financial boolean := false;
  _trip_id uuid; _stop_id uuid;
BEGIN
  SELECT * INTO _fd FROM public.fiscal_documents WHERE id = _fiscal_document_id;
  IF _fd.id IS NULL THEN RAISE EXCEPTION 'Documento não encontrado'; END IF;
  _tenant := _fd.tenant_id;
  IF NOT public.portal_user_can_access_fiscal_document(_tenant, _fiscal_document_id) THEN
    RAISE EXCEPTION 'Acesso negado a este documento';
  END IF;
  _can_financial := public.portal_user_can_view_financial(_tenant, _fiscal_document_id);

  SELECT ds.dispatch_trip_id, ds.id INTO _trip_id, _stop_id
  FROM public.dispatch_stop_documents dsd
  JOIN public.dispatch_stops ds ON ds.id = dsd.dispatch_stop_id
  WHERE dsd.fiscal_document_id = _fd.id LIMIT 1;

  RETURN jsonb_build_object(
    'document', jsonb_build_object(
      'id', _fd.id, 'invoice_number', _fd.invoice_number, 'access_key', _fd.access_key,
      'document_type', _fd.document_type, 'issue_date', _fd.issue_date, 'status', _fd.status,
      'client_load_number', _fd.client_load_number, 'reference_number', _fd.reference_number,
      'remitter', _fd.remitter, 'remitter_cnpj', _fd.remitter_cnpj,
      'recipient', _fd.recipient, 'recipient_cnpj', _fd.recipient_cnpj,
      'recipient_city', _fd.recipient_city, 'recipient_state', _fd.recipient_state,
      'recipient_neighborhood', _fd.recipient_neighborhood,
      'product_summary', _fd.product_summary, 'pallet_count', _fd.pallet_count, 'weight_kg', _fd.weight_kg,
      'value', CASE WHEN _can_financial THEN _fd.value END,
      'freight_value', CASE WHEN _can_financial THEN _fd.freight_value END
    ),
    'load', (SELECT jsonb_build_object('id', l.id, 'load_number', l.load_number, 'status', l.status,
              'origin', l.origin, 'destination', l.destination,
              'total_pallet_count', l.total_pallet_count, 'total_weight_kg', l.total_weight_kg)
             FROM public.loads l WHERE l.id = _fd.load_id),
    'trip', (SELECT jsonb_build_object('id', dt.id, 'status', dt.status,
              'planned_start_at', dt.planned_start_at, 'actual_start_at', dt.actual_start_at,
              'planned_end_at', dt.planned_end_at, 'actual_end_at', dt.actual_end_at)
             FROM public.dispatch_trips dt WHERE dt.id = _trip_id),
    'stop', (SELECT jsonb_build_object('id', ds.id, 'stop_order', ds.stop_order,
              'destination', ds.destination, 'status', ds.status,
              'planned_arrival_at', ds.planned_arrival_at,
              'actual_arrival_at', ds.actual_arrival_at,
              'actual_departure_at', ds.actual_departure_at)
             FROM public.dispatch_stops ds WHERE ds.id = _stop_id),
    'events', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', e.id, 'event_type', e.event_type,
                'notes', e.notes, 'created_at', e.created_at) ORDER BY e.created_at)
                FROM public.dispatch_events e WHERE e.dispatch_stop_id = _stop_id), '[]'::jsonb),
    'occurrences', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', oe.id, 'event_type', oe.event_type,
              'severity', oe.severity, 'description', oe.description,
              'public_status', oe.public_status, 'resolved_at', oe.resolved_at,
              'created_at', oe.created_at) ORDER BY oe.created_at DESC)
      FROM public.operational_events oe
      WHERE oe.tenant_id = _tenant
        AND oe.visible_to_client = true
        AND (
          oe.fiscal_document_id = _fd.id
          OR (oe.dispatch_stop_id IS NOT NULL AND oe.dispatch_stop_id = _stop_id)
          OR (oe.client_id IS NOT NULL AND oe.client_id = _fd.client_id
              AND oe.dispatch_stop_id IS NULL AND oe.fiscal_document_id IS NULL)
        )
    ), '[]'::jsonb),
    'proofs', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', p.id, 'proof_type', p.proof_type,
                'status', p.status, 'receiver_name', p.receiver_name, 'receiver_role', p.receiver_role,
                'received_at', p.received_at, 'validated_at', p.validated_at,
                'has_file', (p.storage_path IS NOT NULL)) ORDER BY p.created_at DESC)
                FROM public.proof_of_delivery p WHERE p.fiscal_document_id = _fd.id), '[]'::jsonb)
  );
END $function$;

CREATE OR REPLACE FUNCTION public.get_client_document_download_url(_proof_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _proof public.proof_of_delivery;
  _fd_client uuid;
  _can_download boolean;
BEGIN
  SELECT * INTO _proof FROM public.proof_of_delivery WHERE id = _proof_id;
  IF _proof.id IS NULL OR _proof.storage_path IS NULL THEN
    RAISE EXCEPTION 'Comprovante não encontrado';
  END IF;

  SELECT client_id INTO _fd_client FROM public.fiscal_documents WHERE id = _proof.fiscal_document_id;

  IF NOT public.user_has_client_access(_fd_client) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  SELECT bool_or(can_download_documents) INTO _can_download
  FROM public.client_portal_access
  WHERE user_id = auth.uid() AND tenant_id = _proof.tenant_id AND active = true;

  IF NOT COALESCE(_can_download, false) THEN
    RAISE EXCEPTION 'Usuário sem permissão para baixar documentos';
  END IF;

  RETURN jsonb_build_object('bucket', _proof.storage_bucket, 'path', _proof.storage_path);
END;
$function$;

CREATE OR REPLACE FUNCTION public._portal_user_client_ids(_tenant_id uuid)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(array_agg(DISTINCT client_id), ARRAY[]::uuid[])
  FROM public.client_portal_access
  WHERE tenant_id = _tenant_id
    AND user_id = auth.uid()
    AND active = true;
$function$;

CREATE OR REPLACE FUNCTION public._portal_user_has_perm(_tenant_id uuid, _client_id uuid, _perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ok boolean := false;
BEGIN
  EXECUTE format(
    'SELECT EXISTS(SELECT 1 FROM public.client_portal_access
       WHERE tenant_id = $1 AND user_id = $2 AND client_id = $3 AND active = true AND %I = true)',
    _perm
  ) INTO v_ok USING _tenant_id, auth.uid(), _client_id;
  RETURN v_ok;
END;
$function$;

CREATE OR REPLACE FUNCTION public.list_client_pickups(_tenant_id uuid, _status text DEFAULT NULL::text, _start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _limit integer DEFAULT 100, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, pickup_number text, remitter_name text, remitter_cnpj text, recipient_name text, pickup_at timestamp with time zone, status text, notes text, linked_docs_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    p.id, p.pickup_number, p.remitter_name, p.remitter_cnpj, p.recipient_name,
    p.pickup_at, p.status, p.notes,
    (SELECT COUNT(*) FROM public.fiscal_documents fd WHERE fd.pickup_order_id = p.id) AS linked_docs_count
  FROM public.pickup_orders p
  WHERE p.tenant_id = _tenant_id
    AND public.portal_user_can_access_pickup_order(_tenant_id, p.id)
    AND (_status IS NULL OR p.status = _status)
    AND (_start_date IS NULL OR p.pickup_at >= _start_date)
    AND (_end_date IS NULL OR p.pickup_at <= _end_date)
  ORDER BY p.pickup_at DESC NULLS LAST
  LIMIT _limit OFFSET _offset;
$function$;

CREATE OR REPLACE FUNCTION public.request_client_pickup(_tenant_id uuid, _client_id uuid, _pickup_at timestamp with time zone, _recipient_name text DEFAULT NULL::text, _notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid; v_num text;
  v_requester_name text; v_requester_doc text;
BEGIN
  IF NOT public._portal_user_has_perm(_tenant_id, _client_id, 'can_request_pickup') THEN
    RAISE EXCEPTION 'Permission denied: cannot request pickup for this client';
  END IF;

  SELECT COALESCE(c.trade_name, c.company_name, c.legal_name), c.tax_id
    INTO v_requester_name, v_requester_doc
  FROM public.clients c
  WHERE c.id = _client_id AND c.tenant_id = _tenant_id;
  IF v_requester_name IS NULL THEN RAISE EXCEPTION 'Client not found'; END IF;

  BEGIN
    SELECT public.peek_next_pickup_number(_tenant_id) INTO v_num;
  EXCEPTION WHEN OTHERS THEN
    v_num := to_char(now(), 'YYYYMMDDHH24MISS');
  END;

  INSERT INTO public.pickup_orders (
    tenant_id, pickup_number, remitter_client_id, remitter_name, remitter_cnpj,
    recipient_name, pickup_at, status, notes, created_by
  ) VALUES (
    _tenant_id, v_num, _client_id, v_requester_name, v_requester_doc,
    _recipient_name, _pickup_at, 'pendente', _notes, auth.uid()
  ) RETURNING id INTO v_id;

  PERFORM public._log_entity_audit(_tenant_id, 'pickup_order', v_id, 'create_by_client',
    NULL, jsonb_build_object('client_id', _client_id, 'pickup_at', _pickup_at), 'portal');

  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.list_client_documents(_tenant_id uuid, _document_type text DEFAULT NULL::text, _search text DEFAULT NULL::text, _start_date date DEFAULT NULL::date, _end_date date DEFAULT NULL::date, _limit integer DEFAULT 100, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, document_type text, invoice_number text, access_key text, issue_date date, remitter text, recipient text, recipient_city text, recipient_state text, value numeric, weight_kg numeric, status text, load_id uuid, client_id uuid, has_pod boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT fd.id, fd.document_type, fd.invoice_number, fd.access_key, fd.issue_date,
    fd.remitter, fd.recipient, fd.recipient_city, fd.recipient_state,
    CASE WHEN public.portal_user_can_view_financial(_tenant_id, fd.id) THEN fd.value END,
    fd.weight_kg, fd.status, fd.load_id, fd.client_id,
    EXISTS(SELECT 1 FROM public.proof_of_delivery pod WHERE pod.fiscal_document_id = fd.id)
  FROM public.fiscal_documents fd
  WHERE fd.tenant_id = _tenant_id
    AND public.portal_user_can_access_fiscal_document(_tenant_id, fd.id)
    AND (_document_type IS NULL OR fd.document_type = _document_type)
    AND (_start_date IS NULL OR fd.issue_date >= _start_date)
    AND (_end_date   IS NULL OR fd.issue_date <= _end_date)
    AND (_search IS NULL OR (
      fd.invoice_number ILIKE '%' || _search || '%'
      OR fd.access_key  ILIKE '%' || _search || '%'
      OR fd.remitter    ILIKE '%' || _search || '%'
      OR fd.recipient   ILIKE '%' || _search || '%'
    ))
  ORDER BY fd.issue_date DESC NULLS LAST, fd.created_at DESC
  LIMIT _limit OFFSET _offset;
$function$;

CREATE OR REPLACE FUNCTION public.list_client_occurrences(_tenant_id uuid, _severity text DEFAULT NULL::text, _resolved boolean DEFAULT NULL::boolean, _limit integer DEFAULT 100, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, load_id uuid, order_id uuid, event_type text, severity text, description text, public_status text, client_action_required boolean, client_opened boolean, client_resolution_note text, resolution text, resolved_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH allowed AS (SELECT unnest(public._portal_user_client_ids(_tenant_id)) AS client_id)
  SELECT
    oe.id, oe.load_id, oe.order_id, oe.event_type, oe.severity, oe.description,
    oe.public_status, oe.client_action_required, oe.client_opened,
    oe.client_resolution_note, oe.resolution, oe.resolved_at, oe.created_at
  FROM public.operational_events oe
  WHERE oe.tenant_id = _tenant_id
    AND oe.client_id IN (SELECT client_id FROM allowed)
    AND (oe.visible_to_client = true OR oe.client_opened = true)
    AND (_severity IS NULL OR oe.severity = _severity)
    AND (_resolved IS NULL OR (_resolved = true AND oe.resolved_at IS NOT NULL) OR (_resolved = false AND oe.resolved_at IS NULL))
  ORDER BY oe.created_at DESC
  LIMIT _limit OFFSET _offset;
$function$;

CREATE OR REPLACE FUNCTION public.create_client_occurrence(_tenant_id uuid, _client_id uuid, _event_type text, _description text, _severity text DEFAULT 'medium'::text, _load_id uuid DEFAULT NULL::uuid, _order_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_ok boolean;
BEGIN
  IF NOT public._portal_user_has_perm(_tenant_id, _client_id, 'can_open_occurrences') THEN
    RAISE EXCEPTION 'Permission denied: cannot open occurrences for this client';
  END IF;

  IF _load_id IS NOT NULL THEN
    SELECT EXISTS(
      SELECT 1 FROM public.loads l
      WHERE l.id = _load_id AND l.tenant_id = _tenant_id
        AND (
          EXISTS(SELECT 1 FROM public.fiscal_documents fd WHERE fd.load_id = l.id AND fd.client_id = _client_id)
          OR EXISTS(
            SELECT 1 FROM public.load_items li
            JOIN public.fiscal_documents fd ON fd.id = li.fiscal_document_id
            WHERE li.load_id = l.id AND fd.client_id = _client_id
          )
          OR EXISTS(
            SELECT 1 FROM public.load_items li
            JOIN public.orders o ON o.id = li.order_id
            WHERE li.load_id = l.id AND o.client_id = _client_id
          )
        )
    ) INTO v_ok;
    IF NOT v_ok THEN RAISE EXCEPTION 'access_denied: load does not belong to client/tenant'; END IF;
  END IF;

  IF _order_id IS NOT NULL THEN
    SELECT EXISTS(
      SELECT 1 FROM public.orders o
      WHERE o.id = _order_id AND o.tenant_id = _tenant_id AND o.client_id = _client_id
    ) INTO v_ok;
    IF NOT v_ok THEN RAISE EXCEPTION 'access_denied: order does not belong to client/tenant'; END IF;
  END IF;

  INSERT INTO public.operational_events (
    tenant_id, client_id, load_id, order_id, event_type, severity, description,
    visible_to_client, client_opened, public_status, created_by
  ) VALUES (
    _tenant_id, _client_id, _load_id, _order_id, _event_type, _severity, _description,
    true, true, 'reported_by_client', auth.uid()
  ) RETURNING id INTO v_id;

  PERFORM public._log_entity_audit(_tenant_id, 'operational_event', v_id, 'create_by_client',
    NULL, jsonb_build_object('client_id', _client_id, 'load_id', _load_id, 'severity', _severity), 'portal');

  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.get_client_pod_metadata(_tenant_id uuid, _pod_id uuid)
 RETURNS TABLE(storage_bucket text, storage_path text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT pod.storage_bucket, pod.storage_path
  FROM public.proof_of_delivery pod
  WHERE pod.id = _pod_id
    AND pod.tenant_id = _tenant_id
    AND public.portal_user_can_download_fiscal_document(_tenant_id, pod.fiscal_document_id);
$function$;

CREATE OR REPLACE FUNCTION public.list_client_pods(_tenant_id uuid, _status text DEFAULT NULL::text, _start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _limit integer DEFAULT 100, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, fiscal_document_id uuid, load_id uuid, invoice_number text, proof_type text, status text, has_file boolean, receiver_name text, receiver_document text, receiver_role text, received_at timestamp with time zone, validated_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT pod.id, pod.fiscal_document_id, pod.load_id, fd.invoice_number,
    pod.proof_type, pod.status, (pod.storage_path IS NOT NULL) AS has_file,
    pod.receiver_name, pod.receiver_document, pod.receiver_role,
    pod.received_at, pod.validated_at
  FROM public.proof_of_delivery pod
  JOIN public.fiscal_documents fd ON fd.id = pod.fiscal_document_id
  WHERE pod.tenant_id = _tenant_id
    AND public.portal_user_can_access_fiscal_document(_tenant_id, fd.id)
    AND (_status IS NULL OR pod.status = _status)
    AND (_start_date IS NULL OR pod.received_at >= _start_date)
    AND (_end_date   IS NULL OR pod.received_at <= _end_date)
  ORDER BY pod.received_at DESC NULLS LAST, pod.created_at DESC
  LIMIT _limit OFFSET _offset;
$function$;

CREATE OR REPLACE FUNCTION public._assert_driver_owns_trip(_trip_id uuid)
 RETURNS TABLE(driver_id uuid, tenant_id uuid, status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_driver uuid; v_tenant uuid; v_status text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;

  SELECT t.driver_id, t.tenant_id, t.status
    INTO v_driver, v_tenant, v_status
  FROM public.dispatch_trips t WHERE t.id = _trip_id;

  IF v_driver IS NULL THEN
    RAISE EXCEPTION 'trip_not_found' USING ERRCODE='P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.drivers d
    WHERE d.id = v_driver AND d.user_id = v_uid
      AND d.tenant_id = v_tenant AND d.active = true
  ) THEN
    RAISE EXCEPTION 'access_denied' USING ERRCODE='42501';
  END IF;

  IF v_status NOT IN ('planned','loading','dispatched','in_progress','completed') THEN
    RAISE EXCEPTION 'trip_not_active' USING ERRCODE='22023';
  END IF;

  driver_id := v_driver; tenant_id := v_tenant; status := v_status;
  RETURN NEXT;
END;
$function$;

CREATE OR REPLACE FUNCTION public.driver_mark_arrival(_stop_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_trip uuid; v_tenant uuid; v_event uuid; v_was_active boolean; v_status text;
BEGIN
  SELECT dispatch_trip_id, tenant_id, status INTO v_trip, v_tenant, v_status
  FROM public.dispatch_stops WHERE id = _stop_id;
  IF v_trip IS NULL THEN RAISE EXCEPTION 'stop_not_found'; END IF;
  PERFORM public._assert_driver_owns_trip(v_trip);

  IF v_status = ANY(public.stop_terminal_statuses()) THEN
    RAISE EXCEPTION 'stop_already_terminal';
  END IF;

  SELECT (status = 'in_progress') INTO v_was_active
  FROM public.dispatch_trips WHERE id = v_trip;

  UPDATE public.dispatch_stops
    SET status = 'arrived',
        actual_arrival_at = COALESCE(actual_arrival_at, now()),
        updated_at = now()
    WHERE id = _stop_id;

  INSERT INTO public.dispatch_events(tenant_id, dispatch_trip_id, dispatch_stop_id, event_type, payload, created_by)
  VALUES (v_tenant, v_trip, _stop_id, 'arrival', jsonb_build_object('source','driver_app'), auth.uid())
  RETURNING id INTO v_event;

  UPDATE public.dispatch_trips
    SET status='in_progress', actual_start_at = COALESCE(actual_start_at, now()), updated_at = now()
    WHERE id = v_trip AND status IN ('planned','loading','dispatched');

  IF NOT COALESCE(v_was_active, false) THEN
    UPDATE public.loads SET status='in_transit', updated_at=now()
    WHERE id IN (SELECT load_id FROM public.dispatch_trip_loads WHERE dispatch_trip_id = v_trip)
      AND status NOT IN ('delivered','cancelled');
    UPDATE public.loads l SET status='in_transit', updated_at=now()
    FROM public.dispatch_trips dt
    WHERE dt.id = v_trip AND l.id = dt.load_id
      AND l.status NOT IN ('delivered','cancelled','in_transit');
  END IF;

  RETURN v_event;
END; $function$;

CREATE OR REPLACE FUNCTION public.driver_create_event(_trip_id uuid, _event_type text, _payload jsonb DEFAULT '{}'::jsonb, _stop_id uuid DEFAULT NULL::uuid, _notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_id uuid;
BEGIN
  SELECT tenant_id INTO v_tenant FROM public._assert_driver_owns_trip(_trip_id);
  IF _event_type IS NULL OR length(_event_type) = 0 THEN RAISE EXCEPTION 'event_type_required'; END IF;
  IF _stop_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.dispatch_stops WHERE id=_stop_id AND dispatch_trip_id=_trip_id
  ) THEN RAISE EXCEPTION 'stop_not_in_trip'; END IF;
  INSERT INTO public.dispatch_events(tenant_id, dispatch_trip_id, dispatch_stop_id, event_type, payload, notes, created_by)
  VALUES (v_tenant, _trip_id, _stop_id, _event_type, COALESCE(_payload,'{}'::jsonb), _notes, auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$;

CREATE OR REPLACE FUNCTION public.driver_save_checklist(_trip_id uuid, _kind text, _payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_type text; v_id uuid;
BEGIN
  IF _kind NOT IN ('pre','post') THEN RAISE EXCEPTION 'invalid_kind'; END IF;
  v_type := CASE _kind WHEN 'pre' THEN 'checklist_pre' ELSE 'checklist_post' END;
  SELECT tenant_id INTO v_tenant FROM public._assert_driver_owns_trip(_trip_id);
  INSERT INTO public.dispatch_events(tenant_id, dispatch_trip_id, event_type, payload, created_by)
  VALUES (v_tenant, _trip_id, v_type, COALESCE(_payload,'{}'::jsonb), auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$;

CREATE OR REPLACE FUNCTION public.driver_finalize_delivery(_stop_id uuid, _receiver_name text, _signature_path text DEFAULT NULL::text, _photo_paths text[] DEFAULT ARRAY[]::text[], _receiver_document text DEFAULT NULL::text, _receiver_role text DEFAULT NULL::text, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trip uuid; v_tenant uuid; v_stop_status text;
  v_event uuid; v_pod_ids uuid[] := ARRAY[]::uuid[]; v_pod uuid;
  v_fd uuid; v_doc_load uuid; v_pending int; v_proof_type text;
BEGIN
  SELECT dispatch_trip_id, tenant_id, status
    INTO v_trip, v_tenant, v_stop_status
  FROM public.dispatch_stops WHERE id = _stop_id;
  IF v_trip IS NULL THEN RAISE EXCEPTION 'stop_not_found'; END IF;
  PERFORM public._assert_driver_owns_trip(v_trip);

  IF v_stop_status = ANY(public.stop_terminal_statuses()) THEN
    RAISE EXCEPTION 'stop_already_completed';
  END IF;
  IF _receiver_name IS NULL OR length(btrim(_receiver_name)) < 2 THEN
    RAISE EXCEPTION 'receiver_required';
  END IF;

  INSERT INTO public.dispatch_events(
    tenant_id, dispatch_trip_id, dispatch_stop_id, event_type, notes, payload, created_by
  ) VALUES (
    v_tenant, v_trip, _stop_id, 'delivery_delivered', _notes,
    jsonb_build_object(
      'event_subtype','entregue',
      'receiver_name', btrim(_receiver_name),
      'receiver_document', NULLIF(btrim(coalesce(_receiver_document,'')),''),
      'receiver_role', NULLIF(btrim(coalesce(_receiver_role,'')),''),
      'photo_paths', coalesce(to_jsonb(_photo_paths),'[]'::jsonb),
      'signature_path', _signature_path
    ),
    auth.uid()
  ) RETURNING id INTO v_event;

  UPDATE public.dispatch_stops
    SET status='delivered',
        actual_arrival_at = COALESCE(actual_arrival_at, now()),
        actual_departure_at = now(),
        notes = COALESCE(_notes, notes),
        updated_at = now()
    WHERE id = _stop_id;

  v_proof_type := CASE WHEN _signature_path IS NOT NULL THEN 'receiver_confirmation' ELSE 'delivery_photo' END;

  FOR v_fd, v_doc_load IN
    SELECT dsd.fiscal_document_id, COALESCE(dsd.load_id, fd.load_id)
    FROM public.dispatch_stop_documents dsd
    JOIN public.fiscal_documents fd ON fd.id = dsd.fiscal_document_id
    WHERE dsd.dispatch_stop_id = _stop_id
      AND dsd.tenant_id = v_tenant
      AND fd.tenant_id = v_tenant
  LOOP
    INSERT INTO public.proof_of_delivery(
      tenant_id, fiscal_document_id, load_id, dispatch_trip_id, dispatch_stop_id,
      proof_type, status, storage_bucket, storage_path,
      receiver_name, receiver_document, receiver_role, received_at, metadata
    ) VALUES (
      v_tenant, v_fd, v_doc_load, v_trip, _stop_id,
      v_proof_type, 'uploaded', 'receipts',
      COALESCE(_signature_path, CASE WHEN array_length(_photo_paths,1) > 0 THEN _photo_paths[1] END),
      btrim(_receiver_name),
      NULLIF(btrim(coalesce(_receiver_document,'')),''),
      NULLIF(btrim(coalesce(_receiver_role,'')),''),
      now(),
      jsonb_build_object('photo_paths', coalesce(to_jsonb(_photo_paths),'[]'::jsonb),
                         'signature_path', _signature_path,
                         'event_id', v_event)
    )
    ON CONFLICT (fiscal_document_id) DO UPDATE SET
      load_id = COALESCE(EXCLUDED.load_id, public.proof_of_delivery.load_id),
      status = EXCLUDED.status,
      storage_bucket = EXCLUDED.storage_bucket,
      storage_path = COALESCE(EXCLUDED.storage_path, public.proof_of_delivery.storage_path),
      receiver_name = EXCLUDED.receiver_name,
      receiver_document = COALESCE(EXCLUDED.receiver_document, public.proof_of_delivery.receiver_document),
      receiver_role = COALESCE(EXCLUDED.receiver_role, public.proof_of_delivery.receiver_role),
      received_at = EXCLUDED.received_at,
      dispatch_stop_id = EXCLUDED.dispatch_stop_id,
      dispatch_trip_id = EXCLUDED.dispatch_trip_id,
      proof_type = EXCLUDED.proof_type,
      metadata = public.proof_of_delivery.metadata || EXCLUDED.metadata,
      updated_at = now()
    RETURNING id INTO v_pod;
    v_pod_ids := v_pod_ids || v_pod;

    UPDATE public.fiscal_documents SET status='delivered', updated_at=now() WHERE id=v_fd;
  END LOOP;

  -- close trip when all stops in terminal state
  SELECT count(*) INTO v_pending FROM public.dispatch_stops
   WHERE dispatch_trip_id = v_trip
     AND NOT (status = ANY(public.stop_terminal_statuses()));
  IF v_pending = 0 THEN
    UPDATE public.dispatch_trips
       SET status='completed', actual_end_at=now(), updated_at=now()
     WHERE id = v_trip AND status <> 'completed';
    UPDATE public.loads SET status='delivered', updated_at=now()
     WHERE id IN (SELECT load_id FROM public.dispatch_trip_loads WHERE dispatch_trip_id = v_trip)
       AND status <> 'delivered';
    UPDATE public.loads l SET status='delivered', updated_at=now()
     FROM public.dispatch_trips dt
     WHERE dt.id = v_trip AND l.id = dt.load_id AND l.status <> 'delivered';
  END IF;

  RETURN jsonb_build_object('event_id', v_event, 'pod_ids', to_jsonb(v_pod_ids));
END; $function$;

CREATE OR REPLACE FUNCTION public.finalize_driver_delivery(_stop_id uuid, _receiver_name text, _signature_path text DEFAULT NULL::text, _photo_paths text[] DEFAULT ARRAY[]::text[], _fiscal_document_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.driver_finalize_delivery(_stop_id, _receiver_name, _signature_path, _photo_paths);
$function$;

CREATE OR REPLACE FUNCTION public._driver_trip_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT t.id FROM public.dispatch_trips t
  JOIN public.drivers d ON d.id = t.driver_id
  WHERE d.user_id = auth.uid() AND d.active = true;
$function$;

CREATE OR REPLACE FUNCTION public.get_user_portal_tenants()
 RETURNS TABLE(id uuid, name text, plan_key text, timezone text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT t.id, t.name, t.plan_key, t.timezone
  FROM public.tenants t
  WHERE t.id IN (
      SELECT tenant_id FROM public.tenant_memberships
      WHERE user_id = auth.uid() AND active = true
      UNION
      SELECT tenant_id FROM public.client_portal_access
      WHERE user_id = auth.uid() AND active = true
  );
$function$;

CREATE OR REPLACE FUNCTION public.portal_user_can_access_fiscal_document(_tenant_id uuid, _fiscal_document_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.fiscal_documents fd
    JOIN public.client_portal_access cpa
      ON cpa.tenant_id = fd.tenant_id
     AND cpa.user_id = auth.uid()
     AND cpa.active = true
    LEFT JOIN public.clients c ON c.id = cpa.client_id
    WHERE fd.id = _fiscal_document_id
      AND fd.tenant_id = _tenant_id
      AND (
        cpa.client_id = fd.client_id
        OR (cpa.access_type IN ('remitter','full','financial','documents_only')
            AND c.tax_id IS NOT NULL AND c.tax_id = fd.remitter_cnpj)
        OR (cpa.access_type IN ('recipient','full','financial','documents_only')
            AND c.tax_id IS NOT NULL AND c.tax_id = fd.recipient_cnpj)
        OR (cpa.access_type = 'full' AND c.tax_id IS NOT NULL
            AND c.tax_id IN (fd.remitter_cnpj, fd.recipient_cnpj))
      )
  );
$function$;

CREATE OR REPLACE FUNCTION public.portal_user_can_view_financial(_tenant_id uuid, _fiscal_document_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.fiscal_documents fd
    JOIN public.client_portal_access cpa
      ON cpa.tenant_id = fd.tenant_id AND cpa.user_id = auth.uid()
     AND cpa.active = true AND cpa.can_view_financial = true
    LEFT JOIN public.clients c ON c.id = cpa.client_id
    WHERE fd.id = _fiscal_document_id AND fd.tenant_id = _tenant_id
      AND (
        cpa.client_id = fd.client_id
        OR (cpa.access_type IN ('remitter','full','financial','documents_only')
            AND c.tax_id IS NOT NULL AND c.tax_id = fd.remitter_cnpj)
        OR (cpa.access_type IN ('recipient','full','financial','documents_only')
            AND c.tax_id IS NOT NULL AND c.tax_id = fd.recipient_cnpj)
        OR (cpa.access_type = 'full' AND c.tax_id IS NOT NULL
            AND c.tax_id IN (fd.remitter_cnpj, fd.recipient_cnpj))
      )
  );
$function$;

CREATE OR REPLACE FUNCTION public.driver_create_operational_occurrence(_trip_id uuid, _event_type text, _description text, _severity text DEFAULT 'medium'::text, _stop_id uuid DEFAULT NULL::uuid, _client_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_driver uuid; v_tenant uuid; v_trip uuid := _trip_id; v_stop uuid := _stop_id;
  v_load uuid; v_vehicle uuid; v_client uuid := _client_id; v_fd uuid;
  v_visible boolean; v_id uuid;
  v_internal_types text[] := ARRAY['mechanical','fuel_low','driver_internal','rest','admin'];
BEGIN
  SELECT id, tenant_id INTO v_driver, v_tenant FROM public.drivers
    WHERE user_id = auth.uid() AND active = true LIMIT 1;
  IF v_driver IS NULL THEN RAISE EXCEPTION 'Motorista não autenticado'; END IF;

  IF v_trip IS NULL THEN
    SELECT id INTO v_trip FROM public.dispatch_trips
      WHERE driver_id = v_driver
        AND status IN ('planned','loading','in_progress','en_route','arrived')
      ORDER BY COALESCE(actual_start_at, planned_start_at) DESC NULLS LAST LIMIT 1;
  END IF;

  IF v_trip IS NOT NULL AND NOT public.driver_owns_trip(v_trip) THEN
    RAISE EXCEPTION 'Viagem não pertence ao motorista';
  END IF;

  IF v_trip IS NOT NULL THEN
    SELECT load_id, vehicle_id INTO v_load, v_vehicle FROM public.dispatch_trips WHERE id = v_trip;
  END IF;

  IF v_stop IS NULL AND v_trip IS NOT NULL THEN
    SELECT id INTO v_stop FROM public.dispatch_stops
      WHERE dispatch_trip_id = v_trip AND status IN ('arrived','servicing','in_progress')
      ORDER BY stop_order LIMIT 1;
    IF v_stop IS NULL THEN
      SELECT id INTO v_stop FROM public.dispatch_stops
        WHERE dispatch_trip_id = v_trip
          AND status NOT IN (SELECT unnest(public.stop_terminal_statuses()))
        ORDER BY stop_order LIMIT 1;
    END IF;
  END IF;

  IF v_stop IS NOT NULL THEN
    SELECT dsd.fiscal_document_id INTO v_fd
      FROM public.dispatch_stop_documents dsd WHERE dsd.dispatch_stop_id = v_stop LIMIT 1;
    IF v_client IS NULL AND v_fd IS NOT NULL THEN
      SELECT client_id INTO v_client FROM public.fiscal_documents WHERE id = v_fd;
    END IF;
  END IF;

  v_visible := (v_client IS NOT NULL OR v_fd IS NOT NULL)
               AND NOT (_event_type = ANY(v_internal_types));

  INSERT INTO public.dispatch_events(tenant_id, dispatch_trip_id, dispatch_stop_id, event_type, payload, notes, created_by)
  VALUES (v_tenant, v_trip, v_stop, 'occurrence',
          jsonb_build_object('source','driver_app','severity',_severity,'kind',_event_type),
          _description, auth.uid());

  INSERT INTO public.operational_events(
    tenant_id, client_id, load_id, vehicle_id, driver_id,
    dispatch_trip_id, dispatch_stop_id, fiscal_document_id,
    event_type, severity, description,
    visible_to_client, public_status, created_by
  ) VALUES (
    v_tenant, v_client, v_load, v_vehicle, v_driver,
    v_trip, v_stop, v_fd,
    _event_type, _severity, _description,
    v_visible, 'reported_by_driver', auth.uid()
  ) RETURNING id INTO v_id;
  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.portal_user_can_download_fiscal_document(_tenant_id uuid, _fiscal_document_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.fiscal_documents fd
    JOIN public.client_portal_access cpa
      ON cpa.tenant_id = fd.tenant_id
     AND cpa.user_id = auth.uid()
     AND cpa.active = true
     AND cpa.can_download_documents = true
    LEFT JOIN public.clients c ON c.id = cpa.client_id
    WHERE fd.id = _fiscal_document_id
      AND fd.tenant_id = _tenant_id
      AND (
        cpa.client_id = fd.client_id
        OR (cpa.access_type IN ('remitter','full','financial','documents_only')
            AND c.tax_id IS NOT NULL AND c.tax_id = fd.remitter_cnpj)
        OR (cpa.access_type IN ('recipient','full','financial','documents_only')
            AND c.tax_id IS NOT NULL AND c.tax_id = fd.recipient_cnpj)
        OR (cpa.access_type = 'full' AND c.tax_id IS NOT NULL
            AND c.tax_id IN (fd.remitter_cnpj, fd.recipient_cnpj))
      )
  );
$function$;

CREATE OR REPLACE FUNCTION public.stop_terminal_statuses()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT ARRAY[
    'completed','delivered','cancelled','skipped',
    'refused','returned','partial_delivery','failed'
  ]::text[];
$function$;

CREATE OR REPLACE FUNCTION public.driver_register_departure(_stop_id uuid, _notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_trip uuid; v_tenant uuid; v_event uuid;
BEGIN
  SELECT dispatch_trip_id, tenant_id INTO v_trip, v_tenant
  FROM public.dispatch_stops WHERE id = _stop_id;
  IF v_trip IS NULL THEN RAISE EXCEPTION 'stop_not_found'; END IF;
  PERFORM public._assert_driver_owns_trip(v_trip);

  UPDATE public.dispatch_stops
    SET actual_departure_at = COALESCE(actual_departure_at, now()),
        updated_at = now()
    WHERE id = _stop_id;

  INSERT INTO public.dispatch_events(tenant_id, dispatch_trip_id, dispatch_stop_id, event_type, payload, notes, created_by)
  VALUES (v_tenant, v_trip, _stop_id, 'departure',
          jsonb_build_object('source','driver_app'), _notes, auth.uid())
  RETURNING id INTO v_event;

  RETURN v_event;
END; $function$;

CREATE OR REPLACE FUNCTION public._block_client_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.role = 'client' THEN
    RAISE EXCEPTION 'role_client_not_allowed_in_memberships'
      USING HINT = 'Use client_portal_access para acesso de cliente externo.',
            ERRCODE = '22023';
  END IF;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public.is_user_internal_role(_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    from public.tenant_memberships
    where user_id = auth.uid()
      and tenant_id = _tenant_id
      and role IN ('owner', 'admin', 'operator')
      and active = true
  )
$function$;

CREATE OR REPLACE FUNCTION public._driver_load_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT dtl.load_id FROM public.dispatch_trip_loads dtl
  JOIN public.dispatch_trips dt ON dt.id = dtl.dispatch_trip_id
  JOIN public.drivers d ON d.id = dt.driver_id
  JOIN public.loads l ON l.id = dtl.load_id
  WHERE d.user_id = auth.uid() AND d.active = true AND l.on_hold = false
  UNION
  SELECT l.id FROM public.loads l
  JOIN public.dispatch_trips dt ON dt.id = l.trip_id
  JOIN public.drivers d ON d.id = dt.driver_id
  WHERE d.user_id = auth.uid() AND d.active = true AND l.on_hold = false
  UNION
  SELECT l.id FROM public.loads l
  JOIN public.drivers d ON d.id = l.driver_id
  WHERE d.user_id = auth.uid() AND d.active = true AND l.on_hold = false;
$function$;

CREATE OR REPLACE FUNCTION public._driver_fiscal_document_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT id FROM public.fiscal_documents WHERE load_id IN (SELECT public._driver_load_ids());
$function$;

CREATE OR REPLACE FUNCTION public._driver_order_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT lo.order_id FROM public.load_orders lo
  WHERE lo.load_id IN (SELECT public._driver_load_ids());
$function$;

CREATE OR REPLACE FUNCTION public._driver_client_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT client_id FROM public.fiscal_documents
   WHERE load_id IN (SELECT public._driver_load_ids()) AND client_id IS NOT NULL
  UNION
  SELECT DISTINCT client_id FROM public.orders
   WHERE id IN (SELECT public._driver_order_ids()) AND client_id IS NOT NULL;
$function$;

CREATE OR REPLACE FUNCTION public._driver_pickup_order_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT pickup_order_id FROM public.fiscal_documents
   WHERE load_id IN (SELECT public._driver_load_ids()) AND pickup_order_id IS NOT NULL;
$function$;

CREATE OR REPLACE FUNCTION public.portal_user_can_access_pickup_order(_tenant_id uuid, _pickup_order_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.pickup_orders po
    JOIN public.client_portal_access cpa
      ON cpa.tenant_id = po.tenant_id AND cpa.user_id = auth.uid() AND cpa.active = true
    LEFT JOIN public.clients c ON c.id = cpa.client_id
    WHERE po.id = _pickup_order_id AND po.tenant_id = _tenant_id
      AND (
        cpa.client_id = po.remitter_client_id
        OR (cpa.access_type IN ('remitter','full','documents_only','financial')
            AND c.tax_id IS NOT NULL AND c.tax_id = po.remitter_cnpj)
      )
  );
$function$;

CREATE OR REPLACE FUNCTION public.portal_user_can_access_operational_event(_tenant_id uuid, _event_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.operational_events oe
    WHERE oe.id = _event_id AND oe.tenant_id = _tenant_id AND oe.visible_to_client = true
      AND (
        (oe.client_id IS NOT NULL
         AND oe.client_id IN (SELECT unnest(public._portal_user_client_ids(_tenant_id))))
        OR (oe.load_id IS NOT NULL AND EXISTS (
              SELECT 1 FROM public.fiscal_documents fd
              WHERE fd.load_id = oe.load_id
                AND public.portal_user_can_access_fiscal_document(_tenant_id, fd.id)))
      )
  );
$function$;

