CREATE OR REPLACE FUNCTION public._log_entity_audit(_tenant_id uuid, _entity_type text, _entity_id uuid, _action text, _old jsonb DEFAULT NULL::jsonb, _new jsonb DEFAULT NULL::jsonb, _source text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text;
BEGIN
  SELECT role::text INTO v_role FROM public.tenant_memberships
   WHERE tenant_id = _tenant_id AND user_id = auth.uid() AND active = true
   ORDER BY CASE role::text WHEN 'owner' THEN 1 WHEN 'admin' THEN 2 WHEN 'operator' THEN 3 ELSE 4 END
   LIMIT 1;
  INSERT INTO public.entity_audit_log(
    tenant_id, entity_type, entity_id, action,
    old_data, new_data, actor_user_id, actor_role, source
  ) VALUES (
    _tenant_id, _entity_type, _entity_id, _action,
    _old, _new, auth.uid(), v_role, _source
  );
END $function$;

CREATE OR REPLACE FUNCTION public.driver_update_stop_status(_stop_id uuid, _new_status text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trip uuid; v_tenant uuid; v_event_type text; v_event uuid; v_current text;
  v_terminal text[] := public.stop_terminal_statuses();
  v_pending int; v_load_id uuid;
  v_load_terminals text[]; v_new_load_status text;
  v_doc_ids uuid[]; v_doc_status text; v_load_ids uuid[] := ARRAY[]::uuid[];
  v_trip_completed boolean := false;
BEGIN
  IF _new_status NOT IN (
    'partial_delivery','refused','damaged','returned','skipped',
    'cancelled','failed','delivered','completed','arrived','departed'
  ) THEN RAISE EXCEPTION 'invalid_status'; END IF;

  SELECT dispatch_trip_id, tenant_id, status INTO v_trip, v_tenant, v_current
  FROM public.dispatch_stops WHERE id = _stop_id;
  IF v_trip IS NULL THEN RAISE EXCEPTION 'stop_not_found'; END IF;
  PERFORM public._assert_driver_owns_trip(v_trip);

  IF v_current = ANY(v_terminal) AND _new_status <> v_current THEN
    RAISE EXCEPTION 'stop_already_terminal';
  END IF;

  v_event_type := 'stop_' || _new_status;

  UPDATE public.dispatch_stops
    SET status = _new_status,
        notes = COALESCE(_reason, notes),
        actual_arrival_at = COALESCE(actual_arrival_at,
          CASE WHEN _new_status IN ('arrived','delivered','completed','refused','returned','partial_delivery','failed') THEN now() END),
        actual_departure_at = CASE
          WHEN _new_status = 'arrived' THEN actual_departure_at
          ELSE COALESCE(actual_departure_at, now())
        END,
        updated_at = now()
    WHERE id = _stop_id;

  INSERT INTO public.dispatch_events(tenant_id, dispatch_trip_id, dispatch_stop_id, event_type, payload, notes, created_by)
  VALUES (v_tenant, v_trip, _stop_id, v_event_type,
          jsonb_build_object('source','driver_app','new_status',_new_status,'reason',_reason),
          _reason, auth.uid())
  RETURNING id INTO v_event;

  v_doc_status := CASE _new_status
    WHEN 'refused' THEN 'refused'
    WHEN 'returned' THEN 'returned'
    WHEN 'partial_delivery' THEN 'partial_delivery'
    WHEN 'failed' THEN 'failed'
    WHEN 'skipped' THEN 'not_delivered'
    WHEN 'cancelled' THEN 'cancelled'
    WHEN 'delivered' THEN 'delivered'
    WHEN 'completed' THEN 'delivered'
    ELSE NULL
  END;

  SELECT COALESCE(array_agg(DISTINCT dsd.fiscal_document_id), ARRAY[]::uuid[])
    INTO v_doc_ids
  FROM public.dispatch_stop_documents dsd
  WHERE dsd.dispatch_stop_id = _stop_id;

  IF v_doc_status IS NOT NULL AND array_length(v_doc_ids, 1) IS NOT NULL THEN
    UPDATE public.fiscal_documents
      SET status = v_doc_status, updated_at = now()
      WHERE id = ANY(v_doc_ids) AND tenant_id = v_tenant
        AND status NOT IN ('delivered','returned','refused','partial_delivery','failed','cancelled');
    PERFORM public._log_entity_audit(v_tenant, 'fiscal_document', x,
      'status_change_by_driver', NULL,
      jsonb_build_object('new_status', v_doc_status, 'stop_id', _stop_id), 'driver_app')
      FROM unnest(v_doc_ids) AS x;
  END IF;

  PERFORM public._log_entity_audit(v_tenant, 'dispatch_stop', _stop_id, 'status_change',
    jsonb_build_object('status', v_current), jsonb_build_object('status', _new_status, 'reason', _reason), 'driver_app');

  IF _new_status = ANY(v_terminal) THEN
    SELECT count(*) INTO v_pending FROM public.dispatch_stops
     WHERE dispatch_trip_id = v_trip AND NOT (status = ANY(v_terminal));

    IF v_pending = 0 THEN
      UPDATE public.dispatch_trips
         SET status='completed', actual_end_at=now(), updated_at=now()
       WHERE id = v_trip AND status <> 'completed';
      v_trip_completed := true;

      FOR v_load_id IN
        SELECT DISTINCT load_id FROM (
          SELECT dtl.load_id FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id = v_trip
          UNION
          SELECT l.id FROM public.loads l WHERE l.trip_id = v_trip
        ) x
      LOOP
        v_load_ids := v_load_ids || v_load_id;
        SELECT array_agg(DISTINCT ds.status) INTO v_load_terminals
          FROM public.dispatch_stops ds
          JOIN public.dispatch_stop_documents dsd ON dsd.dispatch_stop_id = ds.id
          JOIN public.fiscal_documents fd ON fd.id = dsd.fiscal_document_id
         WHERE fd.load_id = v_load_id AND ds.dispatch_trip_id = v_trip;

        v_new_load_status := CASE
          WHEN v_load_terminals IS NULL THEN 'delivered'
          WHEN 'partial_delivery' = ANY(v_load_terminals) THEN 'partial_delivery'
          WHEN 'returned' = ANY(v_load_terminals) THEN 'returned'
          WHEN 'refused'  = ANY(v_load_terminals) THEN 'refused'
          WHEN 'failed'   = ANY(v_load_terminals) THEN 'failed'
          WHEN 'cancelled' = ANY(v_load_terminals) AND array_length(v_load_terminals,1)=1 THEN 'cancelled'
          ELSE 'delivered'
        END;

        UPDATE public.loads
           SET status = v_new_load_status, updated_at = now()
         WHERE id = v_load_id
           AND status NOT IN ('delivered','cancelled','returned','refused','partial_delivery','failed');

        PERFORM public._log_entity_audit(v_tenant, 'load', v_load_id, 'status_change',
          NULL, jsonb_build_object('new_status', v_new_load_status, 'trip_id', v_trip), 'driver_app');
      END LOOP;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'event_id', v_event,
    'updated_stop_id', _stop_id,
    'updated_document_ids', COALESCE(to_jsonb(v_doc_ids), '[]'::jsonb),
    'updated_load_ids', COALESCE(to_jsonb(v_load_ids), '[]'::jsonb),
    'trip_completed', v_trip_completed
  );
END $function$;

CREATE OR REPLACE FUNCTION public._load_is_locked(_load_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.loads l
    WHERE l.id = _load_id
      AND (l.status IN ('in_transit','delivered','partial_delivery','returned','refused','failed','cancelled')
           OR EXISTS (SELECT 1 FROM public.dispatch_trips dt
                       WHERE dt.load_id = l.id AND dt.status IN ('in_progress','completed'))
           OR EXISTS (SELECT 1 FROM public.dispatch_trip_loads dtl
                       JOIN public.dispatch_trips dt ON dt.id = dtl.dispatch_trip_id
                       WHERE dtl.load_id = l.id AND dt.status IN ('in_progress','completed')))
  );
$function$;

CREATE OR REPLACE FUNCTION public.assign_fiscal_documents_to_load(_tenant_id uuid, _load_id uuid, _document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int := 0;
  v_requested int := 0;
  v_blocked int := 0;
  v_doc_ids uuid[];
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF _load_id IS NULL OR _document_ids IS NULL OR array_length(_document_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'invalid_input';
  END IF;

  SELECT array_agg(DISTINCT d.id)
    INTO v_doc_ids
  FROM unnest(_document_ids) AS d(id)
  WHERE d.id IS NOT NULL;

  IF v_doc_ids IS NULL OR array_length(v_doc_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'invalid_input';
  END IF;

  IF public._load_is_locked(_load_id) THEN
    RAISE EXCEPTION 'load_locked';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.loads l
    WHERE l.id = _load_id
      AND l.tenant_id = _tenant_id
  ) THEN
    RAISE EXCEPTION 'load_not_found';
  END IF;

  SELECT count(*)::int
    INTO v_requested
  FROM unnest(v_doc_ids) AS d(id);

  SELECT count(*)::int
    INTO v_blocked
  FROM public.fiscal_documents fd
  WHERE fd.id = ANY(v_doc_ids)
    AND fd.tenant_id = _tenant_id
    AND fd.load_id IS NOT NULL
    AND fd.load_id <> _load_id;

  IF v_blocked > 0 THEN
    RAISE EXCEPTION 'document_already_linked';
  END IF;

  UPDATE public.fiscal_documents
    SET load_id = _load_id,
        updated_at = now()
    WHERE id = ANY(v_doc_ids)
      AND tenant_id = _tenant_id
      AND (load_id IS NULL OR load_id = _load_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count <> v_requested THEN
    RAISE EXCEPTION 'document_link_count_mismatch: expected %, updated %', v_requested, v_count;
  END IF;

  INSERT INTO public.load_items (
    tenant_id,
    load_id,
    fiscal_document_id,
    item_description,
    pallet_count,
    weight_kg,
    volume_m3
  )
  SELECT _tenant_id,
         _load_id,
         fd.id,
         COALESCE(NULLIF(fd.product_summary, ''), 'Documento ' || COALESCE(fd.invoice_number, fd.id::text)),
         COALESCE(fd.pallet_count, 0),
         COALESCE(fd.weight_kg, 0),
         0
  FROM public.fiscal_documents fd
  WHERE fd.id = ANY(v_doc_ids)
    AND fd.tenant_id = _tenant_id
    AND fd.load_id = _load_id
    AND NOT EXISTS (
      SELECT 1
      FROM public.load_items li
      WHERE li.fiscal_document_id = fd.id
        AND li.load_id = _load_id
    );

  PERFORM public._log_entity_audit(
    _tenant_id,
    'load',
    _load_id,
    'assign_documents',
    NULL,
    jsonb_build_object('document_ids', to_jsonb(v_doc_ids), 'updated', v_count),
    'composition_rpc'
  );

  RETURN jsonb_build_object('updated', v_count, 'load_id', _load_id);
END $function$;

CREATE OR REPLACE FUNCTION public.remove_fiscal_documents_from_load(_tenant_id uuid, _load_id uuid, _document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF public._load_is_locked(_load_id) THEN RAISE EXCEPTION 'load_locked'; END IF;

  DELETE FROM public.load_items
    WHERE load_id = _load_id AND fiscal_document_id = ANY(_document_ids) AND tenant_id = _tenant_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  UPDATE public.fiscal_documents
    SET load_id = NULL, updated_at = now()
    WHERE id = ANY(_document_ids) AND tenant_id = _tenant_id AND load_id = _load_id;

  PERFORM public._log_entity_audit(_tenant_id, 'load', _load_id, 'remove_documents',
    NULL, jsonb_build_object('document_ids', to_jsonb(_document_ids)), 'composition_rpc');

  RETURN jsonb_build_object('removed', v_count, 'load_id', _load_id);
END $function$;

CREATE OR REPLACE FUNCTION public.move_load_items_between_loads(_tenant_id uuid, _source_load_id uuid, _target_load_id uuid, _item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_moved int; v_doc_ids uuid[];
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF _source_load_id = _target_load_id THEN RAISE EXCEPTION 'same_load'; END IF;
  IF public._load_is_locked(_source_load_id) THEN RAISE EXCEPTION 'source_load_locked'; END IF;
  IF public._load_is_locked(_target_load_id) THEN RAISE EXCEPTION 'target_load_locked'; END IF;

  SELECT COALESCE(array_agg(DISTINCT fiscal_document_id) FILTER (WHERE fiscal_document_id IS NOT NULL),
                  ARRAY[]::uuid[])
    INTO v_doc_ids
  FROM public.load_items
  WHERE id = ANY(_item_ids) AND load_id = _source_load_id AND tenant_id = _tenant_id;

  UPDATE public.load_items
    SET load_id = _target_load_id, updated_at = now()
    WHERE id = ANY(_item_ids) AND load_id = _source_load_id AND tenant_id = _tenant_id;
  GET DIAGNOSTICS v_moved = ROW_COUNT;

  IF array_length(v_doc_ids, 1) IS NOT NULL THEN
    UPDATE public.fiscal_documents
      SET load_id = _target_load_id, updated_at = now()
      WHERE id = ANY(v_doc_ids) AND tenant_id = _tenant_id;
  END IF;

  PERFORM public._log_entity_audit(_tenant_id, 'load', _source_load_id, 'move_items_out',
    NULL, jsonb_build_object('target_load_id', _target_load_id, 'item_ids', to_jsonb(_item_ids),
                             'document_ids', to_jsonb(v_doc_ids)), 'composition_rpc');
  PERFORM public._log_entity_audit(_tenant_id, 'load', _target_load_id, 'move_items_in',
    NULL, jsonb_build_object('source_load_id', _source_load_id, 'item_ids', to_jsonb(_item_ids),
                             'document_ids', to_jsonb(v_doc_ids)), 'composition_rpc');

  RETURN jsonb_build_object('moved', v_moved, 'document_ids', COALESCE(to_jsonb(v_doc_ids), '[]'::jsonb));
END $function$;

CREATE OR REPLACE FUNCTION public.delete_load_safely(_tenant_id uuid, _load_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_pod int; v_terminal_doc int; v_dtl int; v_crit_occ int;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF public._load_is_locked(_load_id) THEN RAISE EXCEPTION 'load_locked'; END IF;

  SELECT count(*) INTO v_pod FROM public.proof_of_delivery WHERE load_id = _load_id;
  IF v_pod > 0 THEN RAISE EXCEPTION 'load_has_pod'; END IF;

  SELECT count(*) INTO v_terminal_doc
    FROM public.fiscal_documents
    WHERE load_id = _load_id AND tenant_id = _tenant_id
      AND status IN ('delivered','partial_delivery','returned','refused','failed','not_delivered');
  IF v_terminal_doc > 0 THEN RAISE EXCEPTION 'load_has_terminal_documents'; END IF;

  SELECT count(*) INTO v_dtl FROM public.dispatch_trip_loads WHERE load_id = _load_id;
  IF v_dtl > 0 THEN RAISE EXCEPTION 'load_in_dispatch_trip'; END IF;

  SELECT count(*) INTO v_crit_occ
    FROM public.operational_events
    WHERE load_id = _load_id AND public_status = 'open' AND severity IN ('high','critical');
  IF v_crit_occ > 0 THEN RAISE EXCEPTION 'load_has_critical_occurrence'; END IF;

  UPDATE public.fiscal_documents SET load_id = NULL, updated_at = now()
    WHERE load_id = _load_id AND tenant_id = _tenant_id;
  DELETE FROM public.load_items WHERE load_id = _load_id AND tenant_id = _tenant_id;
  DELETE FROM public.loads WHERE id = _load_id AND tenant_id = _tenant_id;

  PERFORM public._log_entity_audit(_tenant_id, 'load', _load_id, 'delete_safely', NULL, NULL, 'composition_rpc');

  RETURN jsonb_build_object('deleted', true, 'load_id', _load_id);
END $function$;

CREATE OR REPLACE FUNCTION public.get_public_shipment_status(_fiscal_document_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fd_status text; v_load_status text; v_stop_status text;
  v_has_pod boolean; v_has_critical_occ boolean;
  v_tenant uuid; v_client uuid; v_load uuid;
BEGIN
  SELECT fd.status, l.status, fd.tenant_id, fd.client_id, fd.load_id
    INTO v_fd_status, v_load_status, v_tenant, v_client, v_load
  FROM public.fiscal_documents fd
  LEFT JOIN public.loads l ON l.id = fd.load_id
  WHERE fd.id = _fiscal_document_id;

  SELECT ds.status INTO v_stop_status
  FROM public.dispatch_stop_documents dsd
  JOIN public.dispatch_stops ds ON ds.id = dsd.dispatch_stop_id
  WHERE dsd.fiscal_document_id = _fiscal_document_id
  ORDER BY ds.updated_at DESC NULLS LAST LIMIT 1;

  SELECT EXISTS(SELECT 1 FROM public.proof_of_delivery
    WHERE fiscal_document_id = _fiscal_document_id AND status IN ('uploaded','validated'))
    INTO v_has_pod;

  -- Ocorrência crítica vinculada à NF, à parada que contém a NF, ou ao cliente da NF (visível)
  SELECT EXISTS(
    SELECT 1 FROM public.operational_events oe
    WHERE oe.tenant_id = v_tenant
      AND oe.visible_to_client = true
      AND oe.public_status = 'open'
      AND oe.severity IN ('high','critical')
      AND (
        oe.fiscal_document_id = _fiscal_document_id
        OR oe.dispatch_stop_id IN (
          SELECT dsd.dispatch_stop_id FROM public.dispatch_stop_documents dsd
          WHERE dsd.fiscal_document_id = _fiscal_document_id
        )
        OR (oe.client_id IS NOT NULL AND oe.client_id = v_client
            AND (oe.fiscal_document_id IS NULL OR oe.fiscal_document_id = _fiscal_document_id))
      )
  ) INTO v_has_critical_occ;

  IF v_has_critical_occ THEN RETURN 'exception'; END IF;
  IF v_fd_status = 'refused' THEN RETURN 'not_delivered'; END IF;
  IF v_fd_status = 'returned' THEN RETURN 'returned'; END IF;
  IF v_fd_status IN ('failed','not_delivered') THEN RETURN 'not_delivered'; END IF;
  IF v_fd_status = 'partial_delivery' THEN RETURN 'exception'; END IF;
  IF v_fd_status = 'cancelled' THEN RETURN 'cancelled'; END IF;
  IF v_fd_status = 'delivered' THEN
    RETURN CASE WHEN v_has_pod THEN 'pod_available' ELSE 'pod_pending' END;
  END IF;
  IF v_stop_status IN ('arrived','servicing','in_progress') THEN RETURN 'arrived_at_destination'; END IF;
  IF v_stop_status = 'departed' THEN RETURN 'out_for_delivery'; END IF;
  IF v_load_status = 'in_transit' OR v_fd_status = 'in_transit' THEN RETURN 'in_transit'; END IF;
  IF v_load_status IN ('loading','loaded') OR v_fd_status IN ('loading','loaded') THEN RETURN 'loaded'; END IF;
  IF v_load_status IN ('planned','assembling','ready') THEN RETURN 'being_prepared'; END IF;
  IF v_fd_status IN ('confirmed','assigned','pending') THEN RETURN 'received'; END IF;
  RETURN COALESCE(v_fd_status, 'received');
END $function$;

CREATE OR REPLACE FUNCTION public.record_operational_event_with_status(_tenant_id uuid, _entity_type text, _entity_id uuid, _event_type text, _description text, _severity text DEFAULT 'medium'::text, _new_status text DEFAULT NULL::text, _visible_to_client boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid; v_load uuid; v_fd uuid; v_stop uuid; v_client uuid;
  v_old_status text; v_terminal text[] := ARRAY[
    'delivered','partial_delivery','returned','refused','failed','cancelled','not_delivered'];
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF _entity_type NOT IN ('load','fiscal_document','dispatch_stop') THEN
    RAISE EXCEPTION 'invalid_entity_type';
  END IF;

  IF _entity_type = 'load' THEN
    v_load := _entity_id;
    SELECT status INTO v_old_status FROM public.loads WHERE id = _entity_id AND tenant_id = _tenant_id;
  ELSIF _entity_type = 'fiscal_document' THEN
    v_fd := _entity_id;
    SELECT status, load_id, client_id INTO v_old_status, v_load, v_client
      FROM public.fiscal_documents WHERE id = _entity_id AND tenant_id = _tenant_id;
  ELSE
    v_stop := _entity_id;
    SELECT status, client_id INTO v_old_status, v_client
      FROM public.dispatch_stops WHERE id = _entity_id AND tenant_id = _tenant_id;
  END IF;

  IF _new_status IS NOT NULL THEN
    -- Bloqueia regredir de terminal salvo se for o mesmo
    IF v_old_status = ANY(v_terminal) AND _new_status <> v_old_status THEN
      RAISE EXCEPTION 'terminal_status_locked: % -> %', v_old_status, _new_status;
    END IF;

    IF _entity_type = 'load' THEN
      UPDATE public.loads SET status = _new_status, updated_at = now()
        WHERE id = _entity_id AND tenant_id = _tenant_id;
    ELSIF _entity_type = 'fiscal_document' THEN
      UPDATE public.fiscal_documents SET status = _new_status, updated_at = now()
        WHERE id = _entity_id AND tenant_id = _tenant_id;
      -- Propaga para carga apenas se todas as NFs forem terminais
      IF v_load IS NOT NULL AND _new_status = ANY(v_terminal) THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.fiscal_documents fd
          WHERE fd.load_id = v_load AND NOT (fd.status = ANY(v_terminal))
        ) THEN
          UPDATE public.loads SET status = 'delivered', updated_at = now()
            WHERE id = v_load AND tenant_id = _tenant_id
              AND NOT (status = ANY(v_terminal));
        END IF;
      END IF;
    ELSE
      UPDATE public.dispatch_stops SET status = _new_status, updated_at = now()
        WHERE id = _entity_id AND tenant_id = _tenant_id;
    END IF;

    PERFORM public._log_entity_audit(
      _tenant_id, _entity_type, _entity_id, 'status_change',
      jsonb_build_object('old_status', v_old_status),
      jsonb_build_object('new_status', _new_status),
      'record_operational_event_with_status');
  END IF;

  INSERT INTO public.operational_events(
    tenant_id, client_id, load_id, fiscal_document_id, dispatch_stop_id,
    event_type, severity, description, visible_to_client, public_status, created_by
  ) VALUES (
    _tenant_id, v_client, v_load, v_fd, v_stop,
    _event_type, _severity, _description, _visible_to_client, 'reported_by_operator', auth.uid()
  ) RETURNING id INTO v_id;

  PERFORM public._log_entity_audit(
    _tenant_id, _entity_type, _entity_id, 'operational_event',
    NULL,
    jsonb_build_object('event_id', v_id, 'event_type', _event_type, 'severity', _severity,
                       'visible_to_client', _visible_to_client),
    'record_operational_event_with_status');

  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.audit_data_consistency(_tenant_id uuid)
 RETURNS TABLE(severity text, category text, entity_type text, entity_id uuid, message text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_tenant_admin(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;

  -- Composição
  RETURN QUERY SELECT 'critical','composition','fiscal_document',fd.id,
    'load_id de fiscal_document diverge de load_items'
  FROM public.fiscal_documents fd JOIN public.load_items li ON li.fiscal_document_id = fd.id
  WHERE fd.tenant_id=_tenant_id AND fd.load_id IS NOT NULL AND li.load_id IS NOT NULL
    AND fd.load_id <> li.load_id;

  RETURN QUERY SELECT 'critical','composition','fiscal_document',fd.id,
    'fiscal_document.load_id preenchido sem load_items correspondente'
  FROM public.fiscal_documents fd
  WHERE fd.tenant_id=_tenant_id AND fd.load_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.load_items li WHERE li.fiscal_document_id = fd.id AND li.load_id = fd.load_id);

  RETURN QUERY SELECT 'warning','composition','load_item',li.id,
    'load_item sem fiscal_document.load_id correspondente'
  FROM public.load_items li
  JOIN public.fiscal_documents fd ON fd.id = li.fiscal_document_id
  WHERE li.tenant_id=_tenant_id AND li.load_id IS NOT NULL
    AND (fd.load_id IS NULL OR fd.load_id <> li.load_id);

  -- Dispatch
  RETURN QUERY SELECT 'critical','dispatch','dispatch_trip',dt.id,
    'dispatch_trips sem dispatch_trip_loads'
  FROM public.dispatch_trips dt WHERE dt.tenant_id=_tenant_id
    AND NOT EXISTS (SELECT 1 FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id = dt.id);

  RETURN QUERY SELECT 'critical','dispatch','dispatch_stop_document',dsd.dispatch_stop_id,
    'dispatch_stop_documents.fiscal_document_id fora das cargas da viagem'
  FROM public.dispatch_stop_documents dsd
  JOIN public.dispatch_stops ds ON ds.id = dsd.dispatch_stop_id
  JOIN public.fiscal_documents fd ON fd.id = dsd.fiscal_document_id
  WHERE ds.tenant_id=_tenant_id AND fd.load_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.dispatch_trip_loads dtl
      WHERE dtl.dispatch_trip_id = ds.dispatch_trip_id AND dtl.load_id = fd.load_id
    );

  RETURN QUERY SELECT 'warning','dispatch','dispatch_stop',ds.id,
    'parada sem documentos vinculados em viagem com cargas'
  FROM public.dispatch_stops ds JOIN public.dispatch_trips dt ON dt.id = ds.dispatch_trip_id
  WHERE ds.tenant_id=_tenant_id
    AND EXISTS (SELECT 1 FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id=dt.id)
    AND NOT EXISTS (SELECT 1 FROM public.dispatch_stop_documents dsd WHERE dsd.dispatch_stop_id = ds.id);

  RETURN QUERY SELECT 'critical','dispatch','dispatch_stop_document',dsd1.dispatch_stop_id,
    'documento duplicado em duas paradas ativas da mesma viagem'
  FROM public.dispatch_stop_documents dsd1
  JOIN public.dispatch_stops ds1 ON ds1.id = dsd1.dispatch_stop_id
  JOIN public.dispatch_stop_documents dsd2 ON dsd2.fiscal_document_id = dsd1.fiscal_document_id AND dsd2.dispatch_stop_id <> dsd1.dispatch_stop_id
  JOIN public.dispatch_stops ds2 ON ds2.id = dsd2.dispatch_stop_id AND ds2.dispatch_trip_id = ds1.dispatch_trip_id
  WHERE ds1.tenant_id=_tenant_id
    AND NOT (ds1.status = ANY(public.stop_terminal_statuses()))
    AND NOT (ds2.status = ANY(public.stop_terminal_statuses()));

  -- POD
  RETURN QUERY SELECT 'critical','pod','proof_of_delivery',pod.id,
    'POD.fiscal_document_id não pertence ao dispatch_stop_id'
  FROM public.proof_of_delivery pod
  WHERE pod.tenant_id=_tenant_id AND pod.dispatch_stop_id IS NOT NULL AND pod.fiscal_document_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.dispatch_stop_documents dsd
      WHERE dsd.dispatch_stop_id = pod.dispatch_stop_id AND dsd.fiscal_document_id = pod.fiscal_document_id
    );

  RETURN QUERY SELECT 'warning','pod','proof_of_delivery',pod.id,
    'POD.load_id diverge do load do documento'
  FROM public.proof_of_delivery pod
  JOIN public.fiscal_documents fd ON fd.id = pod.fiscal_document_id
  WHERE pod.tenant_id=_tenant_id AND pod.load_id IS NOT NULL AND fd.load_id IS NOT NULL
    AND pod.load_id <> fd.load_id;

  RETURN QUERY SELECT 'critical','pod','proof_of_delivery',pod.id,
    'POD uploaded/validated sem storage_path'
  FROM public.proof_of_delivery pod
  WHERE pod.tenant_id=_tenant_id AND pod.status IN ('uploaded','validated')
    AND (pod.storage_path IS NULL OR pod.storage_path = '');

  -- Status
  RETURN QUERY SELECT 'warning','status','load',l.id,
    'carga delivered com documentos não terminais'
  FROM public.loads l WHERE l.tenant_id=_tenant_id AND l.status='delivered'
    AND EXISTS (SELECT 1 FROM public.fiscal_documents fd WHERE fd.load_id=l.id
                AND fd.status NOT IN ('delivered','partial_delivery','returned','refused','failed','not_delivered','cancelled'));

  RETURN QUERY SELECT 'warning','pod','fiscal_document',fd.id,
    'documento delivered sem POD registrado'
  FROM public.fiscal_documents fd WHERE fd.tenant_id=_tenant_id AND fd.status='delivered'
    AND NOT EXISTS (SELECT 1 FROM public.proof_of_delivery p WHERE p.fiscal_document_id=fd.id);

  RETURN QUERY SELECT 'warning','status','dispatch_stop',ds.id,
    'parada terminal com documento em status não terminal'
  FROM public.dispatch_stops ds
  JOIN public.dispatch_stop_documents dsd ON dsd.dispatch_stop_id = ds.id
  JOIN public.fiscal_documents fd ON fd.id = dsd.fiscal_document_id
  WHERE ds.tenant_id=_tenant_id AND ds.status = ANY(public.stop_terminal_statuses())
    AND fd.status NOT IN ('delivered','partial_delivery','returned','refused','failed','not_delivered','cancelled');

  RETURN QUERY SELECT 'warning','dispatch','dispatch_trip',dt.id,
    'viagem completed com parada não terminal'
  FROM public.dispatch_trips dt WHERE dt.tenant_id=_tenant_id AND dt.status='completed'
    AND EXISTS (SELECT 1 FROM public.dispatch_stops ds WHERE ds.dispatch_trip_id=dt.id
                AND NOT (ds.status = ANY(public.stop_terminal_statuses())));

  -- Ocorrências / Portal
  RETURN QUERY SELECT 'warning','occurrence','operational_event',oe.id,
    'ocorrência visível ao cliente sem client/document/stop'
  FROM public.operational_events oe WHERE oe.tenant_id=_tenant_id AND oe.visible_to_client=true
    AND oe.client_id IS NULL AND oe.fiscal_document_id IS NULL AND oe.dispatch_stop_id IS NULL;

  RETURN QUERY SELECT 'warning','occurrence','operational_event',oe.id,
    'ocorrência visível com client_id que não bate com documento'
  FROM public.operational_events oe
  JOIN public.fiscal_documents fd ON fd.id = oe.fiscal_document_id
  WHERE oe.tenant_id=_tenant_id AND oe.visible_to_client=true
    AND oe.client_id IS NOT NULL AND fd.client_id IS NOT NULL AND oe.client_id <> fd.client_id;

  RETURN QUERY SELECT 'warning','portal','client_portal_access',cpa.id,
    'client_portal_access órfão (cliente, usuário ou tenant inválido)'
  FROM public.client_portal_access cpa
  WHERE cpa.tenant_id=_tenant_id
    AND (NOT EXISTS (SELECT 1 FROM public.clients c WHERE c.id = cpa.client_id)
         OR NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = cpa.user_id));

  RETURN QUERY SELECT 'warning','pickup','pickup_order',po.id,
    'pickup_orders sem cliente válido'
  FROM public.pickup_orders po
  WHERE po.tenant_id=_tenant_id AND po.remitter_client_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.clients c WHERE c.id = po.remitter_client_id);

  RETURN QUERY SELECT 'warning','composition','load',l.id,
    'load.trip_id sem dispatch_trip_loads correspondente'
  FROM public.loads l WHERE l.tenant_id=_tenant_id AND l.trip_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.dispatch_trip_loads dtl
                    WHERE dtl.dispatch_trip_id=l.trip_id AND dtl.load_id=l.id);

  RETURN QUERY SELECT 'critical','composition','dispatch_trip_load',dtl.dispatch_trip_id,
    'dispatch_trip_loads.load_id sem carga válida'
  FROM public.dispatch_trip_loads dtl
  JOIN public.dispatch_trips dt ON dt.id = dtl.dispatch_trip_id
  WHERE dt.tenant_id=_tenant_id
    AND NOT EXISTS (SELECT 1 FROM public.loads l WHERE l.id = dtl.load_id);

  RETURN;
END $function$;

CREATE OR REPLACE FUNCTION public.delete_loads_safely(_tenant_id uuid, _load_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_result jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF _load_ids IS NULL THEN RETURN v_result; END IF;
  FOREACH v_id IN ARRAY _load_ids LOOP
    BEGIN
      PERFORM public.delete_load_safely(_tenant_id, v_id);
      v_result := v_result || jsonb_build_object('load_id', v_id, 'ok', true);
    EXCEPTION WHEN OTHERS THEN
      v_result := v_result || jsonb_build_object('load_id', v_id, 'ok', false, 'error', SQLERRM);
    END;
  END LOOP;
  RETURN v_result;
END $function$;

CREATE OR REPLACE FUNCTION public.log_pod_access(_tenant_id uuid, _pod_id uuid, _fiscal_document_id uuid, _success boolean, _source text DEFAULT 'portal_pod_download'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text;
BEGIN
  SELECT 'portal'::text INTO v_role;
  INSERT INTO public.entity_audit_log(
    tenant_id, entity_type, entity_id, action,
    old_data, new_data, actor_user_id, actor_role, source
  ) VALUES (
    _tenant_id, 'proof_of_delivery', _pod_id, 'pod_download',
    NULL,
    jsonb_build_object('fiscal_document_id', _fiscal_document_id, 'success', _success),
    auth.uid(), v_role, _source
  );
END $function$;

CREATE OR REPLACE FUNCTION public._touch_driver_settlements_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$;

CREATE OR REPLACE FUNCTION public.generate_driver_settlement(_tenant_id uuid, _dispatch_trip_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_trip_status text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  SELECT status INTO v_trip_status FROM public.dispatch_trips WHERE id = _dispatch_trip_id AND tenant_id = _tenant_id;
  IF v_trip_status IS NULL THEN RAISE EXCEPTION 'trip_not_found'; END IF;
  IF v_trip_status <> 'completed' THEN RAISE EXCEPTION 'trip_not_completed'; END IF;
  RETURN public._build_driver_settlement(_tenant_id, _dispatch_trip_id);
END; $function$;

CREATE OR REPLACE FUNCTION public.generate_pending_driver_settlements(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trip_id uuid; v_existing uuid; v_status text;
  v_generated int := 0; v_recalculated int := 0; v_skipped int := 0;
  v_errors jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  FOR v_trip_id IN
    SELECT dt.id FROM public.dispatch_trips dt
    WHERE dt.tenant_id = _tenant_id AND dt.status = 'completed'
  LOOP
    SELECT id, status INTO v_existing, v_status FROM public.driver_settlements
      WHERE tenant_id = _tenant_id AND dispatch_trip_id = v_trip_id;
    BEGIN
      IF v_existing IS NULL THEN
        PERFORM public._build_driver_settlement(_tenant_id, v_trip_id);
        v_generated := v_generated + 1;
      ELSIF v_status IN ('pending_review','in_review','reopened') THEN
        IF EXISTS (
          SELECT 1 FROM public.driver_settlements s WHERE s.id = v_existing AND (
            s.loads_count = 0 OR s.documents_count = 0 OR s.estimated_km IS NULL
            OR s.total_invoice_value = 0 OR s.total_freight_value = 0 OR s.needs_recalculation = true
            OR s.last_recalculated_at IS NULL
          )
        ) THEN
          PERFORM public._build_driver_settlement(_tenant_id, v_trip_id);
          v_recalculated := v_recalculated + 1;
        ELSE
          v_skipped := v_skipped + 1;
        END IF;
      ELSE
        v_skipped := v_skipped + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_skipped := v_skipped + 1;
      v_errors := v_errors || jsonb_build_object('trip_id', v_trip_id, 'error', SQLERRM);
    END;
  END LOOP;
  RETURN jsonb_build_object('generated', v_generated, 'recalculated', v_recalculated, 'skipped', v_skipped, 'errors', v_errors);
END; $function$;

CREATE OR REPLACE FUNCTION public._on_dispatch_trip_completed_create_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'completed' AND (OLD.status IS DISTINCT FROM 'completed') THEN
    BEGIN
      PERFORM public._build_driver_settlement(NEW.tenant_id, NEW.id);
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.driver_settlements (tenant_id, dispatch_trip_id, driver_id, vehicle_id, status, trip_started_at, trip_completed_at, needs_recalculation, recalculation_reason)
      VALUES (NEW.tenant_id, NEW.id, NEW.driver_id, NEW.vehicle_id, 'pending_review', NEW.actual_start_at, NEW.actual_end_at, true, 'auto_build_failed: ' || SQLERRM)
      ON CONFLICT (tenant_id, dispatch_trip_id) DO NOTHING;
    END;
  END IF;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public._log_settlement_event(_settlement_id uuid, _event_type text, _from_status text DEFAULT NULL::text, _to_status text DEFAULT NULL::text, _reason text DEFAULT NULL::text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_t uuid;
BEGIN
  SELECT tenant_id INTO v_t FROM public.driver_settlements WHERE id = _settlement_id;
  IF v_t IS NULL THEN RETURN; END IF;
  INSERT INTO public.driver_settlement_events(tenant_id, settlement_id, event_type, from_status, to_status, reason, payload, created_by)
  VALUES (v_t, _settlement_id, _event_type, _from_status, _to_status, _reason, COALESCE(_payload,'{}'::jsonb), auth.uid());
END; $function$;

CREATE OR REPLACE FUNCTION public._build_driver_settlement(_tenant_id uuid, _dispatch_trip_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trip record;
  v_settlement_id uuid;
  v_existing_status text;
  v_was_new boolean := false;
  v_loads_count int := 0;
  v_stops_count int := 0;
  v_documents_count int := 0;
  v_total_goods numeric := 0;
  v_total_freight_rev numeric := 0;
  v_total_weight numeric := 0;
  v_estimated_km numeric;
  v_appr numeric := 0;
  v_pend numeric := 0;
  v_rej numeric := 0;
  v_exp_total numeric := 0;
  v_appr_reimb numeric := 0;
  v_adj_credits numeric := 0;
  v_adj_debits numeric := 0;
  v_route_origin text;
  v_route_destination text;
  v_route_name text;
  v_total_paid numeric := 0;
  v_payable numeric := 0;
  v_route_result numeric := 0;
  v_snapshot jsonb;
BEGIN
  SELECT dt.* INTO v_trip
  FROM public.dispatch_trips dt
  WHERE dt.id = _dispatch_trip_id AND dt.tenant_id = _tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'trip_not_found'; END IF;

  SELECT id, status INTO v_settlement_id, v_existing_status
  FROM public.driver_settlements
  WHERE tenant_id = _tenant_id AND dispatch_trip_id = _dispatch_trip_id;

  IF v_settlement_id IS NOT NULL AND v_existing_status NOT IN ('pending_review','in_review','reopened') THEN
    RAISE EXCEPTION 'settlement_locked';
  END IF;

  -- Distinct document ids across the trip (load-linked + stop-linked)
  CREATE TEMP TABLE IF NOT EXISTS _tmp_doc_ids (id uuid PRIMARY KEY) ON COMMIT DROP;
  DELETE FROM _tmp_doc_ids;
  INSERT INTO _tmp_doc_ids(id)
  SELECT DISTINCT x.id FROM (
    SELECT fd.id
      FROM public.fiscal_documents fd
     WHERE fd.tenant_id = _tenant_id
       AND fd.load_id IN (
         SELECT v_trip.load_id WHERE v_trip.load_id IS NOT NULL
         UNION
         SELECT dtl.load_id FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id = _dispatch_trip_id
       )
    UNION
    SELECT dsd.fiscal_document_id AS id
      FROM public.dispatch_stop_documents dsd
      JOIN public.dispatch_stops ds ON ds.id = dsd.dispatch_stop_id
     WHERE ds.dispatch_trip_id = _dispatch_trip_id AND dsd.fiscal_document_id IS NOT NULL
  ) x
  ON CONFLICT (id) DO NOTHING;

  SELECT
    (SELECT count(DISTINCT load_id) FROM (
       SELECT v_trip.load_id AS load_id WHERE v_trip.load_id IS NOT NULL
       UNION
       SELECT dtl.load_id FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id = _dispatch_trip_id
     ) x WHERE load_id IS NOT NULL),
    (SELECT count(*) FROM public.dispatch_stops WHERE dispatch_trip_id = _dispatch_trip_id),
    (SELECT count(*) FROM _tmp_doc_ids),
    COALESCE((SELECT sum(fd.value) FROM public.fiscal_documents fd JOIN _tmp_doc_ids d ON d.id = fd.id
              WHERE COALESCE(fd.document_type,'nfe') NOT IN ('cte','ct-e','CTe')), 0),
    COALESCE((SELECT sum(COALESCE(NULLIF(fd.freight_value,0),
                          CASE WHEN COALESCE(fd.document_type,'nfe') IN ('cte','ct-e','CTe') THEN fd.value ELSE 0 END))
              FROM public.fiscal_documents fd JOIN _tmp_doc_ids d ON d.id = fd.id), 0),
    COALESCE(NULLIF((SELECT sum(fd.weight_kg) FROM public.fiscal_documents fd JOIN _tmp_doc_ids d ON d.id = fd.id),0),
             COALESCE((SELECT sum(l.total_weight_kg) FROM public.loads l WHERE l.id IN (
                SELECT v_trip.load_id WHERE v_trip.load_id IS NOT NULL
                UNION SELECT dtl.load_id FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id = _dispatch_trip_id
             )),0))
  INTO v_loads_count, v_stops_count, v_documents_count, v_total_goods, v_total_freight_rev, v_total_weight;

  SELECT (tr.distance_meters / 1000.0) INTO v_estimated_km
  FROM public.trip_routes tr
  WHERE tr.tenant_id = _tenant_id AND tr.trip_id = _dispatch_trip_id
  ORDER BY (tr.provider = 'osrm') DESC, tr.created_at DESC LIMIT 1;

  -- Expenses split: total approved (route cost) vs. approved-AND-reimbursable (driver payable)
  SELECT
    COALESCE(sum(amount) FILTER (WHERE approval_status='approved'),0),
    COALESCE(sum(amount) FILTER (WHERE approval_status='pending'),0),
    COALESCE(sum(amount) FILTER (WHERE approval_status='rejected'),0),
    COALESCE(sum(amount),0),
    COALESCE(sum(amount) FILTER (WHERE approval_status='approved' AND COALESCE(reimbursable,true)=true),0)
  INTO v_appr, v_pend, v_rej, v_exp_total, v_appr_reimb
  FROM public.driver_expenses
  WHERE tenant_id = _tenant_id AND dispatch_trip_id = _dispatch_trip_id;

  -- Origin: prefer first linked load's origin; else null
  SELECT l.origin INTO v_route_origin
  FROM public.loads l
  WHERE l.id IN (
    SELECT v_trip.load_id WHERE v_trip.load_id IS NOT NULL
    UNION SELECT dtl.load_id FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id = _dispatch_trip_id
  ) AND l.origin IS NOT NULL
  ORDER BY l.created_at ASC NULLS LAST
  LIMIT 1;

  -- If no load origin, use first stop destination as origin proxy
  IF v_route_origin IS NULL THEN
    SELECT ds.destination INTO v_route_origin
    FROM public.dispatch_stops ds
    WHERE ds.dispatch_trip_id = _dispatch_trip_id
    ORDER BY ds.stop_order ASC NULLS LAST, ds.created_at ASC NULLS LAST
    LIMIT 1;
  END IF;

  -- Destination: last stop's destination; fallback to load destination
  SELECT ds.destination INTO v_route_destination
  FROM public.dispatch_stops ds
  WHERE ds.dispatch_trip_id = _dispatch_trip_id
  ORDER BY ds.stop_order DESC NULLS LAST, ds.created_at DESC NULLS LAST
  LIMIT 1;

  IF v_route_destination IS NULL THEN
    SELECT l.destination INTO v_route_destination
    FROM public.loads l
    WHERE l.id IN (
      SELECT v_trip.load_id WHERE v_trip.load_id IS NOT NULL
      UNION SELECT dtl.load_id FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id = _dispatch_trip_id
    ) AND l.destination IS NOT NULL
    ORDER BY l.created_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  v_route_name := v_trip.notes;
  v_route_result := COALESCE(v_total_freight_rev,0) - COALESCE(v_appr,0);

  IF v_settlement_id IS NULL THEN
    v_was_new := true;
    INSERT INTO public.driver_settlements (
      tenant_id, dispatch_trip_id, driver_id, vehicle_id, status,
      trip_started_at, trip_completed_at, route_name, route_origin, route_destination,
      loads_count, stops_count, documents_count,
      total_invoice_value, total_freight_value, total_weight_kg,
      total_goods_value, total_freight_revenue, route_result,
      estimated_km,
      approved_expenses_total, pending_expenses_total, rejected_expenses_total, expenses_total,
      driver_reimbursement_total,
      invoice_balance, operational_balance,
      last_recalculated_at, needs_recalculation, recalculation_reason
    ) VALUES (
      _tenant_id, _dispatch_trip_id, v_trip.driver_id, v_trip.vehicle_id, 'pending_review',
      v_trip.actual_start_at, v_trip.actual_end_at, v_route_name, v_route_origin, v_route_destination,
      v_loads_count, v_stops_count, v_documents_count,
      v_total_goods, v_total_freight_rev, v_total_weight,
      v_total_goods, v_total_freight_rev, v_route_result,
      v_estimated_km,
      v_appr, v_pend, v_rej, v_exp_total,
      v_appr_reimb,
      v_total_goods - v_appr, v_route_result,
      now(), false, NULL
    ) RETURNING id INTO v_settlement_id;
  END IF;

  SELECT
    COALESCE(sum(amount) FILTER (WHERE nature='credit'),0),
    COALESCE(sum(amount) FILTER (WHERE nature='debit'),0)
  INTO v_adj_credits, v_adj_debits
  FROM public.driver_settlement_items
  WHERE settlement_id = v_settlement_id AND item_type='adjustment';

  SELECT COALESCE(sum(amount),0) INTO v_total_paid
  FROM public.driver_settlement_payments WHERE settlement_id = v_settlement_id;

  v_payable := v_adj_credits + v_appr_reimb - v_adj_debits;

  -- Snapshot (fotografia)
  v_snapshot := jsonb_build_object(
    'calculation_version', 'driver_settlement_v2',
    'generated_at', now(),
    'trip', jsonb_build_object('id', v_trip.id, 'status', v_trip.status, 'started_at', v_trip.actual_start_at, 'ended_at', v_trip.actual_end_at, 'notes', v_trip.notes),
    'driver_id', v_trip.driver_id, 'vehicle_id', v_trip.vehicle_id,
    'route', jsonb_build_object('origin', v_route_origin, 'destination', v_route_destination, 'estimated_km', v_estimated_km),
    'loads', COALESCE((SELECT jsonb_agg(to_jsonb(l)) FROM public.loads l WHERE l.id IN (
        SELECT v_trip.load_id WHERE v_trip.load_id IS NOT NULL
        UNION SELECT dtl.load_id FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id = _dispatch_trip_id
      )), '[]'::jsonb),
    'documents', COALESCE((SELECT jsonb_agg(to_jsonb(fd)) FROM public.fiscal_documents fd WHERE fd.id IN (SELECT id FROM _tmp_doc_ids)), '[]'::jsonb),
    'expenses', COALESCE((SELECT jsonb_agg(to_jsonb(de)) FROM public.driver_expenses de WHERE de.tenant_id = _tenant_id AND de.dispatch_trip_id = _dispatch_trip_id), '[]'::jsonb),
    'totals', jsonb_build_object(
      'total_goods_value', v_total_goods,
      'total_freight_revenue', v_total_freight_rev,
      'approved_expenses_total', v_appr,
      'driver_reimbursement_total', v_appr_reimb,
      'route_result', v_route_result,
      'driver_credits_total', v_adj_credits,
      'driver_debits_total', v_adj_debits,
      'driver_payable_amount', v_payable,
      'total_paid_amount', v_total_paid,
      'payment_balance', v_payable - v_total_paid
    )
  );

  UPDATE public.driver_settlements SET
    driver_id = v_trip.driver_id,
    vehicle_id = v_trip.vehicle_id,
    trip_started_at = v_trip.actual_start_at,
    trip_completed_at = v_trip.actual_end_at,
    route_name = v_route_name,
    route_origin = v_route_origin,
    route_destination = v_route_destination,
    loads_count = v_loads_count,
    stops_count = v_stops_count,
    documents_count = v_documents_count,
    total_invoice_value = v_total_goods,
    total_freight_value = v_total_freight_rev,
    total_weight_kg = v_total_weight,
    total_goods_value = v_total_goods,
    total_freight_revenue = v_total_freight_rev,
    route_result = v_route_result,
    estimated_km = v_estimated_km,
    approved_expenses_total = v_appr,
    pending_expenses_total = v_pend,
    rejected_expenses_total = v_rej,
    expenses_total = v_exp_total,
    driver_reimbursement_total = v_appr_reimb,
    driver_credits_total = v_adj_credits,
    driver_debits_total = v_adj_debits,
    driver_payable_amount = v_payable,
    manual_adjustments_total = v_adj_credits - v_adj_debits,
    total_paid_amount = v_total_paid,
    payment_balance = v_payable - v_total_paid,
    invoice_balance = v_total_goods - v_appr,
    operational_balance = v_route_result,
    final_amount = v_payable,
    last_recalculated_at = now(),
    needs_recalculation = false,
    recalculation_reason = NULL,
    snapshot_json = v_snapshot
  WHERE id = v_settlement_id;

  DELETE FROM public.driver_settlement_items
   WHERE settlement_id = v_settlement_id AND item_type <> 'adjustment';

  INSERT INTO public.driver_settlement_items(tenant_id, settlement_id, item_type, source_table, source_id, description, amount, quantity, metadata)
  SELECT _tenant_id, v_settlement_id, 'load', 'loads', l.id,
         COALESCE(l.load_number, l.origin || ' → ' || l.destination), 0, l.total_weight_kg,
         jsonb_build_object('origin', l.origin, 'destination', l.destination, 'status', l.status, 'pallets', l.total_pallet_count)
  FROM public.loads l
  WHERE l.id IN (
    SELECT v_trip.load_id WHERE v_trip.load_id IS NOT NULL
    UNION
    SELECT dtl.load_id FROM public.dispatch_trip_loads dtl WHERE dtl.dispatch_trip_id = _dispatch_trip_id
  );

  INSERT INTO public.driver_settlement_items(tenant_id, settlement_id, item_type, source_table, source_id, description, amount, quantity, metadata)
  SELECT _tenant_id, v_settlement_id, 'fiscal_document', 'fiscal_documents', fd.id,
         COALESCE(fd.invoice_number, fd.access_key), fd.value, fd.weight_kg,
         jsonb_build_object('document_type', fd.document_type, 'freight_value', fd.freight_value, 'recipient', fd.recipient, 'recipient_city', fd.recipient_city, 'recipient_state', fd.recipient_state, 'status', fd.status)
  FROM public.fiscal_documents fd
  WHERE fd.id IN (SELECT id FROM _tmp_doc_ids);

  INSERT INTO public.driver_settlement_items(tenant_id, settlement_id, item_type, source_table, source_id, description, amount, quantity, metadata)
  SELECT _tenant_id, v_settlement_id, 'expense', 'driver_expenses', de.id,
         de.category, de.amount, NULL,
         jsonb_build_object('approval_status', de.approval_status, 'expense_at', de.expense_at, 'receipt_url', de.receipt_url, 'notes', de.notes,
                            'reimbursable', COALESCE(de.reimbursable, true), 'payment_source', COALESCE(de.payment_source,'driver'))
  FROM public.driver_expenses de
  WHERE de.tenant_id = _tenant_id AND de.dispatch_trip_id = _dispatch_trip_id;

  IF v_estimated_km IS NOT NULL THEN
    INSERT INTO public.driver_settlement_items(tenant_id, settlement_id, item_type, source_table, source_id, description, amount, quantity, metadata)
    VALUES (_tenant_id, v_settlement_id, 'km', 'trip_routes', NULL, 'KM estimado (mapa)', 0, v_estimated_km, jsonb_build_object('provider','osrm'));
  END IF;

  PERFORM public._log_settlement_event(
    v_settlement_id,
    CASE WHEN v_was_new THEN 'generated' ELSE 'recalculated' END,
    NULL, NULL, NULL,
    jsonb_build_object('loads', v_loads_count, 'documents', v_documents_count, 'freight', v_total_freight_rev, 'goods', v_total_goods, 'expenses_approved', v_appr, 'driver_reimbursement', v_appr_reimb)
  );

  RETURN v_settlement_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_driver_settlement_status(_settlement_id uuid, _new_status text, _reason text DEFAULT NULL::text, _allow_exceptions boolean DEFAULT false)
 RETURNS driver_settlements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_s public.driver_settlements;
  v_prev_status text;
  v_allowed boolean := false;
  v_blocks text[] := ARRAY[]::text[];
  v_is_admin boolean;
  v_event_type text;
  v_payload jsonb;
BEGIN
  IF _new_status = 'paid' THEN
    RAISE EXCEPTION 'paid_status_requires_payment_registration';
  END IF;

  SELECT * INTO v_s FROM public.driver_settlements WHERE id = _settlement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  v_prev_status := v_s.status;
  v_is_admin := public.is_tenant_admin(v_s.tenant_id);

  v_allowed := CASE
    WHEN v_s.status = 'pending_review' AND _new_status IN ('in_review') THEN true
    WHEN v_s.status = 'in_review' AND _new_status IN ('approved','pending_review') THEN true
    WHEN v_s.status = 'approved' AND _new_status IN ('closed') THEN v_is_admin
    WHEN v_s.status = 'paid' AND _new_status IN ('closed','reopened') THEN v_is_admin OR _new_status='closed'
    WHEN v_s.status = 'closed' AND _new_status = 'reopened' THEN v_is_admin
    WHEN v_s.status = 'reopened' AND _new_status IN ('in_review','approved') THEN true
    ELSE false
  END;
  IF NOT v_allowed THEN RAISE EXCEPTION 'invalid_transition'; END IF;

  -- approved -> closed (excepcional): exige motivo obrigatório
  IF v_s.status = 'approved' AND _new_status = 'closed' THEN
    IF length(trim(COALESCE(_reason,''))) = 0 THEN
      RAISE EXCEPTION 'reason_required';
    END IF;
  END IF;

  IF _new_status = 'approved' THEN
    IF v_s.needs_recalculation THEN v_blocks := array_append(v_blocks,'needs_recalculation'); END IF;
    IF v_s.loads_count = 0 THEN v_blocks := array_append(v_blocks,'no_loads'); END IF;
    IF v_s.documents_count = 0 THEN v_blocks := array_append(v_blocks,'no_documents'); END IF;
    IF v_s.km_review_status NOT IN ('reviewed','disputed') THEN v_blocks := array_append(v_blocks,'km_not_reviewed'); END IF;
    IF v_s.km_review_status = 'disputed' AND COALESCE(v_s.km_review_notes,'')='' THEN v_blocks := array_append(v_blocks,'km_dispute_needs_notes'); END IF;
    IF v_s.audited_km IS NULL THEN v_blocks := array_append(v_blocks,'audited_km_missing'); END IF;
    IF COALESCE(v_s.pending_expenses_total,0) > 0 THEN v_blocks := array_append(v_blocks,'pending_expenses'); END IF;
    IF COALESCE(v_s.total_freight_value,0) = 0 THEN v_blocks := array_append(v_blocks,'no_freight'); END IF;

    IF array_length(v_blocks,1) > 0 THEN
      IF NOT _allow_exceptions OR NOT v_is_admin OR COALESCE(_reason,'')='' THEN
        RAISE EXCEPTION 'approval_blocked: %', array_to_string(v_blocks, ',');
      END IF;
    END IF;
  END IF;

  UPDATE public.driver_settlements SET
    status = _new_status,
    reviewed_by = CASE WHEN _new_status='in_review' THEN v_user ELSE reviewed_by END,
    reviewed_at = CASE WHEN _new_status='in_review' THEN now() ELSE reviewed_at END,
    approved_by = CASE WHEN _new_status='approved' THEN v_user ELSE approved_by END,
    approved_at = CASE WHEN _new_status='approved' THEN now() ELSE approved_at END,
    closed_by = CASE WHEN _new_status='closed' THEN v_user ELSE closed_by END,
    closed_at = CASE WHEN _new_status='closed' THEN now() ELSE closed_at END,
    approved_with_exception = CASE WHEN _new_status='approved' AND array_length(v_blocks,1) > 0 THEN true ELSE approved_with_exception END,
    exception_reason = CASE WHEN _new_status='approved' AND array_length(v_blocks,1) > 0 THEN _reason ELSE exception_reason END
  WHERE id = _settlement_id RETURNING * INTO v_s;

  IF v_prev_status = 'approved' AND _new_status = 'closed' THEN
    v_event_type := 'closed_without_full_payment';
    v_payload := jsonb_build_object(
      'driver_payable_amount', v_s.driver_payable_amount,
      'total_paid_amount', v_s.total_paid_amount,
      'payment_balance', v_s.payment_balance,
      'closed_by', v_s.closed_by,
      'closed_at', v_s.closed_at
    );
  ELSIF _new_status='approved' AND array_length(v_blocks,1) > 0 THEN
    v_event_type := 'approved_with_exception';
    v_payload := jsonb_build_object('blocks', to_jsonb(v_blocks), 'allow_exceptions', _allow_exceptions);
  ELSE
    v_event_type := 'status_changed';
    v_payload := jsonb_build_object('blocks', to_jsonb(v_blocks), 'allow_exceptions', _allow_exceptions);
  END IF;

  PERFORM public._log_settlement_event(_settlement_id, v_event_type, v_prev_status, _new_status, _reason, v_payload);

  RETURN v_s;
END; $function$;

CREATE OR REPLACE FUNCTION public.add_driver_settlement_adjustment(_settlement_id uuid, _nature text, _amount numeric, _description text, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_s public.driver_settlements; v_id uuid;
BEGIN
  SELECT * INTO v_s FROM public.driver_settlements WHERE id = _settlement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF v_s.status NOT IN ('pending_review','in_review','reopened') THEN RAISE EXCEPTION 'settlement_locked'; END IF;
  IF _nature NOT IN ('credit','debit') THEN RAISE EXCEPTION 'invalid_nature'; END IF;
  IF _amount IS NULL OR _amount <= 0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;
  IF COALESCE(_reason,'')='' THEN RAISE EXCEPTION 'reason_required'; END IF;
  INSERT INTO public.driver_settlement_items(tenant_id, settlement_id, item_type, source_table, description, amount, nature, metadata)
  VALUES (v_s.tenant_id, _settlement_id, 'adjustment', 'manual', _description, _amount, _nature,
          jsonb_build_object('reason', _reason, 'created_by', auth.uid()))
  RETURNING id INTO v_id;
  PERFORM public._build_driver_settlement(v_s.tenant_id, v_s.dispatch_trip_id);
  PERFORM public._log_settlement_event(_settlement_id, 'manual_adjustment_added', NULL, NULL, _reason,
    jsonb_build_object('item_id', v_id, 'nature', _nature, 'amount', _amount, 'description', _description));
  RETURN v_id;
END; $function$;

CREATE OR REPLACE FUNCTION public.remove_driver_settlement_adjustment(_settlement_id uuid, _item_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_s public.driver_settlements; v_rows int;
BEGIN
  IF length(trim(COALESCE(_reason,''))) = 0 THEN RAISE EXCEPTION 'reason_required'; END IF;
  SELECT * INTO v_s FROM public.driver_settlements WHERE id = _settlement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF v_s.status NOT IN ('pending_review','in_review','reopened') THEN RAISE EXCEPTION 'settlement_locked'; END IF;
  DELETE FROM public.driver_settlement_items
    WHERE id = _item_id AND settlement_id = _settlement_id AND item_type='adjustment';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN RAISE EXCEPTION 'adjustment_not_found'; END IF;
  PERFORM public._build_driver_settlement(v_s.tenant_id, v_s.dispatch_trip_id);
  PERFORM public._log_settlement_event(_settlement_id, 'manual_adjustment_removed', NULL, NULL, _reason,
    jsonb_build_object('item_id', _item_id));
END; $function$;

CREATE OR REPLACE FUNCTION public.mark_driver_settlement_outdated(_tenant_id uuid, _dispatch_trip_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_s public.driver_settlements;
BEGIN
  SELECT * INTO v_s FROM public.driver_settlements
    WHERE tenant_id = _tenant_id AND dispatch_trip_id = _dispatch_trip_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_s.status IN ('pending_review','in_review','reopened') THEN
    UPDATE public.driver_settlements SET
      needs_recalculation = true,
      recalculation_reason = _reason,
      source_updated_at = now()
    WHERE id = v_s.id;
  END IF;
  PERFORM public._log_settlement_event(v_s.id, 'marked_outdated', v_s.status, v_s.status, _reason, '{}'::jsonb);
END; $function$;

CREATE OR REPLACE FUNCTION public._tg_mark_outdated_expense()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tid uuid; v_trip uuid;
BEGIN
  v_tid := COALESCE(NEW.tenant_id, OLD.tenant_id);
  v_trip := COALESCE(NEW.dispatch_trip_id, OLD.dispatch_trip_id);
  IF v_trip IS NOT NULL THEN PERFORM public.mark_driver_settlement_outdated(v_tid, v_trip, 'driver_expense_change'); END IF;
  RETURN COALESCE(NEW, OLD);
END; $function$;

CREATE OR REPLACE FUNCTION public._tg_mark_outdated_trip_loads()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_trip uuid; v_tid uuid;
BEGIN
  v_trip := COALESCE(NEW.dispatch_trip_id, OLD.dispatch_trip_id);
  SELECT tenant_id INTO v_tid FROM public.dispatch_trips WHERE id = v_trip;
  IF v_tid IS NOT NULL THEN PERFORM public.mark_driver_settlement_outdated(v_tid, v_trip, 'trip_loads_change'); END IF;
  RETURN COALESCE(NEW, OLD);
END; $function$;

CREATE OR REPLACE FUNCTION public._tg_mark_outdated_trip_routes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_trip uuid; v_tid uuid;
BEGIN
  v_trip := COALESCE(NEW.trip_id, OLD.trip_id);
  v_tid := COALESCE(NEW.tenant_id, OLD.tenant_id);
  IF v_trip IS NOT NULL AND v_tid IS NOT NULL THEN PERFORM public.mark_driver_settlement_outdated(v_tid, v_trip, 'trip_route_change'); END IF;
  RETURN COALESCE(NEW, OLD);
END; $function$;

CREATE OR REPLACE FUNCTION public.register_driver_settlement_payment(_settlement_id uuid, _amount numeric, _payment_method text DEFAULT NULL::text, _payment_account text DEFAULT NULL::text, _payment_reference text DEFAULT NULL::text, _receipt_url text DEFAULT NULL::text, _notes text DEFAULT NULL::text, _allow_overpayment boolean DEFAULT false, _overpayment_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_s public.driver_settlements; v_id uuid; v_total numeric;
  v_balance numeric; v_is_admin boolean; v_prev_status text; v_new_status text;
  v_account text; v_in_locked_payroll boolean;
BEGIN
  SELECT * INTO v_s FROM public.driver_settlements WHERE id = _settlement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF v_s.status NOT IN ('approved','paid') THEN RAISE EXCEPTION 'must_be_approved'; END IF;
  IF _amount IS NULL OR _amount <= 0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;

  IF _payment_account IS NULL OR length(trim(_payment_account)) = 0 THEN
    RAISE EXCEPTION 'payment_account_required';
  END IF;
  v_account := trim(_payment_account);
  IF lower(v_account) IN ('outro', 'other') THEN
    RAISE EXCEPTION 'payment_account_description_required';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.payroll_entry_items pei
    JOIN public.payroll_entries pe ON pe.id = pei.payroll_entry_id
    JOIN public.payroll_periods pp ON pp.id = pe.payroll_period_id
    WHERE pei.source_table = 'driver_settlements'
      AND pei.source_id = _settlement_id
      AND pei.item_type <> 'driver_settlement_payment'
      AND pp.status IN ('approved','closed')
      AND EXISTS (
        SELECT 1 FROM public.payables pay
        WHERE pay.tenant_id=v_s.tenant_id
          AND pay.source_table='payroll_entries'
          AND pay.source_id=pe.id
          AND pay.status IN ('pending','paid','partial')
      )
  ) INTO v_in_locked_payroll;

  v_is_admin := EXISTS (
    SELECT 1 FROM public.tenant_memberships
     WHERE tenant_id = v_s.tenant_id AND user_id = auth.uid()
       AND active = true AND role IN ('owner','admin'));

  IF v_in_locked_payroll THEN
    IF NOT (v_is_admin AND length(trim(COALESCE(_overpayment_reason,''))) > 0) THEN
      RAISE EXCEPTION 'settlement_locked_in_payroll';
    END IF;
    INSERT INTO public.payroll_generation_issues(
      tenant_id, payroll_period_id, driver_id, employee_id,
      issue_type, severity, source_table, source_id, message
    )
    SELECT
      v_s.tenant_id, pp.id, v_s.driver_id, pe.employee_id,
      'duplicate_payment_override', 'warning',
      'driver_settlements', _settlement_id,
      'Pagamento direto do acerto autorizado por admin apesar do vínculo em folha. Valor='
        || _amount::text
        || '. Motivo=' || COALESCE(_overpayment_reason, '')
        || '. Usuário=' || COALESCE(auth.uid()::text, '')
    FROM public.payroll_entry_items pei
    JOIN public.payroll_entries pe ON pe.id = pei.payroll_entry_id
    JOIN public.payroll_periods pp ON pp.id = pe.payroll_period_id
    WHERE pei.source_table='driver_settlements' AND pei.source_id=_settlement_id
    LIMIT 1;
  END IF;

  v_prev_status := v_s.status;
  v_balance := COALESCE(v_s.driver_payable_amount,0) - COALESCE(v_s.total_paid_amount,0);
  IF _amount > v_balance THEN
    IF NOT (_allow_overpayment AND v_is_admin AND length(trim(COALESCE(_overpayment_reason,''))) > 0) THEN
      RAISE EXCEPTION 'overpayment_blocked';
    END IF;
  END IF;

  INSERT INTO public.driver_settlement_payments(tenant_id, settlement_id, amount, payment_method, payment_account, payment_reference, receipt_url, notes, paid_by)
  VALUES (v_s.tenant_id, _settlement_id, _amount, _payment_method, v_account, _payment_reference, _receipt_url, _notes, auth.uid())
  RETURNING id INTO v_id;

  SELECT COALESCE(sum(amount),0) INTO v_total FROM public.driver_settlement_payments WHERE settlement_id = _settlement_id;

  UPDATE public.driver_settlements SET
    total_paid_amount = v_total,
    payment_balance = COALESCE(driver_payable_amount,0) - v_total,
    status = CASE WHEN v_total >= COALESCE(driver_payable_amount,0) THEN 'paid' ELSE status END,
    paid_by = CASE WHEN v_total >= COALESCE(driver_payable_amount,0) THEN auth.uid() ELSE paid_by END,
    paid_at = CASE WHEN v_total >= COALESCE(driver_payable_amount,0) THEN now() ELSE paid_at END
  WHERE id = _settlement_id;

  SELECT status INTO v_new_status FROM public.driver_settlements WHERE id = _settlement_id;

  PERFORM public._log_settlement_event(_settlement_id, 'payment_registered', v_prev_status, v_new_status, _notes,
    jsonb_build_object(
      'payment_id', v_id, 'amount', _amount, 'payment_method', _payment_method,
      'payment_account', v_account, 'payment_reference', _payment_reference,
      'receipt_url', _receipt_url, 'notes', _notes,
      'total_paid_amount', v_total,
      'payment_balance', COALESCE(v_s.driver_payable_amount,0) - v_total,
      'overpayment', _amount > v_balance,
      'overpayment_reason', CASE WHEN _amount > v_balance OR v_in_locked_payroll THEN _overpayment_reason END,
      'in_locked_payroll', v_in_locked_payroll
    ));
  RETURN v_id;
END; $function$;

CREATE OR REPLACE FUNCTION public.list_driver_settlements(_tenant_id uuid, _search text DEFAULT NULL::text, _driver_id uuid DEFAULT NULL::uuid, _vehicle_id uuid DEFAULT NULL::uuid, _status text DEFAULT NULL::text, _date_from date DEFAULT NULL::date, _date_to date DEFAULT NULL::date, _only_km_pending boolean DEFAULT false, _only_expense_pending boolean DEFAULT false, _only_no_freight boolean DEFAULT false, _only_needs_recalculation boolean DEFAULT false, _page integer DEFAULT 1, _page_size integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_page_size int := LEAST(GREATEST(COALESCE(_page_size, 50), 1), 100);
  v_page int := GREATEST(COALESCE(_page, 1), 1);
  v_offset int;
  v_q text;
  v_total int;
  v_items jsonb;
  v_summary jsonb;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  v_offset := (v_page - 1) * v_page_size;
  v_q := NULLIF(trim(COALESCE(_search,'')), '');

  WITH base AS (
    SELECT s.*, d.name AS driver_name, v.plate AS vehicle_plate
      FROM public.driver_settlements s
      LEFT JOIN public.drivers d ON d.id = s.driver_id
      LEFT JOIN public.vehicles v ON v.id = s.vehicle_id
     WHERE s.tenant_id = _tenant_id
       AND (_status IS NULL OR s.status = _status)
       AND (_driver_id IS NULL OR s.driver_id = _driver_id)
       AND (_vehicle_id IS NULL OR s.vehicle_id = _vehicle_id)
       AND (_date_from IS NULL OR s.trip_completed_at >= _date_from)
       AND (_date_to IS NULL OR s.trip_completed_at < (_date_to + INTERVAL '1 day'))
       AND (NOT _only_km_pending OR s.km_review_status = 'pending')
       AND (NOT _only_expense_pending OR COALESCE(s.pending_expenses_total,0) > 0)
       AND (NOT _only_no_freight OR COALESCE(s.total_freight_value,0) = 0)
       AND (NOT _only_needs_recalculation OR s.needs_recalculation = true)
       AND (
         v_q IS NULL OR
         s.driver_id IN (SELECT id FROM public.drivers WHERE tenant_id=_tenant_id AND name ILIKE '%'||v_q||'%') OR
         s.vehicle_id IN (SELECT id FROM public.vehicles WHERE tenant_id=_tenant_id AND plate ILIKE '%'||v_q||'%') OR
         s.route_name ILIKE '%'||v_q||'%' OR
         s.route_origin ILIKE '%'||v_q||'%' OR
         s.route_destination ILIKE '%'||v_q||'%' OR
         EXISTS (
           SELECT 1 FROM public.driver_settlement_items i
            WHERE i.settlement_id = s.id AND (i.description ILIKE '%'||v_q||'%')
         )
       )
  ),
  totals AS (
    SELECT
      count(*)::int AS total_count,
      count(*) FILTER (WHERE status='pending_review')::int AS pending_count,
      count(*) FILTER (WHERE status='in_review')::int AS in_review_count,
      count(*) FILTER (WHERE status='approved')::int AS approved_count,
      count(*) FILTER (WHERE status IN ('paid','closed'))::int AS paid_closed_count,
      count(*) FILTER (WHERE needs_recalculation = true)::int AS needs_recalculation_count,
      count(*) FILTER (WHERE km_review_status='pending')::int AS km_pending_count,
      count(*) FILTER (WHERE COALESCE(pending_expenses_total,0) > 0)::int AS expense_pending_count,
      COALESCE(sum(driver_payable_amount),0) AS total_payable,
      COALESCE(sum(total_paid_amount),0) AS total_paid,
      COALESCE(sum(payment_balance),0) AS payment_balance,
      COALESCE(sum(route_result),0) AS route_result_total,
      COALESCE(sum(approved_expenses_total),0) AS approved_expenses_total
    FROM base
  ),
  paged AS (
    SELECT * FROM base
    ORDER BY trip_completed_at DESC NULLS LAST, created_at DESC
    LIMIT v_page_size OFFSET v_offset
  )
  SELECT
    (SELECT total_count FROM totals),
    COALESCE((SELECT jsonb_agg(to_jsonb(paged)) FROM paged), '[]'::jsonb),
    (SELECT to_jsonb(totals) FROM totals)
  INTO v_total, v_items, v_summary;

  RETURN jsonb_build_object(
    'items', v_items,
    'total_count', COALESCE(v_total,0),
    'page', v_page,
    'page_size', v_page_size,
    'summary', COALESCE(v_summary, '{}'::jsonb)
  );
END; $function$;

CREATE OR REPLACE FUNCTION public.list_driver_settlement_filter_options(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_drivers jsonb; v_vehicles jsonb;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name) ORDER BY d.name), '[]'::jsonb)
    INTO v_drivers
    FROM public.drivers d
   WHERE d.tenant_id = _tenant_id
     AND EXISTS (SELECT 1 FROM public.driver_settlements s WHERE s.tenant_id = _tenant_id AND s.driver_id = d.id);
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', v.id, 'plate', v.plate) ORDER BY v.plate), '[]'::jsonb)
    INTO v_vehicles
    FROM public.vehicles v
   WHERE v.tenant_id = _tenant_id
     AND EXISTS (SELECT 1 FROM public.driver_settlements s WHERE s.tenant_id = _tenant_id AND s.vehicle_id = v.id);
  RETURN jsonb_build_object('drivers', v_drivers, 'vehicles', v_vehicles);
END; $function$;

CREATE OR REPLACE FUNCTION public.settle_zero_driver_settlement(_settlement_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_s public.driver_settlements;
  v_payable numeric; v_paid numeric; v_balance numeric;
BEGIN
  IF length(trim(COALESCE(_reason,''))) = 0 THEN RAISE EXCEPTION 'reason_required'; END IF;

  SELECT * INTO v_s FROM public.driver_settlements WHERE id = _settlement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF v_s.status <> 'approved' THEN RAISE EXCEPTION 'must_be_approved'; END IF;

  v_payable := COALESCE(v_s.driver_payable_amount, 0);
  v_paid    := COALESCE(v_s.total_paid_amount, 0);
  v_balance := v_payable - v_paid;

  IF NOT (v_payable = 0 OR v_balance = 0) THEN
    RAISE EXCEPTION 'has_outstanding_balance';
  END IF;

  UPDATE public.driver_settlements SET
    status = 'paid',
    paid_at = now(),
    paid_by = auth.uid(),
    payment_balance = 0
  WHERE id = _settlement_id;

  PERFORM public._log_settlement_event(
    _settlement_id, 'settled_without_payment', 'approved', 'paid', _reason,
    jsonb_build_object(
      'driver_payable_amount', v_payable,
      'total_paid_amount', v_paid,
      'payment_balance', 0
    )
  );

  RETURN jsonb_build_object('ok', true, 'settlement_id', _settlement_id, 'status', 'paid');
END; $function$;

CREATE OR REPLACE FUNCTION public.sync_financial_obligations(_tenant_id uuid, _date_from date DEFAULT NULL::date, _date_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_receivables INT := 0;
  v_settlements INT := 0;
  v_payables INT := 0;
  v_expenses INT := 0;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Receivables → inflow / receivable
  WITH src AS (
    SELECT r.*
    FROM public.receivables r
    WHERE r.tenant_id = _tenant_id
      AND (_date_from IS NULL OR COALESCE(r.due_date, r.created_at::date) >= _date_from)
      AND (_date_to   IS NULL OR COALESCE(r.due_date, r.created_at::date) <= _date_to)
  ),
  upsert AS (
    INSERT INTO public.financial_obligations (
      tenant_id, direction, obligation_type, source_table, source_id,
      description, counterparty_type, counterparty_id,
      amount_expected, amount_matched,
      due_date, expected_payment_date, competence_date,
      status, matching_status, metadata, created_by
    )
    SELECT
      s.tenant_id, 'inflow', 'receivable', 'receivables', s.id,
      COALESCE(s.description, s.invoice_number, 'Recebível'),
      CASE WHEN s.client_id IS NOT NULL THEN 'client' ELSE NULL END,
      s.client_id,
      COALESCE(s.amount, 0),
      COALESCE(s.received_amount, 0),
      s.due_date, s.received_at::date, s.due_date,
      CASE
        WHEN s.status = 'cancelled'                          THEN 'cancelled'
        WHEN s.status = 'received'                           THEN 'paid'
        WHEN COALESCE(s.received_amount,0) > 0
             AND COALESCE(s.received_amount,0) < s.amount    THEN 'partially_paid'
        ELSE 'pending'
      END,
      CASE
        WHEN s.status = 'received' THEN 'matched'
        WHEN COALESCE(s.received_amount,0) > 0 THEN 'partial'
        ELSE 'unmatched'
      END,
      jsonb_build_object(
        'invoice_number', s.invoice_number,
        'fiscal_document_id', s.fiscal_document_id,
        'load_id', s.load_id,
        'order_id', s.order_id
      ),
      s.created_by
    FROM src s
    ON CONFLICT (tenant_id, source_table, source_id, obligation_type)
      WHERE source_table IS NOT NULL AND source_id IS NOT NULL
    DO UPDATE SET
      amount_expected = EXCLUDED.amount_expected,
      amount_matched  = GREATEST(financial_obligations.amount_matched, EXCLUDED.amount_matched),
      due_date        = EXCLUDED.due_date,
      expected_payment_date = EXCLUDED.expected_payment_date,
      description     = EXCLUDED.description,
      counterparty_id = EXCLUDED.counterparty_id,
      status = CASE
        WHEN financial_obligations.status IN ('paid','cancelled','written_off') THEN financial_obligations.status
        ELSE EXCLUDED.status
      END,
      matching_status = CASE
        WHEN financial_obligations.matching_status = 'matched' THEN 'matched'
        ELSE EXCLUDED.matching_status
      END,
      metadata = financial_obligations.metadata || EXCLUDED.metadata,
      updated_at = now()
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_receivables FROM upsert;

  -- Driver settlements → outflow / driver_settlement_payment
  WITH src AS (
    SELECT ds.*
    FROM public.driver_settlements ds
    WHERE ds.tenant_id = _tenant_id
      AND ds.status IN ('approved','paid','closed')
      AND COALESCE(ds.driver_payable_amount, 0) > 0
      AND (_date_from IS NULL OR COALESCE(ds.approved_at::date, ds.created_at::date) >= _date_from)
      AND (_date_to   IS NULL OR COALESCE(ds.approved_at::date, ds.created_at::date) <= _date_to)
  ),
  upsert AS (
    INSERT INTO public.financial_obligations (
      tenant_id, direction, obligation_type, source_table, source_id,
      description, counterparty_type, counterparty_id,
      amount_expected, amount_matched,
      due_date, expected_payment_date, competence_date,
      status, matching_status, metadata, created_by
    )
    SELECT
      s.tenant_id, 'outflow', 'driver_settlement_payment', 'driver_settlements', s.id,
      COALESCE('Acerto ' || s.route_name, 'Acerto motorista'),
      'driver', s.driver_id,
      s.driver_payable_amount,
      COALESCE(s.total_paid_amount, 0),
      COALESCE(s.approved_at::date, s.trip_completed_at::date),
      s.approved_at::date,
      COALESCE(s.trip_completed_at::date, s.approved_at::date),
      CASE
        WHEN s.status = 'closed' AND COALESCE(s.total_paid_amount,0) >= s.driver_payable_amount THEN 'paid'
        WHEN s.status = 'paid'                                                                   THEN 'paid'
        WHEN COALESCE(s.total_paid_amount,0) >= s.driver_payable_amount                          THEN 'paid'
        WHEN COALESCE(s.total_paid_amount,0) > 0                                                 THEN 'partially_paid'
        ELSE 'pending'
      END,
      CASE
        WHEN COALESCE(s.total_paid_amount,0) >= s.driver_payable_amount THEN 'matched'
        WHEN COALESCE(s.total_paid_amount,0) > 0                        THEN 'partial'
        ELSE 'unmatched'
      END,
      jsonb_build_object(
        'dispatch_trip_id', s.dispatch_trip_id,
        'vehicle_id', s.vehicle_id,
        'settlement_status', s.status,
        'route_origin', s.route_origin,
        'route_destination', s.route_destination
      ),
      s.created_by
    FROM src s
    ON CONFLICT (tenant_id, source_table, source_id, obligation_type)
      WHERE source_table IS NOT NULL AND source_id IS NOT NULL
    DO UPDATE SET
      amount_expected = EXCLUDED.amount_expected,
      amount_matched  = GREATEST(financial_obligations.amount_matched, EXCLUDED.amount_matched),
      due_date        = EXCLUDED.due_date,
      description     = EXCLUDED.description,
      counterparty_id = EXCLUDED.counterparty_id,
      status = CASE
        WHEN financial_obligations.status IN ('cancelled','written_off') THEN financial_obligations.status
        ELSE EXCLUDED.status
      END,
      matching_status = CASE
        WHEN financial_obligations.matching_status = 'matched' THEN 'matched'
        ELSE EXCLUDED.matching_status
      END,
      metadata = financial_obligations.metadata || EXCLUDED.metadata,
      updated_at = now()
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_settlements FROM upsert;

  -- Payables → outflow / payable
  WITH src AS (
    SELECT p.*
    FROM public.payables p
    WHERE p.tenant_id = _tenant_id
      AND (_date_from IS NULL OR COALESCE(p.due_date, p.created_at::date) >= _date_from)
      AND (_date_to   IS NULL OR COALESCE(p.due_date, p.created_at::date) <= _date_to)
  ),
  upsert AS (
    INSERT INTO public.financial_obligations (
      tenant_id, direction, obligation_type, source_table, source_id,
      description, counterparty_type, counterparty_id, counterparty_name,
      amount_expected, amount_matched,
      due_date, expected_payment_date, competence_date,
      status, matching_status, metadata, created_by
    )
    SELECT
      s.tenant_id, 'outflow', 'payable', 'payables', s.id,
      COALESCE(s.description, s.supplier_name, 'Conta a pagar'),
      'supplier', s.supplier_id, s.supplier_name,
      s.amount,
      CASE WHEN s.status = 'paid' THEN s.amount ELSE 0 END,
      s.due_date, s.paid_at::date, s.competence_date,
      CASE
        WHEN s.status = 'cancelled' THEN 'cancelled'
        WHEN s.status = 'paid'      THEN 'paid'
        ELSE 'pending'
      END,
      CASE WHEN s.status = 'paid' THEN 'matched' ELSE 'unmatched' END,
      jsonb_build_object(
        'category', s.category,
        'vehicle_id', s.vehicle_id,
        'driver_id', s.driver_id,
        'dispatch_trip_id', s.dispatch_trip_id,
        'load_id', s.load_id,
        'document_number', s.document_number
      ),
      s.created_by
    FROM src s
    ON CONFLICT (tenant_id, source_table, source_id, obligation_type)
      WHERE source_table IS NOT NULL AND source_id IS NOT NULL
    DO UPDATE SET
      amount_expected = EXCLUDED.amount_expected,
      amount_matched  = GREATEST(financial_obligations.amount_matched, EXCLUDED.amount_matched),
      due_date        = EXCLUDED.due_date,
      description     = EXCLUDED.description,
      counterparty_id = EXCLUDED.counterparty_id,
      counterparty_name = EXCLUDED.counterparty_name,
      status = CASE
        WHEN financial_obligations.status IN ('cancelled','written_off') THEN financial_obligations.status
        ELSE EXCLUDED.status
      END,
      matching_status = CASE
        WHEN financial_obligations.matching_status = 'matched' THEN 'matched'
        ELSE EXCLUDED.matching_status
      END,
      metadata = financial_obligations.metadata || EXCLUDED.metadata,
      updated_at = now()
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_payables FROM upsert;

  -- Driver expenses paid by the company (not reimbursable) → outflow / driver_expense
  WITH src AS (
    SELECT e.*
    FROM public.driver_expenses e
    WHERE e.tenant_id = _tenant_id
      AND e.approval_status = 'approved'
      AND COALESCE(e.reimbursable, false) = false
      AND COALESCE(e.payment_source, 'driver') <> 'driver'
      AND (_date_from IS NULL OR e.expense_at::date >= _date_from)
      AND (_date_to   IS NULL OR e.expense_at::date <= _date_to)
  ),
  upsert AS (
    INSERT INTO public.financial_obligations (
      tenant_id, direction, obligation_type, source_table, source_id,
      description, counterparty_type, counterparty_id,
      amount_expected, amount_matched,
      due_date, expected_payment_date, competence_date,
      status, matching_status, metadata, created_by
    )
    SELECT
      s.tenant_id, 'outflow', 'driver_expense', 'driver_expenses', s.id,
      COALESCE(s.notes, s.category, 'Despesa operacional'),
      'driver', s.driver_id,
      s.amount, 0,
      s.expense_at::date, s.expense_at::date, s.expense_at::date,
      'pending','unmatched',
      jsonb_build_object(
        'category', s.category,
        'payment_source', s.payment_source,
        'dispatch_trip_id', s.dispatch_trip_id
      ),
      s.approved_by
    FROM src s
    ON CONFLICT (tenant_id, source_table, source_id, obligation_type)
      WHERE source_table IS NOT NULL AND source_id IS NOT NULL
    DO UPDATE SET
      amount_expected = EXCLUDED.amount_expected,
      description     = EXCLUDED.description,
      counterparty_id = EXCLUDED.counterparty_id,
      metadata = financial_obligations.metadata || EXCLUDED.metadata,
      updated_at = now()
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_expenses FROM upsert;

  RETURN jsonb_build_object(
    'receivables', v_receivables,
    'driver_settlements', v_settlements,
    'payables', v_payables,
    'driver_expenses', v_expenses
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.import_bank_statement(_tenant_id uuid, _bank_account_id uuid, _file_name text, _file_hash text, _period_start date, _period_end date, _rows jsonb, _raw_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_import_id UUID;
  v_user UUID := auth.uid();
  v_inserted INT := 0;
  v_skipped  INT := 0;
  v_inflow   NUMERIC := 0;
  v_outflow  NUMERIC := 0;
  v_existing UUID;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF _bank_account_id IS NULL OR _file_hash IS NULL OR trim(_file_hash) = '' THEN
    RAISE EXCEPTION 'invalid_arguments';
  END IF;

  -- Ensure bank account belongs to tenant
  IF NOT EXISTS (
    SELECT 1 FROM public.bank_accounts
    WHERE id = _bank_account_id AND tenant_id = _tenant_id
  ) THEN
    RAISE EXCEPTION 'bank_account_not_found';
  END IF;

  -- Reject duplicate file for same account
  SELECT id INTO v_existing
  FROM public.bank_statement_imports
  WHERE tenant_id = _tenant_id
    AND bank_account_id = _bank_account_id
    AND file_hash = _file_hash;
  IF v_existing IS NOT NULL THEN
    RAISE EXCEPTION 'duplicate_import' USING DETAIL = v_existing::text;
  END IF;

  INSERT INTO public.bank_statement_imports (
    tenant_id, bank_account_id, file_name, file_hash,
    period_start, period_end, imported_by, status, raw_metadata
  )
  VALUES (
    _tenant_id, _bank_account_id, _file_name, _file_hash,
    _period_start, _period_end, v_user, 'imported', COALESCE(_raw_metadata,'{}'::jsonb)
  )
  RETURNING id INTO v_import_id;

  WITH ins AS (
    INSERT INTO public.bank_transactions (
      tenant_id, bank_account_id, import_id,
      posted_at, description, normalized_description, amount, transaction_type,
      external_id, document_number, counterparty_name, balance_after,
      raw_payload, normalized_key, reconciliation_status
    )
    SELECT
      _tenant_id,
      _bank_account_id,
      v_import_id,
      COALESCE((r->>'posted_at')::timestamptz, now()),
      NULLIF(r->>'description',''),
      lower(regexp_replace(COALESCE(r->>'description',''), '\s+', ' ', 'g')),
      (r->>'amount')::numeric,
      CASE WHEN (r->>'amount')::numeric >= 0 THEN 'credit' ELSE 'debit' END,
      NULLIF(r->>'external_id',''),
      NULLIF(r->>'document_number',''),
      NULLIF(r->>'counterparty_name',''),
      NULLIF(r->>'balance_after','')::numeric,
      COALESCE(r->'raw', r),
      NULLIF(r->>'normalized_key',''),
      'unmatched'
    FROM jsonb_array_elements(COALESCE(_rows,'[]'::jsonb)) r
    WHERE (r->>'amount') IS NOT NULL
    ON CONFLICT (tenant_id, bank_account_id, normalized_key)
      WHERE normalized_key IS NOT NULL
    DO NOTHING
    RETURNING amount
  )
  SELECT
    COUNT(*),
    COALESCE(SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END),0),
    COALESCE(SUM(CASE WHEN amount < 0 THEN -amount ELSE 0 END),0)
  INTO v_inserted, v_inflow, v_outflow
  FROM ins;

  v_skipped := jsonb_array_length(COALESCE(_rows,'[]'::jsonb)) - v_inserted;

  UPDATE public.bank_statement_imports
     SET rows_count = v_inserted,
         total_inflow = v_inflow,
         total_outflow = v_outflow,
         updated_at = now()
   WHERE id = v_import_id;

  INSERT INTO public.bank_reconciliation_audit (
    tenant_id, action, entity_table, entity_id, payload, user_id
  )
  VALUES (
    _tenant_id, 'imported_statement', 'bank_statement_imports', v_import_id,
    jsonb_build_object(
      'bank_account_id', _bank_account_id,
      'file_name', _file_name,
      'file_hash', _file_hash,
      'rows_inserted', v_inserted,
      'rows_skipped', v_skipped,
      'total_inflow', v_inflow,
      'total_outflow', v_outflow
    ),
    v_user
  );

  RETURN jsonb_build_object(
    'import_id', v_import_id,
    'rows_inserted', v_inserted,
    'rows_skipped', v_skipped,
    'total_inflow', v_inflow,
    'total_outflow', v_outflow
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public._apply_match_amounts(_obligation_id uuid, _transaction_id uuid, _delta numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_matched NUMERIC;
  v_expected NUMERIC;
  v_tx_amount NUMERIC;
  v_tx_used NUMERIC;
BEGIN
  UPDATE public.financial_obligations
     SET amount_matched = amount_matched + _delta,
         updated_at = now()
   WHERE id = _obligation_id
   RETURNING amount_matched, amount_expected INTO v_new_matched, v_expected;

  UPDATE public.financial_obligations
     SET status = CASE
           WHEN status IN ('cancelled','written_off') THEN status
           WHEN v_new_matched <= 0 THEN 'pending'
           WHEN v_new_matched >= v_expected THEN 'paid'
           ELSE 'partially_paid'
         END,
         matching_status = CASE
           WHEN v_new_matched <= 0 THEN 'unmatched'
           WHEN v_new_matched >= v_expected THEN 'matched'
           ELSE 'partial'
         END
   WHERE id = _obligation_id;

  -- Compute how much of the transaction is used by all accepted matches
  SELECT abs(bt.amount),
         COALESCE(SUM(fm.amount_matched) FILTER (WHERE fm.status = 'accepted'), 0)
    INTO v_tx_amount, v_tx_used
    FROM public.bank_transactions bt
    LEFT JOIN public.financial_matches fm ON fm.bank_transaction_id = bt.id
   WHERE bt.id = _transaction_id
   GROUP BY bt.amount;

  UPDATE public.bank_transactions
     SET reconciliation_status = CASE
           WHEN v_tx_used <= 0 THEN 'unmatched'
           WHEN v_tx_used >= v_tx_amount THEN 'matched'
           ELSE 'manual_review'
         END,
         updated_at = now()
   WHERE id = _transaction_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.run_bank_reconciliation(_tenant_id uuid, _bank_account_id uuid, _period_start date, _period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_auto INT := 0;
  v_suggested INT := 0;
  v_scanned INT := 0;
  r_tx RECORD;
  r_best RECORD;
  r_second RECORD;
  v_score NUMERIC;
  v_direction TEXT;
  v_abs NUMERIC;
  v_norm_desc TEXT;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  FOR r_tx IN
    SELECT id, amount, posted_at, description, normalized_description,
           counterparty_name, document_number
      FROM public.bank_transactions
     WHERE tenant_id = _tenant_id
       AND bank_account_id = _bank_account_id
       AND posted_at::date BETWEEN _period_start AND _period_end
       AND reconciliation_status IN ('unmatched','suggested')
  LOOP
    v_scanned := v_scanned + 1;
    v_direction := CASE WHEN r_tx.amount >= 0 THEN 'inflow' ELSE 'outflow' END;
    v_abs := abs(r_tx.amount);
    v_norm_desc := lower(coalesce(r_tx.normalized_description, r_tx.description, ''));

    -- Score candidates and pick top 2
    WITH cand AS (
      SELECT o.id,
             o.amount_expected - o.amount_matched AS open_balance,
             o.counterparty_name,
             o.description,
             o.due_date,
             o.metadata,
             (
               -- amount closeness
               CASE
                 WHEN (o.amount_expected - o.amount_matched) = v_abs THEN 50
                 WHEN abs((o.amount_expected - o.amount_matched) - v_abs) <= 0.02 THEN 45
                 WHEN v_abs > 0 AND abs((o.amount_expected - o.amount_matched) - v_abs) / v_abs <= 0.01 THEN 30
                 ELSE 0
               END
               +
               -- date proximity (based on due_date)
               CASE
                 WHEN o.due_date IS NULL THEN 5
                 WHEN abs(EXTRACT(DAY FROM (r_tx.posted_at::date - o.due_date))) <= 3 THEN 20
                 WHEN abs(EXTRACT(DAY FROM (r_tx.posted_at::date - o.due_date))) <= 7 THEN 10
                 ELSE 0
               END
               +
               -- counterparty in description
               CASE
                 WHEN o.counterparty_name IS NOT NULL
                      AND length(o.counterparty_name) >= 4
                      AND position(lower(o.counterparty_name) IN v_norm_desc) > 0 THEN 20
                 ELSE 0
               END
               +
               -- document match
               CASE
                 WHEN r_tx.document_number IS NOT NULL
                      AND (o.metadata->>'document_number' = r_tx.document_number
                           OR o.metadata->>'invoice_number' = r_tx.document_number) THEN 20
                 ELSE 0
               END
             ) AS score
        FROM public.financial_obligations o
       WHERE o.tenant_id = _tenant_id
         AND o.direction = v_direction
         AND o.status NOT IN ('paid','cancelled','written_off')
         AND o.matching_status <> 'matched'
         AND (o.amount_expected - o.amount_matched) > 0
    )
    SELECT * INTO r_best FROM cand ORDER BY score DESC, open_balance ASC LIMIT 1;

    IF r_best IS NULL OR r_best.score < 70 THEN
      CONTINUE;
    END IF;

    SELECT * INTO r_second FROM (
      SELECT * FROM (
        WITH cand AS (
          SELECT o.id,
                 o.amount_expected - o.amount_matched AS open_balance,
                 (
                   CASE
                     WHEN (o.amount_expected - o.amount_matched) = v_abs THEN 50
                     WHEN abs((o.amount_expected - o.amount_matched) - v_abs) <= 0.02 THEN 45
                     WHEN v_abs > 0 AND abs((o.amount_expected - o.amount_matched) - v_abs) / v_abs <= 0.01 THEN 30
                     ELSE 0
                   END
                   +
                   CASE
                     WHEN o.due_date IS NULL THEN 5
                     WHEN abs(EXTRACT(DAY FROM (r_tx.posted_at::date - o.due_date))) <= 3 THEN 20
                     WHEN abs(EXTRACT(DAY FROM (r_tx.posted_at::date - o.due_date))) <= 7 THEN 10
                     ELSE 0
                   END
                   +
                   CASE
                     WHEN o.counterparty_name IS NOT NULL
                          AND length(o.counterparty_name) >= 4
                          AND position(lower(o.counterparty_name) IN v_norm_desc) > 0 THEN 20
                     ELSE 0
                   END
                   +
                   CASE
                     WHEN r_tx.document_number IS NOT NULL
                          AND (o.metadata->>'document_number' = r_tx.document_number
                               OR o.metadata->>'invoice_number' = r_tx.document_number) THEN 20
                     ELSE 0
                   END
                 ) AS score
            FROM public.financial_obligations o
           WHERE o.tenant_id = _tenant_id
             AND o.direction = v_direction
             AND o.status NOT IN ('paid','cancelled','written_off')
             AND o.matching_status <> 'matched'
             AND (o.amount_expected - o.amount_matched) > 0
             AND o.id <> r_best.id
        )
        SELECT id, score FROM cand ORDER BY score DESC LIMIT 1
      ) x
    ) AS y;

    v_score := LEAST(r_best.score, 100);

    -- Decide auto vs suggested
    IF v_score >= 90 AND (r_second IS NULL OR r_second.score < 80) THEN
      -- auto-accept 1:1 for the amount that fits
      INSERT INTO public.financial_matches (
        tenant_id, bank_transaction_id, financial_obligation_id,
        amount_matched, confidence_score, match_type, status,
        created_by, accepted_by, accepted_at
      ) VALUES (
        _tenant_id, r_tx.id, r_best.id,
        LEAST(v_abs, r_best.open_balance), v_score, 'auto', 'accepted',
        v_user, v_user, now()
      );
      PERFORM public._apply_match_amounts(r_best.id, r_tx.id, LEAST(v_abs, r_best.open_balance));
      INSERT INTO public.bank_reconciliation_audit (tenant_id, action, entity_table, entity_id, payload, user_id)
      VALUES (_tenant_id, 'match_accepted', 'bank_transactions', r_tx.id,
              jsonb_build_object('obligation_id', r_best.id, 'score', v_score, 'auto', true), v_user);
      v_auto := v_auto + 1;
    ELSE
      -- suggested
      INSERT INTO public.financial_matches (
        tenant_id, bank_transaction_id, financial_obligation_id,
        amount_matched, confidence_score, match_type, status, created_by
      ) VALUES (
        _tenant_id, r_tx.id, r_best.id,
        LEAST(v_abs, r_best.open_balance), v_score, 'suggested', 'suggested',
        v_user
      )
      ON CONFLICT DO NOTHING;
      UPDATE public.bank_transactions SET reconciliation_status = 'suggested' WHERE id = r_tx.id AND reconciliation_status = 'unmatched';
      UPDATE public.financial_obligations SET matching_status = CASE WHEN matching_status='matched' THEN 'matched' ELSE 'suggested' END WHERE id = r_best.id;
      INSERT INTO public.bank_reconciliation_audit (tenant_id, action, entity_table, entity_id, payload, user_id)
      VALUES (_tenant_id, 'match_suggested', 'bank_transactions', r_tx.id,
              jsonb_build_object('obligation_id', r_best.id, 'score', v_score), v_user);
      v_suggested := v_suggested + 1;
    END IF;
  END LOOP;

  INSERT INTO public.bank_reconciliation_audit (tenant_id, action, entity_table, entity_id, payload, user_id)
  VALUES (_tenant_id, 'auto_match_run', 'bank_accounts', _bank_account_id,
          jsonb_build_object('period_start', _period_start, 'period_end', _period_end,
                             'scanned', v_scanned, 'auto', v_auto, 'suggested', v_suggested),
          v_user);

  RETURN jsonb_build_object('scanned', v_scanned, 'auto', v_auto, 'suggested', v_suggested);
END;
$function$;

CREATE OR REPLACE FUNCTION public.accept_financial_match(_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_m public.financial_matches%ROWTYPE;
  v_user UUID := auth.uid();
BEGIN
  SELECT * INTO v_m FROM public.financial_matches WHERE id = _match_id FOR UPDATE;
  IF v_m.id IS NULL THEN RAISE EXCEPTION 'match_not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(v_m.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF v_m.status <> 'suggested' THEN RAISE EXCEPTION 'invalid_status'; END IF;

  UPDATE public.financial_matches
     SET status = 'accepted', accepted_by = v_user, accepted_at = now(), updated_at = now()
   WHERE id = _match_id;

  PERFORM public._apply_match_amounts(v_m.financial_obligation_id, v_m.bank_transaction_id, v_m.amount_matched);

  INSERT INTO public.bank_reconciliation_audit (tenant_id, action, entity_table, entity_id, payload, user_id)
  VALUES (v_m.tenant_id, 'match_accepted', 'financial_matches', _match_id,
          jsonb_build_object('obligation_id', v_m.financial_obligation_id,
                             'transaction_id', v_m.bank_transaction_id,
                             'amount', v_m.amount_matched), v_user);
END;
$function$;

CREATE OR REPLACE FUNCTION public.reject_financial_match(_match_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_m public.financial_matches%ROWTYPE;
  v_user UUID := auth.uid();
  v_still INT;
BEGIN
  SELECT * INTO v_m FROM public.financial_matches WHERE id = _match_id FOR UPDATE;
  IF v_m.id IS NULL THEN RAISE EXCEPTION 'match_not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(v_m.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF v_m.status <> 'suggested' THEN RAISE EXCEPTION 'invalid_status'; END IF;
  IF _reason IS NULL OR trim(_reason) = '' THEN RAISE EXCEPTION 'reason_required'; END IF;

  UPDATE public.financial_matches
     SET status = 'rejected', reason = _reason, updated_at = now()
   WHERE id = _match_id;

  -- If no more suggestions/accepted for this tx, mark as unmatched
  SELECT COUNT(*) INTO v_still FROM public.financial_matches
    WHERE bank_transaction_id = v_m.bank_transaction_id AND status IN ('suggested','accepted');
  IF v_still = 0 THEN
    UPDATE public.bank_transactions SET reconciliation_status = 'unmatched', updated_at = now()
     WHERE id = v_m.bank_transaction_id;
  END IF;

  SELECT COUNT(*) INTO v_still FROM public.financial_matches
    WHERE financial_obligation_id = v_m.financial_obligation_id AND status IN ('suggested','accepted');
  IF v_still = 0 THEN
    UPDATE public.financial_obligations
       SET matching_status = CASE
             WHEN amount_matched <= 0 THEN 'unmatched'
             WHEN amount_matched >= amount_expected THEN 'matched'
             ELSE 'partial'
           END
     WHERE id = v_m.financial_obligation_id;
  END IF;

  INSERT INTO public.bank_reconciliation_audit (tenant_id, action, entity_table, entity_id, payload, reason, user_id)
  VALUES (v_m.tenant_id, 'match_rejected', 'financial_matches', _match_id,
          jsonb_build_object('obligation_id', v_m.financial_obligation_id,
                             'transaction_id', v_m.bank_transaction_id), _reason, v_user);
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_manual_financial_match(_tenant_id uuid, _bank_transaction_id uuid, _financial_obligation_id uuid, _amount_matched numeric, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx public.bank_transactions%ROWTYPE;
  v_ob public.financial_obligations%ROWTYPE;
  v_tx_used NUMERIC;
  v_tx_avail NUMERIC;
  v_ob_avail NUMERIC;
  v_user UUID := auth.uid();
  v_new_id UUID;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF _amount_matched IS NULL OR _amount_matched <= 0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;

  SELECT * INTO v_tx FROM public.bank_transactions
   WHERE id = _bank_transaction_id AND tenant_id = _tenant_id FOR UPDATE;
  IF v_tx.id IS NULL THEN RAISE EXCEPTION 'transaction_not_found'; END IF;

  SELECT * INTO v_ob FROM public.financial_obligations
   WHERE id = _financial_obligation_id AND tenant_id = _tenant_id FOR UPDATE;
  IF v_ob.id IS NULL THEN RAISE EXCEPTION 'obligation_not_found'; END IF;

  -- Direction must match
  IF (v_tx.amount >= 0 AND v_ob.direction <> 'inflow')
     OR (v_tx.amount < 0 AND v_ob.direction <> 'outflow') THEN
    RAISE EXCEPTION 'direction_mismatch';
  END IF;

  SELECT COALESCE(SUM(amount_matched),0) INTO v_tx_used
    FROM public.financial_matches
   WHERE bank_transaction_id = _bank_transaction_id AND status = 'accepted';
  v_tx_avail := abs(v_tx.amount) - v_tx_used;
  v_ob_avail := v_ob.amount_expected - v_ob.amount_matched;

  IF _amount_matched > v_tx_avail + 0.001 THEN RAISE EXCEPTION 'exceeds_transaction_balance'; END IF;
  IF _amount_matched > v_ob_avail + 0.001 THEN RAISE EXCEPTION 'exceeds_obligation_balance'; END IF;

  INSERT INTO public.financial_matches (
    tenant_id, bank_transaction_id, financial_obligation_id,
    amount_matched, confidence_score, match_type, status,
    reason, created_by, accepted_by, accepted_at
  ) VALUES (
    _tenant_id, _bank_transaction_id, _financial_obligation_id,
    _amount_matched, NULL, 'manual', 'accepted',
    _reason, v_user, v_user, now()
  ) RETURNING id INTO v_new_id;

  PERFORM public._apply_match_amounts(_financial_obligation_id, _bank_transaction_id, _amount_matched);

  INSERT INTO public.bank_reconciliation_audit (tenant_id, action, entity_table, entity_id, payload, reason, user_id)
  VALUES (_tenant_id, 'manual_match_created', 'financial_matches', v_new_id,
          jsonb_build_object('obligation_id', _financial_obligation_id,
                             'transaction_id', _bank_transaction_id,
                             'amount', _amount_matched), _reason, v_user);

  RETURN v_new_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reverse_financial_match(_match_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_m public.financial_matches%ROWTYPE;
  v_user UUID := auth.uid();
BEGIN
  SELECT * INTO v_m FROM public.financial_matches WHERE id = _match_id FOR UPDATE;
  IF v_m.id IS NULL THEN RAISE EXCEPTION 'match_not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(v_m.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF v_m.status <> 'accepted' THEN RAISE EXCEPTION 'invalid_status'; END IF;
  IF _reason IS NULL OR trim(_reason) = '' THEN RAISE EXCEPTION 'reason_required'; END IF;

  UPDATE public.financial_matches
     SET status = 'reversed', reason = COALESCE(reason,'') || ' | reverse: ' || _reason, updated_at = now()
   WHERE id = _match_id;

  PERFORM public._apply_match_amounts(v_m.financial_obligation_id, v_m.bank_transaction_id, - v_m.amount_matched);

  INSERT INTO public.bank_reconciliation_audit (tenant_id, action, entity_table, entity_id, payload, reason, user_id)
  VALUES (v_m.tenant_id, 'match_reversed', 'financial_matches', _match_id,
          jsonb_build_object('obligation_id', v_m.financial_obligation_id,
                             'transaction_id', v_m.bank_transaction_id,
                             'amount', v_m.amount_matched), _reason, v_user);
END;
$function$;

CREATE OR REPLACE FUNCTION public.close_reconciliation_session(_session_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_s public.bank_reconciliation_sessions%ROWTYPE;
  v_user UUID := auth.uid();
  v_in NUMERIC; v_out NUMERIC; v_matched NUMERIC;
BEGIN
  SELECT * INTO v_s FROM public.bank_reconciliation_sessions WHERE id = _session_id FOR UPDATE;
  IF v_s.id IS NULL THEN RAISE EXCEPTION 'session_not_found'; END IF;
  IF NOT public.is_tenant_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'admin_required'; END IF;
  IF v_s.status = 'closed' THEN RAISE EXCEPTION 'already_closed'; END IF;

  SELECT
    COALESCE(SUM(CASE WHEN bt.amount > 0 THEN bt.amount ELSE 0 END),0),
    COALESCE(SUM(CASE WHEN bt.amount < 0 THEN -bt.amount ELSE 0 END),0),
    COALESCE(SUM(CASE WHEN bt.reconciliation_status = 'matched' THEN abs(bt.amount) ELSE 0 END),0)
  INTO v_in, v_out, v_matched
  FROM public.bank_transactions bt
  WHERE bt.tenant_id = v_s.tenant_id
    AND bt.bank_account_id = v_s.bank_account_id
    AND bt.posted_at::date BETWEEN v_s.period_start AND v_s.period_end;

  UPDATE public.bank_reconciliation_sessions
     SET status = 'closed',
         total_bank_inflow = v_in,
         total_bank_outflow = v_out,
         total_matched = v_matched,
         total_unmatched = (v_in + v_out) - v_matched,
         closed_by = v_user,
         closed_at = now(),
         updated_at = now()
   WHERE id = _session_id;

  INSERT INTO public.bank_reconciliation_audit (tenant_id, action, entity_table, entity_id, session_id, payload, user_id)
  VALUES (v_s.tenant_id, 'session_closed', 'bank_reconciliation_sessions', _session_id, _session_id,
          jsonb_build_object('total_inflow', v_in, 'total_outflow', v_out, 'total_matched', v_matched), v_user);
END;
$function$;

CREATE OR REPLACE FUNCTION public.reopen_reconciliation_session(_session_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_s public.bank_reconciliation_sessions%ROWTYPE;
  v_user UUID := auth.uid();
BEGIN
  SELECT * INTO v_s FROM public.bank_reconciliation_sessions WHERE id = _session_id FOR UPDATE;
  IF v_s.id IS NULL THEN RAISE EXCEPTION 'session_not_found'; END IF;
  IF NOT public.is_tenant_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'admin_required'; END IF;
  IF v_s.status <> 'closed' THEN RAISE EXCEPTION 'not_closed'; END IF;
  IF _reason IS NULL OR trim(_reason) = '' THEN RAISE EXCEPTION 'reason_required'; END IF;

  UPDATE public.bank_reconciliation_sessions
     SET status = 'reopened',
         reopened_by = v_user,
         reopened_at = now(),
         reopen_reason = _reason,
         updated_at = now()
   WHERE id = _session_id;

  INSERT INTO public.bank_reconciliation_audit (tenant_id, action, entity_table, entity_id, session_id, payload, reason, user_id)
  VALUES (v_s.tenant_id, 'session_reopened', 'bank_reconciliation_sessions', _session_id, _session_id,
          jsonb_build_object('previous_closed_at', v_s.closed_at), _reason, v_user);
END;
$function$;

CREATE OR REPLACE FUNCTION public.driver_create_expense(_trip_id uuid, _category text, _amount numeric, _notes text DEFAULT NULL::text, _receipt_path text DEFAULT NULL::text, _expense_at timestamp with time zone DEFAULT now(), _supplier_name text DEFAULT NULL::text, _document_number text DEFAULT NULL::text, _city text DEFAULT NULL::text, _state text DEFAULT NULL::text, _odometer numeric DEFAULT NULL::numeric, _no_receipt boolean DEFAULT false, _no_receipt_reason text DEFAULT NULL::text, _paid_with_advance boolean DEFAULT false, _payment_source text DEFAULT 'driver'::text, _reimbursable boolean DEFAULT NULL::boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_driver uuid; v_id uuid;
  v_reimbursable boolean;
  v_payment_source text;
BEGIN
  SELECT driver_id, tenant_id INTO v_driver, v_tenant FROM public._assert_driver_owns_trip(_trip_id);

  IF _amount IS NULL OR _amount <= 0 THEN RAISE EXCEPTION 'amount_invalid'; END IF;
  IF _category IS NULL OR length(_category) = 0 THEN RAISE EXCEPTION 'category_required'; END IF;

  IF COALESCE(_no_receipt, false) = true
     AND length(trim(COALESCE(_no_receipt_reason,''))) = 0 THEN
    RAISE EXCEPTION 'no_receipt_reason_required';
  END IF;

  v_payment_source := COALESCE(NULLIF(trim(_payment_source), ''), 'driver');
  IF v_payment_source NOT IN ('driver','company_card','company_account','advance','other') THEN
    RAISE EXCEPTION 'invalid_payment_source';
  END IF;

  IF _reimbursable IS NULL THEN
    v_reimbursable := CASE
      WHEN v_payment_source IN ('driver','advance') THEN true
      WHEN v_payment_source IN ('company_card','company_account') THEN false
      ELSE true
    END;
  ELSE
    v_reimbursable := _reimbursable;
  END IF;

  INSERT INTO public.driver_expenses(
    tenant_id, dispatch_trip_id, driver_id, category, amount,
    expense_at, receipt_url, notes, approval_status,
    supplier_name, document_number, city, state, odometer,
    no_receipt, no_receipt_reason, paid_with_advance,
    payment_source, reimbursable
  ) VALUES (
    v_tenant, _trip_id, v_driver, _category, _amount,
    COALESCE(_expense_at, now()), _receipt_path, _notes, 'pending',
    _supplier_name, _document_number, _city, _state, _odometer,
    COALESCE(_no_receipt, false), _no_receipt_reason, COALESCE(_paid_with_advance, false),
    v_payment_source, v_reimbursable
  ) RETURNING id INTO v_id;

  RETURN v_id;
END; $function$;

CREATE OR REPLACE FUNCTION public._tg_sync_obligations_from_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_from date; v_to date;
BEGIN
  IF NEW.status IN ('approved','paid','closed')
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status
          OR OLD.driver_payable_amount IS DISTINCT FROM NEW.driver_payable_amount) THEN
    v_from := COALESCE(NEW.trip_started_at::date, (now() - INTERVAL '60 days')::date);
    v_to   := (COALESCE(NEW.trip_completed_at::date, now()::date) + INTERVAL '1 day')::date;
    PERFORM public.sync_financial_obligations(NEW.tenant_id, v_from, v_to);
  END IF;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public._tg_sync_obligations_from_settlement_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_s public.driver_settlements; v_from date; v_to date;
BEGIN
  SELECT * INTO v_s FROM public.driver_settlements WHERE id = NEW.settlement_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  v_from := COALESCE(v_s.trip_started_at::date, (now() - INTERVAL '60 days')::date);
  v_to   := (COALESCE(v_s.trip_completed_at::date, now()::date) + INTERVAL '1 day')::date;
  PERFORM public.sync_financial_obligations(v_s.tenant_id, v_from, v_to);
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public._tg_sync_obligations_from_expense()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_from date; v_to date;
BEGIN
  IF NEW.approval_status = 'approved'
     AND COALESCE(NEW.reimbursable, false) = false
     AND COALESCE(NEW.payment_source,'driver') <> 'driver' THEN
    v_from := (NEW.expense_at::date - INTERVAL '1 day')::date;
    v_to   := (NEW.expense_at::date + INTERVAL '1 day')::date;
    PERFORM public.sync_financial_obligations(NEW.tenant_id, v_from, v_to);
  END IF;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public._tg_sync_obligations_from_payable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_from date; v_to date; v_row public.payables;
BEGIN
  v_row := COALESCE(NEW, OLD);
  v_from := COALESCE(v_row.due_date, v_row.competence_date, (now() - INTERVAL '60 days')::date) - INTERVAL '1 day';
  v_to   := COALESCE(v_row.due_date, v_row.competence_date, now()::date) + INTERVAL '30 days';
  PERFORM public.sync_financial_obligations(v_row.tenant_id, v_from::date, v_to::date);
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public.tg_client_invoices_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.next_client_invoice_number(_tenant_id uuid, _issue_date date DEFAULT CURRENT_DATE, _installment integer DEFAULT 1)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year integer := EXTRACT(YEAR FROM _issue_date)::int;
  v_next integer;
BEGIN
  IF NOT public.is_tenant_member(_tenant_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  INSERT INTO public.client_invoice_sequences(tenant_id, sequence_year, next_number)
  VALUES (_tenant_id, v_year, 2)
  ON CONFLICT (tenant_id, sequence_year)
  DO UPDATE SET next_number = client_invoice_sequences.next_number + 1,
                updated_at = now()
  RETURNING next_number - 1 INTO v_next;

  RETURN v_next::text || '/' || LPAD(COALESCE(_installment,1)::text, 2, '0');
END;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_client_invoice(_invoice_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_receivable uuid;
  v_recv_status text;
BEGIN
  SELECT tenant_id, receivable_id INTO v_tenant, v_receivable
    FROM public.client_invoices WHERE id = _invoice_id;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'invoice not found';
  END IF;
  IF NOT public.is_tenant_member(v_tenant) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE public.client_invoices
     SET status = 'cancelled',
         cancelled_at = now(),
         cancellation_reason = _reason,
         updated_at = now()
   WHERE id = _invoice_id;

  UPDATE public.client_invoice_charges
     SET cancelled_at = now()
   WHERE invoice_id = _invoice_id AND cancelled_at IS NULL;

  IF v_receivable IS NOT NULL THEN
    SELECT status INTO v_recv_status FROM public.receivables WHERE id = v_receivable;
    IF v_recv_status IS NOT NULL AND v_recv_status <> 'received' THEN
      UPDATE public.receivables SET status = 'cancelled', updated_at = now() WHERE id = v_receivable;
    END IF;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_client_invoice(payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := (payload->>'tenant_id')::uuid;
  v_client uuid := (payload->>'client_id')::uuid;
  v_issue date := COALESCE((payload->>'issue_date')::date, CURRENT_DATE);
  v_due date := NULLIF(payload->>'due_date','')::date;
  v_install int := COALESCE((payload->>'installment_number')::int, 1);
  v_discount numeric(14,2) := COALESCE((payload->>'discount_amount')::numeric, 0);
  v_interest numeric(14,2) := COALESCE((payload->>'interest_amount')::numeric, 0);
  v_notes text := payload->>'notes';
  v_number text;
  v_seq int;
  v_invoice_id uuid;
  v_charge jsonb;
  v_charge_id uuid;
  v_detail jsonb;
  v_gross numeric(14,2) := 0;
  v_total numeric(14,2);
  v_charges_count int;
  v_receivable_id uuid;
  v_client_name text;
  v_year int := EXTRACT(YEAR FROM v_issue)::int;
BEGIN
  IF v_tenant IS NULL OR v_client IS NULL THEN
    RAISE EXCEPTION 'tenant_id and client_id required';
  END IF;
  IF NOT public.is_tenant_member(v_tenant) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  v_charges_count := jsonb_array_length(COALESCE(payload->'charges','[]'::jsonb));
  IF v_charges_count = 0 THEN
    RAISE EXCEPTION 'invoice requires at least one charge';
  END IF;

  -- Sum charges gross
  FOR v_charge IN SELECT * FROM jsonb_array_elements(payload->'charges') LOOP
    v_gross := v_gross + COALESCE((v_charge->>'gross_amount')::numeric, 0);
  END LOOP;

  v_total := v_gross - v_discount + v_interest;
  IF v_total < 0 THEN
    RAISE EXCEPTION 'total_amount cannot be negative';
  END IF;

  -- Generate number
  v_number := public.next_client_invoice_number(v_tenant, v_issue, v_install);
  v_seq := split_part(v_number, '/', 1)::int;

  -- Insert invoice
  INSERT INTO public.client_invoices(
    tenant_id, client_id, invoice_number, sequence_number, installment_number,
    issue_date, due_date, gross_amount, discount_amount, interest_amount, total_amount,
    status, notes, payer_snapshot, company_snapshot, created_by, updated_by
  ) VALUES (
    v_tenant, v_client, v_number, v_seq, v_install,
    v_issue, v_due, v_gross, v_discount, v_interest, v_total,
    'generated', v_notes,
    COALESCE(payload->'payer_snapshot','{}'::jsonb),
    COALESCE(payload->'company_snapshot','{}'::jsonb),
    auth.uid(), auth.uid()
  ) RETURNING id INTO v_invoice_id;

  -- Insert charges + details
  FOR v_charge IN SELECT * FROM jsonb_array_elements(payload->'charges') LOOP
    INSERT INTO public.client_invoice_charges(
      tenant_id, invoice_id, source_type, source_id, source_number, source_series,
      reference_number, issue_date, description, gross_amount, discount_amount,
      interest_amount, ir_amount, net_amount, sort_order, metadata
    ) VALUES (
      v_tenant, v_invoice_id, v_charge->>'source_type',
      NULLIF(v_charge->>'source_id','')::uuid,
      v_charge->>'source_number', v_charge->>'source_series',
      v_charge->>'reference_number',
      NULLIF(v_charge->>'issue_date','')::date,
      v_charge->>'description',
      COALESCE((v_charge->>'gross_amount')::numeric, 0),
      COALESCE((v_charge->>'discount_amount')::numeric, 0),
      COALESCE((v_charge->>'interest_amount')::numeric, 0),
      COALESCE((v_charge->>'ir_amount')::numeric, 0),
      COALESCE((v_charge->>'net_amount')::numeric, 0),
      COALESCE((v_charge->>'sort_order')::int, 0),
      COALESCE(v_charge->'metadata','{}'::jsonb)
    ) RETURNING id INTO v_charge_id;

    FOR v_detail IN SELECT * FROM jsonb_array_elements(COALESCE(v_charge->'details','[]'::jsonb)) LOOP
      INSERT INTO public.client_invoice_details(
        tenant_id, invoice_id, charge_id, source_type, source_id,
        emission_date, document_label, document_number, ort_number,
        destination, remitter, recipient, weight_kg, cargo_value,
        displayed_freight_value, notes, metadata, sort_order
      ) VALUES (
        v_tenant, v_invoice_id, v_charge_id,
        v_detail->>'source_type',
        NULLIF(v_detail->>'source_id','')::uuid,
        NULLIF(v_detail->>'emission_date','')::date,
        v_detail->>'document_label', v_detail->>'document_number',
        v_detail->>'ort_number', v_detail->>'destination',
        v_detail->>'remitter', v_detail->>'recipient',
        NULLIF(v_detail->>'weight_kg','')::numeric,
        NULLIF(v_detail->>'cargo_value','')::numeric,
        NULLIF(v_detail->>'displayed_freight_value','')::numeric,
        v_detail->>'notes',
        COALESCE(v_detail->'metadata','{}'::jsonb),
        COALESCE((v_detail->>'sort_order')::int, 0)
      );
    END LOOP;
  END LOOP;

  -- Create receivable
  SELECT company_name INTO v_client_name FROM public.clients WHERE id = v_client;

  INSERT INTO public.receivables(
    tenant_id, client_id, description, amount, due_date,
    invoice_number, status, notes, client_invoice_id, created_by
  ) VALUES (
    v_tenant, v_client,
    'Fatura ' || v_number || ' - ' || COALESCE(v_client_name, 'Cliente'),
    v_total, v_due, v_number, 'invoiced',
    v_notes, v_invoice_id, auth.uid()
  ) RETURNING id INTO v_receivable_id;

  UPDATE public.client_invoices SET receivable_id = v_receivable_id WHERE id = v_invoice_id;

  RETURN v_invoice_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.tg_billing_edi_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_doccob_export(_tenant_id uuid, _profile_id uuid, _client_id uuid, _client_invoice_ids uuid[], _file_name text, _file_date date, _generated_content text, _content_hash text, _record_count integer, _total_amount numeric, _charge_count integer, _detail_count integer, _reprocess_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_export_id uuid;
  v_invoice record;
  v_uid uuid := auth.uid();
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN
    RAISE EXCEPTION 'Permissão negada para gerar DOCCOB';
  END IF;
  IF _client_invoice_ids IS NULL OR array_length(_client_invoice_ids, 1) = 0 THEN
    RAISE EXCEPTION 'Nenhuma fatura selecionada';
  END IF;

  -- Valida faturas
  FOR v_invoice IN
    SELECT id, status, edi_status, total_amount, due_date, cancelled_at
    FROM public.client_invoices
    WHERE tenant_id = _tenant_id AND id = ANY(_client_invoice_ids)
  LOOP
    IF v_invoice.status IN ('draft','cancelled') OR v_invoice.cancelled_at IS NOT NULL THEN
      RAISE EXCEPTION 'Fatura % não está liberada (status=%)', v_invoice.id, v_invoice.status;
    END IF;
    IF v_invoice.due_date IS NULL THEN
      RAISE EXCEPTION 'Fatura % sem data de vencimento', v_invoice.id;
    END IF;
    IF COALESCE(v_invoice.total_amount, 0) <= 0 THEN
      RAISE EXCEPTION 'Fatura % com valor inválido', v_invoice.id;
    END IF;
    IF v_invoice.edi_status IN ('generated','sent') AND _reprocess_reason IS NULL THEN
      RAISE EXCEPTION 'Fatura % já possui arquivo EDI gerado. Informe motivo para reprocessar.', v_invoice.id;
    END IF;
  END LOOP;

  IF (SELECT count(*) FROM public.client_invoices
      WHERE tenant_id = _tenant_id AND id = ANY(_client_invoice_ids)) <> array_length(_client_invoice_ids, 1) THEN
    RAISE EXCEPTION 'Uma ou mais faturas não pertencem ao tenant';
  END IF;

  -- Se reprocessando, cancela itens ativos anteriores
  IF _reprocess_reason IS NOT NULL THEN
    UPDATE public.billing_edi_export_items
      SET status = 'cancelled'
    WHERE tenant_id = _tenant_id
      AND client_invoice_id = ANY(_client_invoice_ids)
      AND status = 'included';
  END IF;

  INSERT INTO public.billing_edi_exports (
    tenant_id, profile_id, client_id, file_name, file_date,
    status, invoice_count, charge_count, detail_count, record_count,
    total_amount, content_hash, generated_content, generated_by, reprocess_reason
  ) VALUES (
    _tenant_id, _profile_id, _client_id, _file_name, _file_date,
    'generated', array_length(_client_invoice_ids, 1), _charge_count, _detail_count, _record_count,
    _total_amount, _content_hash, _generated_content, v_uid, _reprocess_reason
  )
  RETURNING id INTO v_export_id;

  INSERT INTO public.billing_edi_export_items (
    tenant_id, export_id, client_invoice_id, receivable_id,
    invoice_number, issue_date, due_date, amount
  )
  SELECT _tenant_id, v_export_id, ci.id, ci.receivable_id,
         ci.invoice_number, ci.issue_date, ci.due_date, ci.total_amount
  FROM public.client_invoices ci
  WHERE ci.tenant_id = _tenant_id AND ci.id = ANY(_client_invoice_ids);

  UPDATE public.client_invoices
    SET edi_status = 'generated',
        last_edi_export_id = v_export_id,
        edi_generated_at = now()
  WHERE tenant_id = _tenant_id AND id = ANY(_client_invoice_ids);

  RETURN jsonb_build_object(
    'export_id', v_export_id,
    'file_name', _file_name,
    'invoice_count', array_length(_client_invoice_ids, 1),
    'record_count', _record_count,
    'total_amount', _total_amount
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.mark_doccob_sent(_tenant_id uuid, _export_id uuid, _channel text DEFAULT 'manual'::text, _sent_to text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN
    RAISE EXCEPTION 'Permissão negada';
  END IF;
  UPDATE public.billing_edi_exports
    SET status = 'sent', sent_at = now(), sent_channel = _channel, sent_to = _sent_to
  WHERE id = _export_id AND tenant_id = _tenant_id;
  UPDATE public.client_invoices ci
    SET edi_status = 'sent', edi_sent_at = now()
  FROM public.billing_edi_export_items it
  WHERE it.export_id = _export_id AND it.tenant_id = _tenant_id
    AND it.client_invoice_id = ci.id AND it.status = 'included';
END;
$function$;

CREATE OR REPLACE FUNCTION public.mark_doccob_downloaded(_tenant_id uuid, _export_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_tenant_member(_tenant_id) THEN
    RAISE EXCEPTION 'Permissão negada';
  END IF;
  UPDATE public.billing_edi_exports
    SET downloaded_at = COALESCE(downloaded_at, now()),
        status = CASE WHEN status = 'generated' THEN 'downloaded' ELSE status END
  WHERE id = _export_id AND tenant_id = _tenant_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_doccob_export(_tenant_id uuid, _export_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN
    RAISE EXCEPTION 'Permissão negada';
  END IF;
  UPDATE public.billing_edi_exports
    SET status = 'cancelled', cancelled_at = now(), cancellation_reason = _reason
  WHERE id = _export_id AND tenant_id = _tenant_id;
  UPDATE public.billing_edi_export_items
    SET status = 'cancelled'
  WHERE export_id = _export_id AND tenant_id = _tenant_id AND status = 'included';
  UPDATE public.client_invoices ci
    SET edi_status = 'not_generated', last_edi_export_id = NULL, edi_generated_at = NULL, edi_sent_at = NULL
  WHERE tenant_id = _tenant_id AND ci.last_edi_export_id = _export_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.next_closing_report_number(_tenant_id uuid, _date date DEFAULT CURRENT_DATE)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _year int := EXTRACT(YEAR FROM _date);
  _n int;
BEGIN
  IF NOT public.is_tenant_member(_tenant_id) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;
  INSERT INTO public.closing_report_sequences (tenant_id, sequence_year, next_number)
  VALUES (_tenant_id, _year, 2)
  ON CONFLICT (tenant_id, sequence_year)
  DO UPDATE SET next_number = closing_report_sequences.next_number + 1,
                updated_at = now()
  RETURNING next_number - 1 INTO _n;
  RETURN 'FCH-' || _year::text || '-' || lpad(_n::text, 4, '0');
END;
$function$;

CREATE OR REPLACE FUNCTION public.close_closing_report(_closing_report_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _r public.closing_reports;
BEGIN
  SELECT * INTO _r FROM public.closing_reports WHERE id = _closing_report_id;
  IF _r.id IS NULL THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(_r.tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.closing_report_items WHERE closing_report_id = _r.id) THEN
    RAISE EXCEPTION 'no_items';
  END IF;
  UPDATE public.closing_reports
     SET status = 'closed', closed_at = now(), closed_by = auth.uid(), updated_at = now(),
         open_amount = GREATEST(0, total_amount - received_amount)
   WHERE id = _r.id;
  INSERT INTO public.closing_report_history (tenant_id, closing_report_id, action, created_by)
  VALUES (_r.tenant_id, _r.id, 'closed', auth.uid());
END;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_closing_report(_closing_report_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _r public.closing_reports;
BEGIN
  SELECT * INTO _r FROM public.closing_reports WHERE id = _closing_report_id;
  IF _r.id IS NULL THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(_r.tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  UPDATE public.closing_reports
     SET status = 'cancelled', payment_status = 'cancelled',
         cancelled_at = now(), cancellation_reason = _reason, updated_at = now()
   WHERE id = _r.id;
  INSERT INTO public.closing_report_history (tenant_id, closing_report_id, action, reason, created_by)
  VALUES (_r.tenant_id, _r.id, 'cancelled', _reason, auth.uid());
END;
$function$;

CREATE OR REPLACE FUNCTION public.reopen_closing_report(_closing_report_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _r public.closing_reports;
BEGIN
  SELECT * INTO _r FROM public.closing_reports WHERE id = _closing_report_id;
  IF _r.id IS NULL THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.is_tenant_admin(_r.tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF _r.client_invoice_id IS NOT NULL OR _r.receivable_id IS NOT NULL THEN
    RAISE EXCEPTION 'has_linked_invoice_or_receivable';
  END IF;
  UPDATE public.closing_reports
     SET status = 'reviewing', closed_at = NULL, closed_by = NULL, updated_at = now()
   WHERE id = _r.id;
  INSERT INTO public.closing_report_history (tenant_id, closing_report_id, action, reason, created_by)
  VALUES (_r.tenant_id, _r.id, 'reopened', _reason, auth.uid());
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_closing_report_payment(_closing_report_id uuid, _payment jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _r public.closing_reports;
  _amt numeric := COALESCE((_payment->>'amount')::numeric, 0);
  _date date := COALESCE((_payment->>'payment_date')::date, current_date);
  _method text := _payment->>'payment_method';
  _notes text := _payment->>'notes';
  _received numeric;
  _new_status text;
  _pay_id uuid;
BEGIN
  SELECT * INTO _r FROM public.closing_reports WHERE id = _closing_report_id;
  IF _r.id IS NULL THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.is_tenant_operator_or_admin(_r.tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF _amt <= 0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;

  INSERT INTO public.closing_report_payments (tenant_id, closing_report_id, receivable_id, payment_date, amount, payment_method, notes, created_by)
  VALUES (_r.tenant_id, _r.id, _r.receivable_id, _date, _amt, _method, _notes, auth.uid())
  RETURNING id INTO _pay_id;

  _received := COALESCE(_r.received_amount,0) + _amt;
  IF _received <= 0 THEN _new_status := 'unpaid';
  ELSIF _received >= _r.total_amount THEN _new_status := 'paid';
  ELSE _new_status := 'partially_paid';
  END IF;

  UPDATE public.closing_reports
     SET received_amount = _received,
         open_amount = GREATEST(0, total_amount - _received),
         payment_status = _new_status,
         payment_date = CASE WHEN _new_status = 'paid' THEN _date ELSE payment_date END,
         status = CASE WHEN _new_status = 'paid' THEN 'paid'
                       WHEN _new_status = 'partially_paid' THEN 'partially_paid'
                       ELSE status END,
         updated_at = now()
   WHERE id = _r.id;

  IF _r.receivable_id IS NOT NULL THEN
    UPDATE public.receivables
       SET received_amount = COALESCE(received_amount,0) + _amt,
           received_at = CASE WHEN _new_status = 'paid' THEN now() ELSE received_at END,
           status = CASE WHEN _new_status = 'paid' THEN 'paid' ELSE status END,
           updated_at = now()
     WHERE id = _r.receivable_id;
  END IF;

  INSERT INTO public.closing_report_history (tenant_id, closing_report_id, action, new_value, created_by)
  VALUES (_r.tenant_id, _r.id, 'payment_registered', _amt::text, auth.uid());

  RETURN _pay_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_closing_report_overdue(_tenant_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _n int;
BEGIN
  IF NOT public.is_tenant_member(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  UPDATE public.closing_reports
     SET payment_status = 'overdue', status = 'overdue', updated_at = now()
   WHERE tenant_id = _tenant_id
     AND payment_status = 'unpaid'
     AND expected_payment_date IS NOT NULL
     AND expected_payment_date < current_date;
  GET DIAGNOSTICS _n = ROW_COUNT;
  RETURN _n;
END;
$function$;

