$function$;

CREATE OR REPLACE FUNCTION public.trg_vehicles_normalize_plate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.plate IS NOT NULL THEN
    IF NEW.plate_raw IS NULL OR (TG_OP='UPDATE' AND OLD.plate IS DISTINCT FROM NEW.plate) THEN
      NEW.plate_raw := NEW.plate;
    END IF;
    NEW.plate := public.normalize_vehicle_plate(NEW.plate);
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.trg_freight_tables_require_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(NEW.blocked,false)=false THEN
    IF NEW.client_id IS NULL
       AND COALESCE(NEW.origin_state,'')=''
       AND COALESCE(NEW.destination_state,'')=''
       AND COALESCE(NEW.origin_municipality,'')=''
       AND COALESCE(NEW.destination_municipality,'')=''
       AND COALESCE(NEW.vehicle_type,'')='' THEN
      RAISE EXCEPTION 'Tarifa de frete precisa de pelo menos um contexto: cliente, origem, destino ou tipo de veículo.'
        USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.next_nfse_number_by_emitter(_tenant_id uuid, _emitter_id uuid, _series text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_branch text;
  v_num bigint;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN
    RAISE EXCEPTION 'Acesso negado para reservar numeração de NFS-e'
      USING ERRCODE = '42501';
  END IF;

  SELECT branch_code INTO v_branch FROM public.tenant_emitters
    WHERE id = _emitter_id AND tenant_id = _tenant_id;
  IF v_branch IS NULL THEN
    RAISE EXCEPTION 'Emitente não encontrado para o tenant';
  END IF;

  INSERT INTO public.nfse_sequences (tenant_id, branch_code, series, emitter_id, next_number)
  VALUES (_tenant_id, v_branch, _series, _emitter_id, 2)
  ON CONFLICT (tenant_id, branch_code, series) DO UPDATE
    SET next_number = public.nfse_sequences.next_number + 1,
        emitter_id  = COALESCE(public.nfse_sequences.emitter_id, EXCLUDED.emitter_id),
        updated_at  = now()
  RETURNING next_number - 1 INTO v_num;

  RETURN v_num;
END;
$function$;

CREATE OR REPLACE FUNCTION public.trg_fiscal_documents_autolink_supplier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cnpj text;
  v_ie_raw text;
  v_ie text;
  v_supplier_id uuid;
  v_is_isento boolean;
BEGIN
  v_cnpj := regexp_replace(coalesce(NEW.remitter_cnpj,''),'\D','','g');
  v_ie_raw := coalesce(NEW.remitter_state_registration,'');
  v_is_isento := v_ie_raw ~* '^(isento|isenta|is|ex|unknown)$';
  v_ie := CASE WHEN v_is_isento THEN 'ISENTO'
               ELSE nullif(regexp_replace(v_ie_raw, '\D', '', 'g'), '') END;

  -- Try to link to existing supplier by CNPJ
  IF NEW.supplier_id IS NULL AND length(v_cnpj) > 0 THEN
    SELECT id INTO v_supplier_id
      FROM public.clients
     WHERE tenant_id = NEW.tenant_id
       AND regexp_replace(coalesce(tax_id,''),'\D','','g') = v_cnpj
     ORDER BY is_supplier DESC, active DESC, created_at ASC
     LIMIT 1;
    NEW.supplier_id := v_supplier_id;
  END IF;

  -- If still unlinked but we have CNPJ + a remitter name, create a minimal supplier
  IF NEW.supplier_id IS NULL AND length(v_cnpj) > 0 AND coalesce(NEW.remitter, '') <> '' THEN
    INSERT INTO public.clients (
      tenant_id, company_name, legal_name, tax_id,
      person_type, client_type,
      is_client, is_supplier,
      state_registration, active, blocked
    ) VALUES (
      NEW.tenant_id,
      NEW.remitter,
      NEW.remitter,
      CASE WHEN length(v_cnpj) = 14
           THEN substr(v_cnpj,1,2)||'.'||substr(v_cnpj,3,3)||'.'||substr(v_cnpj,6,3)||'/'||substr(v_cnpj,9,4)||'-'||substr(v_cnpj,13,2)
           ELSE v_cnpj END,
      CASE WHEN length(v_cnpj) = 11 THEN 'CPF' ELSE 'CNPJ' END,
      CASE WHEN length(v_cnpj) = 11 THEN 'PF' ELSE 'PJ' END,
      false, true,
      v_ie, true, false
    )
    RETURNING id INTO v_supplier_id;
    NEW.supplier_id := v_supplier_id;
  END IF;

  -- Backfill IE / address hints on the supplier if empty
  IF NEW.supplier_id IS NOT NULL AND v_ie IS NOT NULL THEN
    UPDATE public.clients
       SET state_registration = v_ie,
           is_supplier = true
     WHERE id = NEW.supplier_id
       AND (state_registration IS NULL OR btrim(state_registration) = '');
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.cte_defaults_for_group(p_load_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_emitter jsonb;
  v_remitter jsonb;
  v_recipient jsonb;
  v_driver jsonb;
  v_vehicle jsonb;
  v_totals jsonb;
  v_cargo_predominant text;
BEGIN
  IF p_load_ids IS NULL OR array_length(p_load_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('error','no_loads');
  END IF;

  SELECT tenant_id INTO v_tenant FROM public.loads WHERE id = p_load_ids[1];
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('error','load_not_found');
  END IF;

  IF NOT public.is_tenant_member(v_tenant) THEN
    RAISE EXCEPTION 'Acesso negado às cargas informadas'
      USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(p_load_ids) AS requested(load_id)
    LEFT JOIN public.loads AS scoped
      ON scoped.id = requested.load_id
    WHERE scoped.id IS NULL OR scoped.tenant_id <> v_tenant
  ) THEN
    RAISE EXCEPTION 'Todas as cargas devem existir e pertencer ao mesmo tenant'
      USING ERRCODE = '22023';
  END IF;

  SELECT to_jsonb(e.*) INTO v_emitter
  FROM public.tenant_emitters e
  WHERE e.tenant_id = v_tenant AND e.active = true
  ORDER BY e.is_default DESC NULLS LAST, e.created_at ASC
  LIMIT 1;

  SELECT jsonb_build_object(
    'remitter_cnpj', regexp_replace(COALESCE(remitter_cnpj,''), '[^0-9]', '', 'g'),
    'remitter', remitter,
    'origin_city', origin_city,
    'origin_state', origin_state
  ) INTO v_remitter
  FROM public.fiscal_documents
  WHERE tenant_id = v_tenant
    AND document_type = 'inbound'
    AND load_id = ANY(p_load_ids)
    AND remitter_cnpj IS NOT NULL
  GROUP BY remitter_cnpj, remitter, origin_city, origin_state
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  -- Recipient with fallback to clients.tax_id
  WITH agg AS (
    SELECT
      fd.recipient,
      COALESCE(
        NULLIF(regexp_replace(COALESCE(fd.recipient_cnpj,''), '[^0-9]', '', 'g'), ''),
        NULLIF(regexp_replace(COALESCE(c.tax_id,''), '[^0-9]', '', 'g'), '')
      ) AS cnpj_norm,
      fd.recipient_city,
      fd.recipient_state,
      fd.client_id,
      COUNT(*) AS n
    FROM public.fiscal_documents fd
    LEFT JOIN public.clients c ON c.id = fd.client_id
    WHERE fd.tenant_id = v_tenant
      AND fd.document_type = 'inbound'
      AND fd.load_id = ANY(p_load_ids)
    GROUP BY fd.recipient, cnpj_norm, fd.recipient_city, fd.recipient_state, fd.client_id
    ORDER BY n DESC
    LIMIT 1
  )
  SELECT jsonb_build_object(
    'recipient_cnpj', cnpj_norm,
    'recipient', recipient,
    'recipient_city', recipient_city,
    'recipient_state', recipient_state,
    'client_id', client_id
  ) INTO v_recipient FROM agg;

  SELECT to_jsonb(d.*) INTO v_driver
  FROM public.drivers d
  JOIN public.loads l ON l.driver_id = d.id
  WHERE l.id = ANY(p_load_ids) AND d.tenant_id = v_tenant
  LIMIT 1;

  SELECT to_jsonb(v.*) INTO v_vehicle
  FROM public.vehicles v
  JOIN public.loads l ON l.vehicle_id = v.id
  WHERE l.id = ANY(p_load_ids) AND v.tenant_id = v_tenant
  LIMIT 1;

  -- Get predominant product description
  SELECT cargo_description INTO v_cargo_predominant
  FROM public.fiscal_documents
  WHERE load_id = ANY(p_load_ids)
    AND tenant_id = v_tenant
    AND document_type = 'inbound'
    AND cargo_description IS NOT NULL
  GROUP BY cargo_description
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  SELECT jsonb_build_object(
    'total_weight_kg', COALESCE(SUM(fd.weight_kg), 0),
    'total_value', COALESCE(SUM(fd.value), 0),
    'invoice_count', COUNT(*)
  ) INTO v_totals
  FROM public.fiscal_documents fd
  WHERE fd.tenant_id = v_tenant
    AND fd.document_type = 'inbound'
    AND fd.load_id = ANY(p_load_ids);

  RETURN jsonb_build_object(
    'tenant_id', v_tenant,
    'emitter', v_emitter,
    'remitter', v_remitter,
    'recipient', v_recipient,
    'driver', v_driver,
    'vehicle', v_vehicle,
    'totals', COALESCE(v_totals, '{}'::jsonb),
    'cargo_predominant', v_cargo_predominant,
    'taker_role_default', 'destinatario',
    'nature_default', 'PRESTACAO DE SERVICO DE TRANSPORTE'
  );
END;
$function$;

