CREATE OR REPLACE FUNCTION public._recalc_payable_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payable_id UUID;
  v_total NUMERIC;
  v_amount NUMERIC;
  v_status TEXT;
BEGIN
  v_payable_id := COALESCE(NEW.payable_id, OLD.payable_id);
  SELECT COALESCE(SUM(amount),0) INTO v_total FROM public.payables_payments WHERE payable_id = v_payable_id;
  SELECT amount, status INTO v_amount, v_status FROM public.payables WHERE id = v_payable_id;
  IF v_status = 'cancelled' THEN
    UPDATE public.payables SET paid_amount = v_total, updated_at = now() WHERE id = v_payable_id;
    RETURN COALESCE(NEW, OLD);
  END IF;
  UPDATE public.payables SET
    paid_amount = v_total,
    status = CASE
      WHEN v_total <= 0 THEN CASE WHEN v_status IN ('paid','partial') THEN 'approved' ELSE v_status END
      WHEN v_total >= v_amount THEN 'paid'
      ELSE 'partial'
    END,
    paid_at = CASE WHEN v_total >= v_amount THEN COALESCE(paid_at, now()) ELSE NULL END,
    updated_at = now()
  WHERE id = v_payable_id;
  RETURN COALESCE(NEW, OLD);
END $function$;

CREATE OR REPLACE FUNCTION public._recalc_receivable_received()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_receivable_id UUID;
  v_total NUMERIC;
  v_amount NUMERIC;
  v_status TEXT;
BEGIN
  v_receivable_id := COALESCE(NEW.receivable_id, OLD.receivable_id);
  SELECT COALESCE(SUM(amount),0) INTO v_total FROM public.receivables_payments WHERE receivable_id = v_receivable_id;
  SELECT amount, status INTO v_amount, v_status FROM public.receivables WHERE id = v_receivable_id;
  IF v_status = 'cancelled' THEN
    UPDATE public.receivables SET received_amount = v_total, updated_at = now() WHERE id = v_receivable_id;
    RETURN COALESCE(NEW, OLD);
  END IF;
  UPDATE public.receivables SET
    received_amount = v_total,
    status = CASE
      WHEN v_total <= 0 THEN CASE WHEN v_status IN ('received','partial') THEN 'pending' ELSE v_status END
      WHEN v_total >= v_amount THEN 'received'
      ELSE 'partial'
    END,
    received_at = CASE WHEN v_total >= v_amount THEN COALESCE(received_at, now()) ELSE NULL END,
    updated_at = now()
  WHERE id = v_receivable_id;
  RETURN COALESCE(NEW, OLD);
END $function$;

CREATE OR REPLACE FUNCTION public.register_payable_payment(_payable_id uuid, _amount numeric, _paid_at timestamp with time zone, _bank_account_id uuid, _method text DEFAULT 'other'::text, _notes text DEFAULT NULL::text, _attachment_url text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payable public.payables%ROWTYPE;
  v_remaining NUMERIC;
  v_tx_id UUID;
  v_payment_id UUID;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_payable FROM public.payables WHERE id = _payable_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conta não encontrada'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_memberships tm WHERE tm.user_id = v_uid AND tm.tenant_id = v_payable.tenant_id AND tm.role IN ('owner','admin','operator')) THEN
    RAISE EXCEPTION 'Sem permissão para dar baixa em contas a pagar';
  END IF;
  IF v_payable.status = 'cancelled' THEN RAISE EXCEPTION 'Conta cancelada'; END IF;
  IF _amount <= 0 THEN RAISE EXCEPTION 'Valor inválido'; END IF;
  v_remaining := v_payable.amount - COALESCE(v_payable.paid_amount,0);
  IF _amount > v_remaining + 0.01 THEN
    RAISE EXCEPTION 'Valor % maior que o saldo devedor %', _amount, v_remaining;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.bank_accounts WHERE id = _bank_account_id AND tenant_id = v_payable.tenant_id) THEN
    RAISE EXCEPTION 'Conta bancária inválida';
  END IF;

  INSERT INTO public.bank_transactions (
    tenant_id, bank_account_id, posted_at, description, amount, transaction_type,
    document_number, counterparty_name, reconciliation_status, raw_payload
  ) VALUES (
    v_payable.tenant_id, _bank_account_id, _paid_at,
    'Baixa: ' || COALESCE(v_payable.description, v_payable.supplier_name),
    _amount, 'debit',
    v_payable.document_number, v_payable.supplier_name, 'matched',
    jsonb_build_object('source','payable_payment','payable_id', _payable_id)
  ) RETURNING id INTO v_tx_id;

  INSERT INTO public.payables_payments (
    tenant_id, payable_id, amount, paid_at, bank_account_id, method, notes, attachment_url,
    bank_transaction_id, created_by
  ) VALUES (
    v_payable.tenant_id, _payable_id, _amount, _paid_at, _bank_account_id, _method, _notes, _attachment_url,
    v_tx_id, v_uid
  ) RETURNING id INTO v_payment_id;

  RETURN v_payment_id;
END $function$;

CREATE OR REPLACE FUNCTION public.reverse_payable_payment(_payment_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment public.payables_payments%ROWTYPE;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_payment FROM public.payables_payments WHERE id = _payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Baixa não encontrada'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_memberships tm WHERE tm.user_id = v_uid AND tm.tenant_id = v_payment.tenant_id AND tm.role IN ('owner','admin','operator')) THEN
    RAISE EXCEPTION 'Sem permissão para estornar';
  END IF;
  DELETE FROM public.payables_payments WHERE id = _payment_id;
  IF v_payment.bank_transaction_id IS NOT NULL THEN
    DELETE FROM public.bank_transactions WHERE id = v_payment.bank_transaction_id;
  END IF;
  RETURN true;
END $function$;

CREATE OR REPLACE FUNCTION public.register_receivable_payment(_receivable_id uuid, _amount numeric, _received_at timestamp with time zone, _bank_account_id uuid, _method text DEFAULT 'other'::text, _notes text DEFAULT NULL::text, _attachment_url text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rcv public.receivables%ROWTYPE;
  v_remaining NUMERIC;
  v_tx_id UUID;
  v_payment_id UUID;
  v_uid UUID := auth.uid();
  v_desc TEXT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_rcv FROM public.receivables WHERE id = _receivable_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Título não encontrado'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_memberships tm WHERE tm.user_id = v_uid AND tm.tenant_id = v_rcv.tenant_id AND tm.role IN ('owner','admin','operator')) THEN
    RAISE EXCEPTION 'Sem permissão para dar baixa em recebíveis';
  END IF;
  IF v_rcv.status = 'cancelled' THEN RAISE EXCEPTION 'Título cancelado'; END IF;
  IF _amount <= 0 THEN RAISE EXCEPTION 'Valor inválido'; END IF;
  v_remaining := v_rcv.amount - COALESCE(v_rcv.received_amount,0);
  IF _amount > v_remaining + 0.01 THEN
    RAISE EXCEPTION 'Valor % maior que o saldo em aberto %', _amount, v_remaining;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.bank_accounts WHERE id = _bank_account_id AND tenant_id = v_rcv.tenant_id) THEN
    RAISE EXCEPTION 'Conta bancária inválida';
  END IF;
  v_desc := 'Recebimento: ' || COALESCE(v_rcv.description, v_rcv.invoice_number, 'Título ' || v_rcv.id::text);

  INSERT INTO public.bank_transactions (
    tenant_id, bank_account_id, posted_at, description, amount, transaction_type,
    document_number, reconciliation_status, raw_payload
  ) VALUES (
    v_rcv.tenant_id, _bank_account_id, _received_at,
    v_desc, _amount, 'credit',
    v_rcv.invoice_number, 'matched',
    jsonb_build_object('source','receivable_payment','receivable_id', _receivable_id)
  ) RETURNING id INTO v_tx_id;

  INSERT INTO public.receivables_payments (
    tenant_id, receivable_id, amount, received_at, bank_account_id, method, notes, attachment_url,
    bank_transaction_id, created_by
  ) VALUES (
    v_rcv.tenant_id, _receivable_id, _amount, _received_at, _bank_account_id, _method, _notes, _attachment_url,
    v_tx_id, v_uid
  ) RETURNING id INTO v_payment_id;

  RETURN v_payment_id;
END $function$;

CREATE OR REPLACE FUNCTION public.reverse_receivable_payment(_payment_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment public.receivables_payments%ROWTYPE;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_payment FROM public.receivables_payments WHERE id = _payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Baixa não encontrada'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_memberships tm WHERE tm.user_id = v_uid AND tm.tenant_id = v_payment.tenant_id AND tm.role IN ('owner','admin','operator')) THEN
    RAISE EXCEPTION 'Sem permissão para estornar';
  END IF;
  DELETE FROM public.receivables_payments WHERE id = _payment_id;
  IF v_payment.bank_transaction_id IS NOT NULL THEN
    DELETE FROM public.bank_transactions WHERE id = v_payment.bank_transaction_id;
  END IF;
  RETURN true;
END $function$;

CREATE OR REPLACE FUNCTION public.create_manual_expense(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant UUID;
  v_payable_id UUID;
  v_uid UUID := auth.uid();
  v_pay_now BOOLEAN := COALESCE((_payload->>'pay_now')::boolean, false);
  v_amount NUMERIC := (_payload->>'amount')::numeric;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  v_tenant := (_payload->>'tenant_id')::uuid;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'tenant_id obrigatório'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_memberships tm WHERE tm.user_id = v_uid AND tm.tenant_id = v_tenant AND tm.role IN ('owner','admin','operator')) THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;
  IF v_amount IS NULL OR v_amount <= 0 THEN RAISE EXCEPTION 'Valor inválido'; END IF;

  INSERT INTO public.payables (
    tenant_id, supplier_name, supplier_id, category, description, amount,
    due_date, competence_date, document_number, notes, status, source,
    bank_account_id, created_by
  ) VALUES (
    v_tenant,
    COALESCE(_payload->>'supplier_name','Despesa avulsa'),
    NULLIF(_payload->>'supplier_id','')::uuid,
    COALESCE(_payload->>'category','other'),
    _payload->>'description',
    v_amount,
    NULLIF(_payload->>'due_date','')::date,
    NULLIF(_payload->>'competence_date','')::date,
    _payload->>'document_number',
    _payload->>'notes',
    CASE WHEN v_pay_now THEN 'approved' ELSE COALESCE(_payload->>'status','pending') END,
    'manual',
    NULLIF(_payload->>'bank_account_id','')::uuid,
    v_uid
  ) RETURNING id INTO v_payable_id;

  IF v_pay_now THEN
    PERFORM public.register_payable_payment(
      v_payable_id,
      v_amount,
      COALESCE(NULLIF(_payload->>'paid_at','')::timestamptz, now()),
      NULLIF(_payload->>'bank_account_id','')::uuid,
      COALESCE(_payload->>'method','other'),
      _payload->>'payment_notes',
      _payload->>'attachment_url'
    );
  END IF;
  RETURN v_payable_id;
END $function$;

CREATE OR REPLACE FUNCTION public.fiscal_documents_enforce_single_outbound()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.cte_emitted_at is not null and new.nfse_emitted_at is not null then
    raise exception 'NF % ja possui documento de saida (CT-e ou NFS-e). Cancele o documento existente antes de emitir outro.', coalesce(new.invoice_number, new.id::text)
      using errcode = '23505';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_load_dispatch_duplicity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 
    FROM public.dispatch_trip_loads dtl
    JOIN public.dispatch_trips dt ON dt.id = dtl.dispatch_trip_id
    WHERE dtl.load_id = NEW.load_id
      AND dt.status NOT IN ('cancelled', 'completed')
      AND dtl.dispatch_trip_id <> NEW.dispatch_trip_id
  ) THEN
    RAISE EXCEPTION 'Carga % já está vinculada a uma viagem ativa', NEW.load_id;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_driver_settlement_payment_v2(_settlement_id uuid, _amount numeric, _payment_method text DEFAULT 'pix'::text, _payment_account text DEFAULT NULL::text, _payment_reference text DEFAULT NULL::text, _receipt_url text DEFAULT NULL::text, _notes text DEFAULT NULL::text, _allow_overpayment boolean DEFAULT false, _overpayment_reason text DEFAULT NULL::text, _bank_account_id uuid DEFAULT NULL::uuid, _cost_center text DEFAULT 'Operacional'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_s public.driver_settlements;
  v_payment_id uuid;
  v_total numeric;
  v_balance numeric;
  v_is_admin boolean;
  v_prev_status text;
  v_new_status text;
  v_account_desc text;
  v_in_locked_payroll boolean;
  v_bank_transaction_id uuid;
  v_driver_name text;
BEGIN
  -- 1. Fetch settlement and lock for update
  SELECT * INTO v_s FROM public.driver_settlements WHERE id = _settlement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;
  
  -- 2. Basic authorization
  IF NOT public.is_tenant_operator_or_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  
  -- 3. Validation
  IF v_s.status NOT IN ('approved','paid') THEN RAISE EXCEPTION 'must_be_approved'; END IF;
  IF _amount IS NULL OR _amount <= 0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;

  IF _payment_account IS NULL OR length(trim(_payment_account)) = 0 THEN
    RAISE EXCEPTION 'payment_account_required';
  END IF;
  
  v_account_desc := trim(_payment_account);
  IF lower(v_account_desc) IN ('outro', 'other') THEN
    RAISE EXCEPTION 'payment_account_description_required';
  END IF;

  -- 4. Check Payroll Lock (Same logic as v1)
  SELECT EXISTS (
    SELECT 1
    FROM public.payroll_entry_items pei
    JOIN public.payroll_entries pe ON pe.id = pei.payroll_entry_id
    JOIN public.payroll_periods pp ON pp.id = pe.payroll_period_id
    WHERE pei.source_table = 'driver_settlements'
      AND pei.source_id = _settlement_id
      AND pei.item_type <> 'driver_settlement_payment'
      AND pp.status IN ('approved','closed')
  ) INTO v_in_locked_payroll;

  v_is_admin := EXISTS (
    SELECT 1 FROM public.tenant_memberships
     WHERE tenant_id = v_s.tenant_id AND user_id = auth.uid()
       AND active = true AND role IN ('owner','admin'));

  IF v_in_locked_payroll THEN
    IF NOT (v_is_admin AND length(trim(COALESCE(_overpayment_reason,''))) > 0) THEN
      RAISE EXCEPTION 'settlement_locked_in_payroll';
    END IF;
  END IF;

  -- 5. Overpayment check
  v_prev_status := v_s.status;
  v_balance := COALESCE(v_s.driver_payable_amount,0) - COALESCE(v_s.total_paid_amount,0);
  IF _amount > v_balance THEN
    IF NOT (_allow_overpayment AND v_is_admin AND length(trim(COALESCE(_overpayment_reason,''))) > 0) THEN
      RAISE EXCEPTION 'overpayment_blocked';
    END IF;
  END IF;

  -- 6. Insert Payment Record
  INSERT INTO public.driver_settlement_payments(
    tenant_id, settlement_id, amount, payment_method, 
    payment_account, payment_reference, receipt_url, notes, paid_by
  )
  VALUES (
    v_s.tenant_id, _settlement_id, _amount, _payment_method, 
    v_account_desc, _payment_reference, _receipt_url, _notes, auth.uid()
  )
  RETURNING id INTO v_payment_id;

  -- 7. If bank account provided, create a bank transaction (reconciliation)
  IF _bank_account_id IS NOT NULL THEN
    SELECT name INTO v_driver_name FROM public.drivers WHERE id = v_s.driver_id;
    
    INSERT INTO public.bank_transactions (
      tenant_id,
      bank_account_id,
      type,
      amount,
      description,
      transaction_date,
      status,
      category,
      cost_center,
      source_table,
      source_id
    ) VALUES (
      v_s.tenant_id,
      _bank_account_id,
      'expense',
      _amount,
      'Pagamento Acerto: ' || COALESCE(v_driver_name, 'Motorista') || ' - ' || COALESCE(v_s.route_name, 'Viagem'),
      now(),
      'completed',
      'Acerto Motorista',
      _cost_center,
      'driver_settlement_payments',
      v_payment_id
    ) RETURNING id INTO v_bank_transaction_id;
    
    -- Update payment with transaction link if column exists or in metadata/notes
    -- For now, we rely on the bank_transactions table link.
  END IF;

  -- 8. Update Settlement Totals
  SELECT COALESCE(sum(amount),0) INTO v_total FROM public.driver_settlement_payments WHERE settlement_id = _settlement_id;

  UPDATE public.driver_settlements SET
    total_paid_amount = v_total,
    payment_balance = COALESCE(driver_payable_amount,0) - v_total,
    status = CASE WHEN v_total >= COALESCE(driver_payable_amount,0) THEN 'paid' ELSE status END,
    paid_by = CASE WHEN v_total >= COALESCE(driver_payable_amount,0) THEN auth.uid() ELSE paid_by END,
    paid_at = CASE WHEN v_total >= COALESCE(driver_payable_amount,0) THEN now() ELSE paid_at END
  WHERE id = _settlement_id;

  SELECT status INTO v_new_status FROM public.driver_settlements WHERE id = _settlement_id;

  -- 9. Audit Event
  PERFORM public._log_settlement_event(_settlement_id, 'payment_registered', v_prev_status, v_new_status, _notes,
    jsonb_build_object(
      'payment_id', v_payment_id, 'amount', _amount, 'payment_method', _payment_method,
      'payment_account', v_account_desc, 'payment_reference', _payment_reference,
      'receipt_url', _receipt_url, 'notes', _notes,
      'bank_transaction_id', v_bank_transaction_id,
      'total_paid_amount', v_total,
      'payment_balance', COALESCE(v_s.driver_payable_amount,0) - v_total,
      'in_locked_payroll', v_in_locked_payroll
    ));

  RETURN v_payment_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.add_driver_settlement_manual_expense(_settlement_id uuid, _category text, _amount numeric, _expense_at timestamp with time zone, _cost_center text, _payment_source text DEFAULT 'driver'::text, _reimbursable boolean DEFAULT true, _receipt_url text DEFAULT NULL::text, _notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_s public.driver_settlements;
  v_expense_id uuid;
  v_item_id uuid;
  v_tenant_id uuid;
begin
  select * into v_s
  from public.driver_settlements
  where id = _settlement_id
  for update;

  if not found then
    raise exception 'Settlement not found';
  end if;

  if not public.is_tenant_operator_or_admin(v_s.tenant_id) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;

  if v_s.status = 'closed' then
    raise exception 'Cannot add expenses to a closed settlement';
  end if;

  v_tenant_id := v_s.tenant_id;

  insert into public.driver_expenses (
    tenant_id,
    driver_id,
    vehicle_id,
    category,
    amount,
    expense_date,
    status,
    payment_source,
    reimbursable,
    receipt_url,
    notes,
    cost_center,
    source_table,
    source_id
  ) values (
    v_tenant_id,
    v_s.driver_id,
    v_s.vehicle_id,
    _category,
    _amount,
    _expense_at,
    'completed',
    _payment_source,
    _reimbursable,
    _receipt_url,
    _notes,
    _cost_center,
    'driver_settlements',
    _settlement_id
  )
  returning id into v_expense_id;

  insert into public.driver_settlement_items (
    tenant_id,
    settlement_id,
    item_type,
    source_table,
    source_id,
    description,
    amount,
    quantity,
    metadata
  ) values (
    v_tenant_id,
    _settlement_id,
    'expense',
    'driver_expenses',
    v_expense_id,
    _category,
    case
      when _payment_source = 'driver' and _reimbursable then _amount
      else 0
    end,
    1,
    jsonb_build_object(
      'category', _category,
      'expense_at', _expense_at,
      'payment_source', _payment_source,
      'reimbursable', _reimbursable,
      'cost_center', _cost_center,
      'total_amount', _amount
    )
  )
  returning id into v_item_id;

  update public.driver_settlements
  set needs_recalculation = true,
      recalculation_reason = 'Nova despesa manual adicionada'
  where id = _settlement_id;

  insert into public.driver_settlement_events (
    settlement_id,
    event_type,
    description,
    metadata
  )
  values (
    _settlement_id,
    'expense_added',
    'Despesa manual adicionada: ' || _category || ' - ' || _amount,
    jsonb_build_object('expense_id', v_expense_id)
  );

  return v_expense_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_driver_settlement_km_review(_settlement_id uuid, _audited_km numeric, _km_status text, _notes text, _km_start numeric DEFAULT NULL::numeric, _km_end numeric DEFAULT NULL::numeric, _audited_start_location text DEFAULT NULL::text, _audited_end_location text DEFAULT NULL::text)
 RETURNS driver_settlements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE 
  v_s public.driver_settlements;
BEGIN
  SELECT * INTO v_s FROM public.driver_settlements WHERE id = _settlement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;
  
  IF NOT public.is_tenant_operator_or_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  
  IF v_s.status = 'closed' THEN RAISE EXCEPTION 'settlement_locked'; END IF;
  
  IF _km_status NOT IN ('pending','reviewed','disputed') THEN RAISE EXCEPTION 'invalid_km_status'; END IF;
  
  UPDATE public.driver_settlements 
  SET 
    audited_km = _audited_km, 
    km_review_status = _km_status, 
    km_review_notes = _notes,
    km_start = _km_start,
    km_end = _km_end,
    audited_start_location = _audited_start_location,
    audited_end_location = _audited_end_location
  WHERE id = _settlement_id 
  RETURNING * INTO v_s;
  
  PERFORM public._log_settlement_event(
    _settlement_id, 
    'km_reviewed', 
    NULL, 
    NULL, 
    _notes,
    jsonb_build_object(
      'audited_km', _audited_km, 
      'km_status', _km_status,
      'km_start', _km_start,
      'km_end', _km_end,
      'audited_start_location', _audited_start_location,
      'audited_end_location', _audited_end_location
    )
  );
  
  RETURN v_s;
END; $function$;

CREATE OR REPLACE FUNCTION public.delete_driver_settlement(_settlement_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_s public.driver_settlements;
BEGIN
  -- 1. Obter e validar acerto
  SELECT * INTO v_s FROM public.driver_settlements WHERE id = _settlement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;

  -- 2. Verificar permissão de tenant
  IF NOT public.is_tenant_operator_or_admin(v_s.tenant_id) THEN RAISE EXCEPTION 'forbidden'; END IF;

  -- 3. Verificar status
  IF v_s.status IN ('paid', 'closed') AND NOT public.is_tenant_admin(v_s.tenant_id) THEN
    RAISE EXCEPTION 'cannot_delete_settled_record';
  END IF;

  -- 4. Desvincular romaneios (loads)
  UPDATE public.loads
  SET driver_settlement_id = NULL
  WHERE driver_settlement_id = _settlement_id;

  -- 5. Remover dependências
  DELETE FROM public.driver_settlement_items WHERE settlement_id = _settlement_id;
  DELETE FROM public.driver_settlement_events WHERE settlement_id = _settlement_id;
  DELETE FROM public.driver_settlement_payments WHERE settlement_id = _settlement_id;

  -- 6. Remover o registro principal
  DELETE FROM public.driver_settlements WHERE id = _settlement_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.soft_delete_fiscal_document(doc_id uuid, user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_tenant_id uuid;
begin
  if v_actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select fd.tenant_id
  into v_tenant_id
  from public.fiscal_documents fd
  where fd.id = doc_id
  for update;

  if not found then
    raise exception 'Fiscal document not found';
  end if;

  if not public.is_tenant_operator_or_admin(v_tenant_id) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;

  update public.fiscal_documents
  set deleted_at = now(),
      deleted_by = v_actor_id,
      load_id = null,
      status = 'deleted'
  where id = doc_id
    and tenant_id = v_tenant_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_load_if_empty(v_load_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_doc_count INT;
    v_tenant_id UUID;
BEGIN
    IF v_load_id IS NULL THEN
        RETURN;
    END IF;

    -- Count active fiscal documents for this load
    SELECT count(*) INTO v_doc_count
    FROM public.fiscal_documents
    WHERE load_id = v_load_id 
      AND deleted_at IS NULL 
      AND status <> 'deleted';

    IF v_doc_count = 0 THEN
        SELECT tenant_id INTO v_tenant_id FROM public.loads WHERE id = v_load_id;
        
        IF v_tenant_id IS NOT NULL THEN
            -- delete_load_safely handles unlinking remaining items and deleting the load
            PERFORM public.delete_load_safely(v_tenant_id, v_load_id);
        END IF;
    END IF;
EXCEPTION WHEN OTHERS THEN
    NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.trg_handle_empty_load_on_doc_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    -- If it's an UPDATE that changed load_id, check the OLD load_id
    IF TG_OP = 'UPDATE' THEN
        IF OLD.load_id IS NOT NULL AND (NEW.load_id IS NULL OR NEW.load_id <> OLD.load_id OR NEW.status = 'deleted') THEN
            PERFORM public.delete_load_if_empty(OLD.load_id);
        END IF;
    -- If it's a DELETE, check the OLD load_id
    ELSIF TG_OP = 'DELETE' THEN
        IF OLD.load_id IS NOT NULL THEN
            PERFORM public.delete_load_if_empty(OLD.load_id);
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.release_inbound_notes_from_failed_cte()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
  v_sefaz_status text;
  v_outbound_id uuid;
BEGIN
  v_outbound_id := COALESCE(NEW.id, OLD.id);
  v_status := lower(trim(COALESCE(NEW.status, OLD.status, '')));
  v_sefaz_status := lower(trim(COALESCE(NEW.sefaz_status, OLD.sefaz_status, '')));

  IF COALESCE(NEW.document_type, OLD.document_type) = 'outbound'
     AND (
       v_status IN ('rejected', 'rejeitada', 'rejeitado', 'error', 'erro', 'failed', 'denied', 'denegada', 'denegado')
       OR v_sefaz_status IN ('rejected', 'rejeitada', 'rejeitado', 'error', 'erro', 'failed', 'processed_error', 'sent_error', 'sefaz_error', 'denied', 'denegada', 'denegado')
     ) THEN
    UPDATE public.fiscal_documents
       SET cte_emitted_at = NULL,
           cte_emitted_outbound_id = NULL
     WHERE cte_emitted_outbound_id = v_outbound_id
       AND document_type = 'inbound';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$;

CREATE OR REPLACE FUNCTION public.monitor_simples_nacional_icms_violations()
 RETURNS TABLE(fiscal_document_id uuid, cte_number text, emitter_name text, icms_base numeric, icms_aliquota numeric, icms_valor numeric, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    return query
    select 
        fd.id as fiscal_document_id,
        fd.document_number as cte_number,
        te.razao_social as emitter_name,
        (fd.payload->'valores'->>'baseIcms')::numeric as icms_base,
        (fd.payload->'valores'->>'aliquotaIcms')::numeric as icms_aliquota,
        (fd.payload->'valores'->>'valorIcms')::numeric as icms_valor,
        fd.created_at
    from 
        public.fiscal_documents fd
    join 
        public.tenant_emitters te on te.id = fd.emitter_id
    where 
        fd.document_type = 'cte'
        and fd.status = 'authorized'
        and (te.regime_tributario = 'simples' or te.regime_tributario = 'mei')
        and (
            (fd.payload->'valores'->>'valorIcms')::numeric > 0
            or (fd.payload->'valores'->>'baseIcms')::numeric > 0
            or (fd.payload->'valores'->>'aliquotaIcms')::numeric > 0
        )
        and fd.deleted_at is null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.build_fiscal_documents_deleted_recovery_dry_run(_start_time timestamp with time zone, _end_time timestamp with time zone, _tenant_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(tenant_id uuid, deleted_count bigint, sample_ids uuid[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT (public.has_role(auth.uid(), 'admin')) AND auth.role() <> 'service_role' THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    RETURN QUERY
    SELECT 
        fd.tenant_id,
        count(*),
        array_agg(fd.id) FILTER (WHERE fd.id IS NOT NULL)
    FROM public.fiscal_documents fd
    WHERE fd.deleted_at BETWEEN _start_time AND _end_time
      AND (_tenant_id IS NULL OR fd.tenant_id = _tenant_id)
      AND fd.document_type = 'inbound'
    GROUP BY fd.tenant_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.monitor_simples_nacional_icms_violations(_tenant_id uuid)
 RETURNS TABLE(document_id uuid, cte_number text, emitter_name text, icms_value numeric, cst text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.has_role(auth.uid(), 'admin') AND auth.role() <> 'service_role' THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.tenant_memberships 
        WHERE user_id = auth.uid() 
          AND tenant_id = _tenant_id
    ) AND auth.role() <> 'service_role' THEN
        RAISE EXCEPTION 'Tenant access denied';
    END IF;

    RETURN QUERY
    SELECT 
        fd.id,
        fd.cte_number,
        fd.emitter_name,
        (fd.fiscal_payload->'icms'->>'valor')::numeric,
        fd.fiscal_payload->'icms'->>'cst'
    FROM public.fiscal_documents fd
    WHERE fd.tenant_id = _tenant_id
      AND fd.deleted_at IS NULL
      AND (fd.fiscal_payload->>'isSimples')::boolean = true
      AND (fd.fiscal_payload->'icms'->>'valor')::numeric > 0;
END;
$function$;

CREATE OR REPLACE FUNCTION public._recalculate_load_totals(_load_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    UPDATE public.loads l
    SET 
        total_pallet_count = COALESCE((SELECT sum(pallet_count) FROM public.load_items WHERE load_id = _load_id), 0),
        total_weight_kg = COALESCE((SELECT sum(weight_kg) FROM public.load_items WHERE load_id = _load_id), 0),
        total_volume_m3 = COALESCE((SELECT sum(volume_m3) FROM public.load_items WHERE load_id = _load_id), 0),
        updated_at = now()
    WHERE l.id = _load_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.link_fiscal_documents_to_load_v1(_tenant_id uuid, _load_id uuid, _document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_doc_id uuid;
    v_updated_count int := 0;
    v_audit_old jsonb;
    v_audit_new jsonb;
BEGIN
    -- Auth Guard
    IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'operator')) AND auth.role() <> 'service_role' THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    -- Existence Check
    IF NOT EXISTS (SELECT 1 FROM public.loads WHERE id = _load_id AND tenant_id = _tenant_id) THEN
        RAISE EXCEPTION 'Load not found or unauthorized';
    END IF;

    -- Lock Check
    IF public._load_is_locked(_load_id) THEN
        RAISE EXCEPTION 'Load is locked and cannot be modified';
    END IF;

    -- Transactional Linkage
    FOREACH v_doc_id IN ARRAY _document_ids LOOP
        -- Skip if already linked to this load
        IF EXISTS (SELECT 1 FROM public.load_items WHERE load_id = _load_id AND fiscal_document_id = v_doc_id) THEN
            CONTINUE;
        END IF;

        -- Verify ownership and availability
        IF NOT EXISTS (SELECT 1 FROM public.fiscal_documents WHERE id = v_doc_id AND tenant_id = _tenant_id) THEN
            RAISE EXCEPTION 'Document % not found or unauthorized', v_doc_id;
        END IF;

        -- Check if linked elsewhere
        IF EXISTS (SELECT 1 FROM public.fiscal_documents WHERE id = v_doc_id AND load_id IS NOT NULL AND load_id <> _load_id) THEN
             RAISE EXCEPTION 'Document % is already linked to another load', v_doc_id;
        END IF;

        -- Capture audit state
        SELECT jsonb_build_object('load_id', load_id) INTO v_audit_old FROM public.fiscal_documents WHERE id = v_doc_id;

        -- Link Projection 1: fiscal_documents
        UPDATE public.fiscal_documents 
        SET load_id = _load_id, updated_at = now() 
        WHERE id = v_doc_id;

        -- Link SoT: load_items
        INSERT INTO public.load_items (
            tenant_id, load_id, fiscal_document_id, item_description, 
            pallet_count, weight_kg, volume_m3, status
        )
        SELECT 
            _tenant_id, _load_id, id, 
            COALESCE(product_summary, 'Doc ' || invoice_number),
            COALESCE(pallet_count, 0), COALESCE(weight_kg, 0), 0, 'pending'
        FROM public.fiscal_documents
        WHERE id = v_doc_id
        ON CONFLICT (load_id, fiscal_document_id) DO NOTHING;

        -- Link Projection 2: load_documents (join table mirror)
        INSERT INTO public.load_documents (tenant_id, load_id, fiscal_document_id)
        VALUES (_tenant_id, _load_id, v_doc_id)
        ON CONFLICT (load_id, fiscal_document_id) DO NOTHING;

        v_audit_new := jsonb_build_object('load_id', _load_id);
        
        PERFORM public._log_entity_audit(
            _tenant_id, 'fiscal_document', v_doc_id, 'link_to_load', 
            v_audit_old, v_audit_new, 'composition_rpc'
        );

        v_updated_count := v_updated_count + 1;
    END LOOP;

    -- Recalculate
    PERFORM public._recalculate_load_totals(_load_id);

    RETURN jsonb_build_object('success', true, 'linked_count', v_updated_count);
END;
$function$;

CREATE OR REPLACE FUNCTION public.unlink_fiscal_documents_from_load_v1(_tenant_id uuid, _load_id uuid, _document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_doc_id uuid;
    v_removed_count int := 0;
BEGIN
    -- Auth Guard
    IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'operator')) AND auth.role() <> 'service_role' THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    -- Lock Check
    IF public._load_is_locked(_load_id) THEN
        RAISE EXCEPTION 'Load is locked and cannot be modified';
    END IF;

    FOREACH v_doc_id IN ARRAY _document_ids LOOP
        -- SoT Update
        DELETE FROM public.load_items 
        WHERE load_id = _load_id AND fiscal_document_id = v_doc_id;
        
        -- Projection 1
        UPDATE public.fiscal_documents 
        SET load_id = NULL, updated_at = now() 
        WHERE id = v_doc_id AND load_id = _load_id;

        -- Projection 2
        DELETE FROM public.load_documents 
        WHERE load_id = _load_id AND fiscal_document_id = v_doc_id;

        PERFORM public._log_entity_audit(
            _tenant_id, 'fiscal_document', v_doc_id, 'unlink_from_load', 
            jsonb_build_object('load_id', _load_id), jsonb_build_object('load_id', null), 
            'composition_rpc'
        );

        v_removed_count := v_removed_count + 1;
    END LOOP;

    -- Recalculate
    PERFORM public._recalculate_load_totals(_load_id);

    RETURN jsonb_build_object('success', true, 'unlinked_count', v_removed_count);
END;
$function$;

CREATE OR REPLACE FUNCTION public.diagnose_load_composition(_tenant_id uuid, _load_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(load_id uuid, load_number text, entity_id uuid, entity_type text, issue text, severity text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.has_role(auth.uid(), 'admin') AND auth.role() <> 'service_role' THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    RETURN QUERY
    -- Discrepancy: load_items SoT missing in fiscal_documents projection
    SELECT 
        l.id, l.load_number, li.fiscal_document_id, 'fiscal_document'::text,
        'SoT exists in load_items but projection missing in fiscal_documents'::text, 'high'::text
    FROM public.load_items li
    JOIN public.loads l ON l.id = li.load_id
    LEFT JOIN public.fiscal_documents fd ON fd.id = li.fiscal_document_id
    WHERE li.tenant_id = _tenant_id
      AND li.fiscal_document_id IS NOT NULL
      AND (fd.load_id IS NULL OR fd.load_id <> li.load_id)
      AND (_load_ids IS NULL OR li.load_id = ANY(_load_ids))

    UNION ALL

    -- Discrepancy: fiscal_documents has load_id but missing in load_items SoT
    SELECT 
        l.id, l.load_number, fd.id, 'fiscal_document'::text,
        'Projection exists in fiscal_documents but SoT missing in load_items'::text, 'high'::text
    FROM public.fiscal_documents fd
    JOIN public.loads l ON l.id = fd.load_id
    LEFT JOIN public.load_items li ON li.fiscal_document_id = fd.id AND li.load_id = fd.load_id
    WHERE fd.tenant_id = _tenant_id
      AND fd.load_id IS NOT NULL
      AND li.id IS NULL
      AND (_load_ids IS NULL OR fd.load_id = ANY(_load_ids))
    
    UNION ALL
    
    -- Totals discrepancy
    SELECT 
        l.id, l.load_number, l.id, 'load'::text,
        'Totals discrepancy (recalc needed)'::text, 'medium'::text
    FROM public.loads l
    WHERE l.tenant_id = _tenant_id
      AND (_load_ids IS NULL OR l.id = ANY(_load_ids))
      AND (
          l.total_pallet_count <> COALESCE((SELECT sum(pallet_count) FROM public.load_items WHERE load_id = l.id), 0)
          OR l.total_weight_kg <> COALESCE((SELECT sum(weight_kg) FROM public.load_items WHERE load_id = l.id), 0)
      );
END;
$function$;

CREATE OR REPLACE FUNCTION public.repair_load_composition(_tenant_id uuid, _load_ids uuid[], _dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_load_id uuid;
BEGIN
    IF NOT public.has_role(auth.uid(), 'admin') AND auth.role() <> 'service_role' THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    IF _dry_run THEN
        RETURN jsonb_build_object('dry_run', true, 'issues', (SELECT jsonb_agg(t) FROM public.diagnose_load_composition(_tenant_id, _load_ids) t));
    END IF;

    FOREACH v_load_id IN ARRAY _load_ids LOOP
        -- 1. Sync fiscal_documents to load_items (SoT wins)
        UPDATE public.fiscal_documents fd
        SET load_id = li.load_id
        FROM public.load_items li
        WHERE li.fiscal_document_id = fd.id
          AND li.load_id = v_load_id
          AND fd.tenant_id = _tenant_id
          AND (fd.load_id IS NULL OR fd.load_id <> v_load_id);

        -- 2. Clean up dangling fiscal_documents links
        UPDATE public.fiscal_documents fd
        SET load_id = NULL
        WHERE fd.load_id = v_load_id
          AND fd.tenant_id = _tenant_id
          AND NOT EXISTS (SELECT 1 FROM public.load_items li WHERE li.fiscal_document_id = fd.id AND li.load_id = v_load_id);
          
        -- 3. Sync load_documents join table
        DELETE FROM public.load_documents WHERE load_id = v_load_id;
        INSERT INTO public.load_documents (tenant_id, load_id, fiscal_document_id)
        SELECT li.tenant_id, li.load_id, li.fiscal_document_id
        FROM public.load_items li
        WHERE li.load_id = v_load_id AND li.fiscal_document_id IS NOT NULL;

        -- 4. Recalculate totals
        PERFORM public._recalculate_load_totals(v_load_id);
    END LOOP;

    RETURN jsonb_build_object('success', true, 'repaired_loads', array_length(_load_ids, 1));
END;
$function$;

CREATE OR REPLACE FUNCTION public.move_load_items_v2(_tenant_id uuid, _source_load_id uuid, _target_load_id uuid, _document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_res_unlink jsonb;
    v_res_link jsonb;
BEGIN
    -- Auth Guard
    IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'operator')) AND auth.role() <> 'service_role' THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    IF _source_load_id = _target_load_id THEN
        RAISE EXCEPTION 'Source and target loads are the same';
    END IF;

    -- 1. Unlink from source (atomically within this TX)
    -- We bypass the check in link_v1 by doing it manually or modifying unlink
    -- But since they are separate functions, we can just call them if we relax the check or order them.
    
    -- Actually, let's just implement it directly for maximum control
    
    -- Lock Checks
    IF public._load_is_locked(_source_load_id) THEN RAISE EXCEPTION 'Source load is locked'; END IF;
    IF public._load_is_locked(_target_load_id) THEN RAISE EXCEPTION 'Target load is locked'; END IF;

    -- Unlink
    PERFORM public.unlink_fiscal_documents_from_load_v1(_tenant_id, _source_load_id, _document_ids);
    
    -- Link
    PERFORM public.link_fiscal_documents_to_load_v1(_tenant_id, _target_load_id, _document_ids);

    RETURN jsonb_build_object('success', true, 'moved_count', array_length(_document_ids, 1));
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_trip_load_mirrors()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- Atualiza espelho na loads (apenas se for o primeiro link ou principal)
        UPDATE public.loads 
        SET trip_id = NEW.dispatch_trip_id, 
            updated_at = now() 
        WHERE id = NEW.load_id AND (trip_id IS NULL OR trip_id = NEW.dispatch_trip_id);
        
        -- Atualiza espelho na dispatch_trips (apenas se for o primeiro link ou principal)
        UPDATE public.dispatch_trips 
        SET load_id = NEW.load_id, 
            updated_at = now() 
        WHERE id = NEW.dispatch_trip_id AND (load_id IS NULL OR load_id = NEW.load_id);
    ELSIF TG_OP = 'DELETE' THEN
        -- Limpa espelhos se a relação for removida
        UPDATE public.loads 
        SET trip_id = NULL, 
            updated_at = now() 
        WHERE id = OLD.load_id AND trip_id = OLD.dispatch_trip_id;
        
        UPDATE public.dispatch_trips 
        SET load_id = NULL, 
            updated_at = now() 
        WHERE id = OLD.dispatch_trip_id AND load_id = OLD.load_id;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.plan_dispatch_start_trip_v1(p_tenant_id uuid, p_driver_id uuid, p_vehicle_id uuid, p_load_ids uuid[], p_stops jsonb, p_planned_start_at timestamp with time zone DEFAULT now(), p_route_name text DEFAULT NULL::text, p_start_now boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_trip_id UUID;
    v_stop_id UUID;
    v_stop RECORD;
    v_doc_id UUID;
    v_load_id UUID;
BEGIN
    -- Validação de Tenant
    IF p_tenant_id IS NULL THEN
        RAISE EXCEPTION 'tenant_id is required';
    END IF;

    -- 1. Cria a Viagem
    INSERT INTO public.dispatch_trips (
        tenant_id,
        driver_id,
        vehicle_id,
        status,
        planned_start_at,
        actual_start_at,
        notes,
        created_by
    ) VALUES (
        p_tenant_id,
        p_driver_id,
        p_vehicle_id,
        CASE WHEN p_start_now THEN 'in_transit' ELSE 'planned' END,
        p_planned_start_at,
        CASE WHEN p_start_now THEN now() ELSE NULL END,
        p_route_name,
        auth.uid()
    ) RETURNING id INTO v_trip_id;

    -- 2. Vincula Cargas (Relação Canônica)
    FOREACH v_load_id IN ARRAY p_load_ids LOOP
        INSERT INTO public.dispatch_trip_loads (tenant_id, dispatch_trip_id, load_id)
        VALUES (p_tenant_id, v_trip_id, v_load_id);
        
        -- Atualiza status da carga
        UPDATE public.loads 
        SET status = CASE WHEN p_start_now THEN 'in_transit' ELSE 'dispatched' END,
            updated_at = now()
        WHERE id = v_load_id;
    END LOOP;

    -- 3. Cria Paradas e Vincula Documentos
    FOR v_stop IN SELECT * FROM jsonb_to_recordset(p_stops) AS x(
        destination TEXT, 
        client_id UUID, 
        stop_order INT, 
        document_ids UUID[],
        latitude NUMERIC,
        longitude NUMERIC,
        planned_arrival_at TIMESTAMPTZ,
        notes TEXT
    ) LOOP
        INSERT INTO public.dispatch_stops (
            tenant_id, 
            dispatch_trip_id, 
            destination, 
            client_id, 
            stop_order, 
            status,
            latitude,
            longitude,
            planned_arrival_at,
            notes
        ) VALUES (
            p_tenant_id, 
            v_trip_id, 
            v_stop.destination, 
            v_stop.client_id, 
            v_stop.stop_order,
            'pending',
            v_stop.latitude,
            v_stop.longitude,
            COALESCE(v_stop.planned_arrival_at, now()),
            v_stop.notes
        ) RETURNING id INTO v_stop_id;

        -- Vincula documentos à parada (relação canônica)
        IF v_stop.document_ids IS NOT NULL THEN
            FOREACH v_doc_id IN ARRAY v_stop.document_ids LOOP
                INSERT INTO public.dispatch_stop_documents (
                    tenant_id, 
                    dispatch_stop_id, 
                    fiscal_document_id,
                    load_id
                )
                SELECT p_tenant_id, v_stop_id, v_doc_id, load_id
                FROM public.fiscal_documents
                WHERE id = v_doc_id;
            END LOOP;
        END IF;
    END LOOP;

    RETURN v_trip_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.derive_trip_and_load_status_v1(p_tenant_id uuid, p_trip_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_all_terminal boolean;
    v_any_started boolean;
    v_load_ids uuid[];
    v_load_id uuid;
BEGIN
    -- Derive Trip Status from Stops
    SELECT 
        bool_and(status IN ('completed', 'delivered', 'cancelled', 'skipped', 'refused', 'returned', 'partial_delivery', 'failed')),
        bool_or(status NOT IN ('planned', 'pending'))
    INTO v_all_terminal, v_any_started
    FROM public.dispatch_stops
    WHERE dispatch_trip_id = p_trip_id AND tenant_id = p_tenant_id;

    IF v_all_terminal THEN
        UPDATE public.dispatch_trips SET status = 'completed', actual_end_at = now() WHERE id = p_trip_id AND status != 'completed';
    ELSIF v_any_started THEN
        UPDATE public.dispatch_trips SET status = 'in_transit', actual_start_at = COALESCE(actual_start_at, now()) WHERE id = p_trip_id AND status = 'planned';
    END IF;

    -- Derive Load Status from Trip and its documents
    SELECT array_agg(load_id) INTO v_load_ids FROM public.dispatch_trip_loads WHERE dispatch_trip_id = p_trip_id;

    IF v_load_ids IS NOT NULL THEN
        FOREACH v_load_id IN ARRAY v_load_ids LOOP
            IF v_all_terminal THEN
                UPDATE public.loads SET status = 'delivered' WHERE id = v_load_id AND status != 'delivered';
            ELSIF v_any_started THEN
                UPDATE public.loads SET status = 'in_transit' WHERE id = v_load_id AND status = 'ready';
            END IF;
        END LOOP;
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.transition_stop_status_v1(p_tenant_id uuid, p_stop_id uuid, p_to_status text, p_actor_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_from_status text;
    v_trip_id uuid;
    v_allowed boolean := false;
BEGIN
    -- Authorization check
    IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role IN ('admin', 'operator', 'driver')) THEN
        RAISE EXCEPTION 'Não autorizado';
    END IF;

    -- Idempotency check
    IF p_idempotency_key IS NOT NULL THEN
        SELECT to_status INTO v_from_status FROM public.entity_state_audit_log 
        WHERE tenant_id = p_tenant_id AND idempotency_key = p_idempotency_key;
        IF FOUND THEN RETURN v_from_status; END IF;
    END IF;

    -- Get current state
    SELECT status, dispatch_trip_id INTO v_from_status, v_trip_id 
    FROM public.dispatch_stops 
    WHERE id = p_stop_id AND tenant_id = p_tenant_id;

    IF NOT FOUND THEN RAISE EXCEPTION 'Parada não encontrada'; END IF;

    -- State Machine Logic
    CASE v_from_status
        WHEN 'planned' THEN v_allowed := p_to_status IN ('arriving', 'cancelled', 'skipped');
        WHEN 'arriving' THEN v_allowed := p_to_status IN ('arrived', 'skipped');
        WHEN 'arrived' THEN v_allowed := p_to_status IN ('servicing', 'skipped');
        WHEN 'servicing' THEN v_allowed := p_to_status IN ('departed', 'completed', 'delivered', 'refused', 'returned', 'partial_delivery', 'failed');
        WHEN 'departed' THEN v_allowed := p_to_status IN ('completed', 'delivered', 'refused', 'returned', 'partial_delivery', 'failed');
        ELSE v_allowed := false;
    END CASE;

    -- Drivers can only move forward, Admins can override
    IF NOT v_allowed AND NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role IN ('admin')) THEN
        RAISE EXCEPTION 'Transição de status inválida: % -> %', v_from_status, p_to_status;
    END IF;

    -- Update Stop
    UPDATE public.dispatch_stops 
    SET status = p_to_status, 
        updated_at = now(),
        actual_arrival_at = CASE WHEN p_to_status = 'arrived' THEN now() ELSE actual_arrival_at END,
        actual_departure_at = CASE WHEN p_to_status = 'departed' OR p_to_status IN ('completed', 'delivered', 'refused', 'returned', 'partial_delivery', 'failed') THEN now() ELSE actual_departure_at END
    WHERE id = p_stop_id AND tenant_id = p_tenant_id;

    -- Audit Log
    INSERT INTO public.entity_state_audit_log (
        tenant_id, entity_type, entity_id, from_status, to_status, actor_id, reason, idempotency_key, metadata
    ) VALUES (
        p_tenant_id, 'stop', p_stop_id, v_from_status, p_to_status, p_actor_id, p_reason, p_idempotency_key, p_metadata
    );

    -- Trigger aggregate derivation
    PERFORM public.derive_trip_and_load_status_v1(p_tenant_id, v_trip_id);

    RETURN p_to_status;
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_data_consistency_v3(p_tenant_id uuid, p_fix boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_report jsonb := '{}'::jsonb;
    v_orphans uuid[];
    v_stuck_trips jsonb[];
BEGIN
    -- orphan_load_trips
    SELECT array_agg(id) INTO v_orphans
    FROM public.loads l
    WHERE tenant_id = p_tenant_id 
      AND trip_id IS NOT NULL 
      AND NOT EXISTS (SELECT 1 FROM public.dispatch_trip_loads dtl WHERE dtl.load_id = l.id);
    
    v_report := v_report || jsonb_build_object('orphan_load_trips', COALESCE(v_orphans, '{}'::uuid[]));

    -- Impossible transitions: Trips in 'completed' but with active stops
    SELECT array_agg(jsonb_build_object('trip_id', dt.id, 'active_stops', (SELECT count(*) FROM public.dispatch_stops ds WHERE ds.dispatch_trip_id = dt.id AND ds.status NOT IN ('completed', 'delivered', 'cancelled', 'skipped', 'refused', 'returned', 'partial_delivery', 'failed'))))
    INTO v_stuck_trips
    FROM public.dispatch_trips dt
    WHERE dt.tenant_id = p_tenant_id AND dt.status = 'completed'
      AND EXISTS (SELECT 1 FROM public.dispatch_stops ds WHERE ds.dispatch_trip_id = dt.id AND ds.status NOT IN ('completed', 'delivered', 'cancelled', 'skipped', 'refused', 'returned', 'partial_delivery', 'failed'));

    v_report := v_report || jsonb_build_object('stuck_completed_trips', COALESCE(v_stuck_trips, ARRAY[]::jsonb[]));

    IF p_fix THEN
        IF v_orphans IS NOT NULL THEN
            UPDATE public.loads SET trip_id = NULL WHERE id = ANY(v_orphans) AND tenant_id = p_tenant_id;
        END IF;
        -- Repair stuck trips: complete stops
        UPDATE public.dispatch_stops ds
        SET status = 'completed', updated_at = now()
        FROM public.dispatch_trips dt
        WHERE ds.dispatch_trip_id = dt.id 
          AND dt.status = 'completed'
          AND ds.status NOT IN ('completed', 'delivered', 'cancelled', 'skipped', 'refused', 'returned', 'partial_delivery', 'failed')
          AND dt.tenant_id = p_tenant_id;
    END IF;

    RETURN v_report;
END;
$function$;

CREATE OR REPLACE FUNCTION public.transition_trip_status_v1(p_tenant_id uuid, p_trip_id uuid, p_to_status text, p_actor_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_from_status text;
    v_allowed boolean := false;
BEGIN
    IF NOT public.is_tenant_operator_or_admin(p_tenant_id) AND 
       NOT EXISTS (SELECT 1 FROM public.dispatch_trips WHERE id = p_trip_id AND tenant_id = p_tenant_id AND driver_id IN (SELECT id FROM public.drivers WHERE user_id = auth.uid())) THEN
        RAISE EXCEPTION 'Não autorizado a transicionar status desta viagem';
    END IF;

    -- Idempotency check
    IF p_idempotency_key IS NOT NULL THEN
        SELECT to_status INTO v_from_status FROM public.entity_state_audit_log 
        WHERE tenant_id = p_tenant_id AND idempotency_key = p_idempotency_key;
        IF FOUND THEN RETURN v_from_status; END IF;
    END IF;

    -- Get current state
    SELECT status INTO v_from_status
    FROM public.dispatch_trips 
    WHERE id = p_trip_id AND tenant_id = p_tenant_id;

    IF NOT FOUND THEN RAISE EXCEPTION 'Viagem não encontrada'; END IF;

    -- State Machine Logic
    CASE v_from_status
        WHEN 'planned' THEN v_allowed := p_to_status IN ('loading', 'in_transit', 'cancelled');
        WHEN 'loading' THEN v_allowed := p_to_status IN ('in_transit', 'cancelled');
        WHEN 'in_transit' THEN v_allowed := p_to_status IN ('completed', 'cancelled');
        ELSE v_allowed := false;
    END CASE;

    -- Override for Admins
    IF NOT v_allowed AND NOT public.is_tenant_admin(p_tenant_id) THEN
        RAISE EXCEPTION 'Transição de status inválida: % -> %', v_from_status, p_to_status;
    END IF;

    -- Update Trip
    UPDATE public.dispatch_trips 
    SET status = p_to_status, 
        updated_at = now(),
        actual_start_at = CASE WHEN p_to_status = 'in_transit' THEN COALESCE(actual_start_at, now()) ELSE actual_start_at END,
        actual_end_at = CASE WHEN p_to_status = 'completed' THEN now() ELSE actual_end_at END
    WHERE id = p_trip_id AND tenant_id = p_tenant_id;

    -- Audit Log
    INSERT INTO public.entity_state_audit_log (
        tenant_id, entity_type, entity_id, from_status, to_status, actor_id, reason, idempotency_key, metadata
    ) VALUES (
        p_tenant_id, 'trip', p_trip_id, v_from_status, p_to_status, p_actor_id, p_reason, p_idempotency_key, p_metadata
    );

    RETURN p_to_status;
END;
$function$;

CREATE OR REPLACE FUNCTION public.list_loads_v1(p_tenant_id uuid, p_search text DEFAULT NULL::text, p_status text[] DEFAULT NULL::text[], p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_total_count bigint;
    v_items jsonb;
    v_next_cursor timestamptz;
BEGIN
    SELECT count(*) INTO v_total_count
    FROM public.loads
    WHERE tenant_id = p_tenant_id
      AND (p_status IS NULL OR status = ANY(p_status))
      AND (p_search IS NULL OR 
           load_number ILIKE '%' || p_search || '%' OR 
           origin ILIKE '%' || p_search || '%' OR 
           destination ILIKE '%' || p_search || '%');

    SELECT jsonb_agg(t) INTO v_items FROM (
        SELECT l.*, 
               (SELECT row_to_json(v) FROM (SELECT plate, nickname FROM vehicles WHERE id = l.vehicle_id) v) as vehicles,
               (SELECT row_to_json(d) FROM (SELECT name FROM drivers WHERE id = l.driver_id) d) as drivers
        FROM public.loads l
        WHERE l.tenant_id = p_tenant_id
          AND (p_status IS NULL OR l.status = ANY(p_status))
          AND (p_search IS NULL OR 
               l.load_number ILIKE '%' || p_search || '%' OR 
               l.origin ILIKE '%' || p_search || '%' OR 
               l.destination ILIKE '%' || p_search || '%')
          AND (p_cursor IS NULL OR l.created_at < p_cursor)
        ORDER BY l.created_at DESC
        LIMIT p_limit
    ) t;

    IF v_items IS NOT NULL AND jsonb_array_length(v_items) = p_limit THEN
        v_next_cursor := (v_items->(p_limit-1)->>'created_at')::timestamptz;
    END IF;

    RETURN jsonb_build_object(
        'items', COALESCE(v_items, '[]'::jsonb),
        'next_cursor', v_next_cursor,
        'total_count', v_total_count
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.list_fiscal_documents_v1(p_tenant_id uuid, p_search text DEFAULT NULL::text, p_type text[] DEFAULT NULL::text[], p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_total_count bigint;
    v_items jsonb;
    v_next_cursor timestamptz;
BEGIN
    SELECT count(*) INTO v_total_count
    FROM public.fiscal_documents
    WHERE tenant_id = p_tenant_id
      AND deleted_at IS NULL
      AND (p_type IS NULL OR document_type = ANY(p_type))
      AND (p_search IS NULL OR 
           invoice_number ILIKE '%' || p_search || '%' OR 
           access_key ILIKE '%' || p_search || '%' OR 
           recipient ILIKE '%' || p_search || '%');

    SELECT jsonb_agg(t) INTO v_items FROM (
        SELECT d.*, 
               c.company_name as client_name,
               l.load_number
        FROM public.fiscal_documents d
        LEFT JOIN public.clients c ON c.id = d.client_id
        LEFT JOIN public.loads l ON l.id = d.load_id
        WHERE d.tenant_id = p_tenant_id
          AND d.deleted_at IS NULL
          AND (p_type IS NULL OR d.document_type = ANY(p_type))
          AND (p_search IS NULL OR 
               d.invoice_number ILIKE '%' || p_search || '%' OR 
               d.access_key ILIKE '%' || p_search || '%' OR 
               d.recipient ILIKE '%' || p_search || '%')
          AND (p_cursor IS NULL OR d.created_at < p_cursor)
        ORDER BY d.created_at DESC
        LIMIT p_limit
    ) t;

    IF v_items IS NOT NULL AND jsonb_array_length(v_items) = p_limit THEN
        v_next_cursor := (v_items->(p_limit-1)->>'created_at')::timestamptz;
    END IF;

    RETURN jsonb_build_object(
        'items', COALESCE(v_items, '[]'::jsonb),
        'next_cursor', v_next_cursor,
        'total_count', v_total_count
    );
END;
$function$;

