CREATE OR REPLACE FUNCTION public.get_next_load_number_v1(p_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_max_num integer;
BEGIN
  SELECT MAX(NULLIF(regexp_replace(load_number, '\D', '', 'g'), '')::integer)
  INTO v_max_num
  FROM public.loads
  WHERE tenant_id = p_tenant_id;
  
  IF v_max_num IS NULL OR v_max_num < 1000 THEN
    RETURN '1000';
  ELSE
    RETURN (v_max_num + 1)::text;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_driver_workspace_v1(p_driver_id uuid, p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_trip_record record;
    v_loads jsonb;
    v_stops jsonb;
    v_progress jsonb;
    v_next_action jsonb;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.drivers WHERE id = p_driver_id AND tenant_id = p_tenant_id AND user_id = auth.uid()) THEN
        RAISE EXCEPTION 'Acesso negado ao workspace do motorista';
    END IF;

    -- 1. Identify active trip
    SELECT * INTO v_trip_record
    FROM public.dispatch_trips
    WHERE driver_id = p_driver_id
      AND tenant_id = p_tenant_id
      AND status NOT IN ('completed', 'cancelled')
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_trip_record.id IS NULL THEN
        RETURN jsonb_build_object(
            'has_active_trip', false,
            'driver_id', p_driver_id
        );
    END IF;

    -- 2. Fetch loads via canonical mapping
    SELECT jsonb_agg(l.*) INTO v_loads
    FROM (
        SELECT 
            loads.id,
            loads.load_number,
            loads.status,
            loads.origin,
            loads.destination,
            loads.total_value,
            loads.total_weight
        FROM public.dispatch_trip_loads dtl
        JOIN public.loads ON loads.id = dtl.load_id
        WHERE dtl.trip_id = v_trip_record.id
    ) l;

    -- 3. Fetch stops and stop-level documents
    SELECT jsonb_agg(s.*) INTO v_stops
    FROM (
        SELECT 
            ds.id,
            ds.stop_order,
            ds.status,
            ds.stop_type,
            ds.location_name,
            ds.address,
            ds.arrival_time,
            ds.departure_time,
            (
                SELECT jsonb_agg(doc.*)
                FROM (
                    SELECT 
                        fd.id,
                        fd.invoice_number as number,
                        fd.invoice_series as series,
                        fd.total_value,
                        dsd.status as stop_status
                    FROM public.dispatch_stop_documents dsd
                    JOIN public.fiscal_documents fd ON fd.id = dsd.fiscal_document_id
                    WHERE dsd.dispatch_stop_id = ds.id
                ) doc
            ) as documents
        FROM public.dispatch_stops ds
        WHERE ds.dispatch_trip_id = v_trip_record.id
        ORDER BY ds.stop_order ASC
    ) s;

    -- 4. Calculate progress
    SELECT jsonb_build_object(
        'total_stops', count(*),
        'completed_stops', count(*) FILTER (WHERE status = 'completed'),
        'pending_stops', count(*) FILTER (WHERE status IN ('pending', 'arrived', 'in_progress'))
    ) INTO v_progress
    FROM public.dispatch_stops
    WHERE dispatch_trip_id = v_trip_record.id;

    -- 5. Determine next action
    SELECT jsonb_build_object(
        'stop_id', id,
        'stop_type', stop_type,
        'status', status,
        'location_name', location_name
    ) INTO v_next_action
    FROM public.dispatch_stops
    WHERE dispatch_trip_id = v_trip_record.id
      AND status != 'completed'
    ORDER BY stop_order ASC
    LIMIT 1;

    RETURN jsonb_build_object(
        'has_active_trip', true,
        'trip', jsonb_build_object(
            'id', v_trip_record.id,
            'status', v_trip_record.status,
            'start_km', v_trip_record.start_km,
            'created_at', v_trip_record.created_at
        ),
        'loads', COALESCE(v_loads, '[]'::jsonb),
        'stops', COALESCE(v_stops, '[]'::jsonb),
        'progress', v_progress,
        'next_action', v_next_action
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.driver_report_event_v1(p_driver_id uuid, p_tenant_id uuid, p_trip_id uuid, p_stop_id uuid, p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id uuid := auth.uid();
    v_event_id uuid;
BEGIN
    -- 1. Validate Ownership and Tenant
    IF NOT EXISTS (
        SELECT 1 FROM public.drivers 
        WHERE id = p_driver_id AND tenant_id = p_tenant_id AND user_id = v_user_id
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Driver mismatch';
    END IF;

    -- 2. Idempotency Check
    IF p_idempotency_key IS NOT NULL THEN
        SELECT id INTO v_event_id 
        FROM public.dispatch_events 
        WHERE payload->>'idempotency_key' = p_idempotency_key
          AND tenant_id = p_tenant_id;
        
        IF v_event_id IS NOT NULL THEN
            RETURN jsonb_build_object('status', 'success', 'event_id', v_event_id, 'idempotent', true);
        END IF;
    END IF;

    -- 3. Log Event
    INSERT INTO public.dispatch_events (
        tenant_id,
        dispatch_trip_id,
        dispatch_stop_id,
        event_type,
        event_at,
        payload,
        created_by
    ) VALUES (
        p_tenant_id,
        p_trip_id,
        p_stop_id,
        p_event_type,
        now(),
        p_payload || jsonb_build_object('idempotency_key', p_idempotency_key),
        v_user_id
    ) RETURNING id INTO v_event_id;

    -- 4. State Transitions (Synchronous)
    IF p_event_type = 'trip_start' THEN
        UPDATE public.dispatch_trips 
        SET status = 'in_transit', 
            start_km = (p_payload->>'odometer')::numeric,
            started_at = now()
        WHERE id = p_trip_id AND tenant_id = p_tenant_id;
        
    ELSIF p_event_type = 'arrival' THEN
        UPDATE public.dispatch_stops 
        SET status = 'arrived', 
            arrival_time = now()
        WHERE id = p_stop_id AND trip_id = p_trip_id AND tenant_id = p_tenant_id;

    ELSIF p_event_type = 'departure' OR p_event_type = 'delivery_complete' THEN
        UPDATE public.dispatch_stops 
        SET status = 'completed', 
            departure_time = now()
        WHERE id = p_stop_id AND trip_id = p_trip_id AND tenant_id = p_tenant_id;

    ELSIF p_event_type = 'trip_end' THEN
        UPDATE public.dispatch_trips 
        SET status = 'completed', 
            end_km = (p_payload->>'odometer')::numeric,
            completed_at = now()
        WHERE id = p_trip_id AND tenant_id = p_tenant_id;
    END IF;

    RETURN jsonb_build_object('status', 'success', 'event_id', v_event_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.log_operational_event_v2(p_tenant_id uuid, p_event_type text, p_dispatch_stop_id uuid DEFAULT NULL::uuid, p_fiscal_document_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_pod_data jsonb DEFAULT NULL::jsonb, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id uuid := auth.uid();
    v_event_id uuid;
    v_pod_id uuid;
    v_content_hash text;
BEGIN
    IF NOT public.is_tenant_member(p_tenant_id) THEN
        RAISE EXCEPTION 'forbidden';
    END IF;
    -- Validate stop ownership if provided
    IF p_dispatch_stop_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.dispatch_stops WHERE id = p_dispatch_stop_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'Parada inválida para este tenant';
    END IF;

    IF p_idempotency_key IS NOT NULL THEN
        SELECT id INTO v_event_id FROM public.operational_events 
        WHERE tenant_id = p_tenant_id AND idempotency_key = p_idempotency_key;
        IF v_event_id IS NOT NULL THEN
            RETURN jsonb_build_object('status', 'success', 'event_id', v_event_id, 'idempotent', true);
        END IF;
    END IF;

    IF p_pod_data IS NOT NULL THEN
        v_content_hash := encode(digest(p_pod_data::text, 'sha256'), 'hex');
        UPDATE public.proof_of_delivery SET is_active = false 
        WHERE dispatch_stop_id = p_dispatch_stop_id 
          AND (fiscal_document_id = p_fiscal_document_id OR (fiscal_document_id IS NULL AND p_fiscal_document_id IS NULL))
          AND tenant_id = p_tenant_id;
        INSERT INTO public.proof_of_delivery (
            tenant_id, dispatch_stop_id, fiscal_document_id, receiver_name, receiver_document,
            received_at, photo_url, signature_url, latitude, longitude, accuracy, content_hash, version, created_by
        ) VALUES (
            p_tenant_id, p_dispatch_stop_id, p_fiscal_document_id, p_pod_data->>'receiver_name', p_pod_data->>'receiver_tax_id',
            COALESCE((p_pod_data->>'signed_at')::timestamp with time zone, now()), p_pod_data->>'photo_url', p_pod_data->>'signature_url',
            (p_pod_data->>'latitude')::numeric, (p_pod_data->>'longitude')::numeric, (p_pod_data->>'accuracy')::numeric, v_content_hash,
            COALESCE((SELECT max(version) + 1 FROM public.proof_of_delivery WHERE dispatch_stop_id = p_dispatch_stop_id), 1), v_user_id
        ) RETURNING id INTO v_pod_id;
    END IF;

    INSERT INTO public.operational_events (
        tenant_id, event_type, dispatch_stop_id, proof_of_delivery_id, payload, idempotency_key, created_by
    ) VALUES (
        p_tenant_id, p_event_type, p_dispatch_stop_id, v_pod_id, p_payload, p_idempotency_key, v_user_id
    ) RETURNING id INTO v_event_id;

    IF p_event_type IN ('delivery_success', 'delivery_failure') THEN
        INSERT INTO public.delivery_occurrences (
            tenant_id, fiscal_document_id, dispatch_stop_id, occurrence_type, occurrence_description, status, created_by
        ) VALUES (
            p_tenant_id, p_fiscal_document_id, p_dispatch_stop_id, p_event_type, p_payload->>'description',
            CASE WHEN p_event_type = 'delivery_success' THEN 'completed' ELSE 'pending' END, v_user_id
        );
    END IF;

    RETURN jsonb_build_object('status', 'success', 'event_id', v_event_id, 'pod_id', v_pod_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.approve_financial_obligation_v1(_obligation_id uuid, _notes text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_rec public.financial_obligations;
    v_ledger_id uuid;
    v_user_id uuid := auth.uid();
BEGIN
    SELECT * INTO v_rec FROM public.financial_obligations WHERE id = _obligation_id;
    
    IF NOT public.is_tenant_operator_or_admin(v_rec.tenant_id) THEN
        RAISE EXCEPTION 'forbidden';
    END IF;

    IF v_rec.status != 'pending' THEN
        RETURN FALSE;
    END IF;

    -- Update obligation
    UPDATE public.financial_obligations
    SET 
        status = 'approved',
        auditor_id = v_user_id,
        audited_at = now(),
        metadata = metadata || jsonb_build_object('approval_notes', _notes),
        updated_at = now()
    WHERE id = _obligation_id;

    -- Create Ledger Entry
    -- Credit for Inflow (Receivables), Debit for Outflow (Payables/Settlements)
    v_ledger_id := public.create_ledger_entry_v1(
        v_rec.tenant_id,
        'financial_obligations',
        v_rec.id,
        v_rec.obligation_type,
        CASE WHEN v_rec.direction = 'inflow' THEN 'credit' ELSE 'debit' END,
        v_rec.amount_expected,
        COALESCE(_notes, v_rec.description),
        jsonb_build_object('obligation_id', v_rec.id, 'direction', v_rec.direction)
    );

    UPDATE public.financial_obligations SET ledger_entry_id = v_ledger_id WHERE id = _obligation_id;

    RETURN TRUE;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reverse_financial_obligation_v1(_obligation_id uuid, _reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_tenant_id uuid;
    v_user_id uuid := auth.uid();
BEGIN
    SELECT tenant_id INTO v_tenant_id FROM public.financial_obligations WHERE id = _obligation_id;
    
    IF NOT public.is_tenant_operator_or_admin(v_tenant_id) THEN
        RAISE EXCEPTION 'forbidden';
    END IF;

    -- Only pending or approved can be reversed (paid ones need refund flow)
    UPDATE public.financial_obligations
    SET 
        status = 'cancelled',
        metadata = metadata || jsonb_build_object('reversal_reason', _reason, 'reversed_by', v_user_id, 'reversed_at', now()),
        updated_at = now()
    WHERE id = _obligation_id
      AND status IN ('pending', 'approved');

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    RETURN TRUE;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_operational_financial_summary_v1(_tenant_id uuid, _date_from date DEFAULT NULL::date, _date_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_revenue numeric := 0;
    v_outflow numeric := 0;
    v_ledger_balance numeric := 0;
    v_receivable_total numeric := 0;
    v_receivable_pending numeric := 0;
    v_receivable_paid numeric := 0;
    v_receivable_overdue numeric := 0;
    v_expenses_total numeric := 0;
    v_maintenance_total numeric := 0;
    v_today date := current_date;
BEGIN
    IF NOT public.is_tenant_member(_tenant_id) THEN
        RAISE EXCEPTION 'forbidden';
    END IF;

    -- 1. Ledger Balance (The Truth)
    SELECT COALESCE(SUM(CASE WHEN nature = 'credit' THEN amount ELSE -amount END), 0)
    INTO v_ledger_balance
    FROM public.operational_ledger
    WHERE tenant_id = _tenant_id
      AND status = 'active'
      AND (_date_from IS NULL OR created_at::date >= _date_from)
      AND (_date_to IS NULL OR created_at::date <= _date_to);

    -- 2. Revenue (CT-e confirmed + NFSe confirmed)
    SELECT COALESCE(SUM(freight_value), 0) INTO v_revenue
    FROM public.fiscal_documents
    WHERE tenant_id = _tenant_id
      AND document_type = 'outbound'
      AND status IN ('authorized', 'registered')
      AND (_date_from IS NULL OR issue_date >= _date_from)
      AND (_date_to IS NULL OR issue_date <= _date_to);

    SELECT v_revenue + COALESCE(SUM(valor_servicos), 0) INTO v_revenue
    FROM public.nfse_documents
    WHERE tenant_id = _tenant_id
      AND status IN ('authorized', 'registered')
      AND (_date_from IS NULL OR issue_date >= _date_from)
      AND (_date_to IS NULL OR issue_date <= _date_to);

    -- 3. Receivables
    SELECT 
        COALESCE(SUM(amount), 0),
        COALESCE(SUM(CASE WHEN status IN ('pending', 'invoiced', 'partial') THEN amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN status = 'received' THEN COALESCE(received_amount, amount) ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN status IN ('pending', 'invoiced', 'partial') AND due_date < v_today THEN amount ELSE 0 END), 0)
    INTO 
        v_receivable_total, v_receivable_pending, v_receivable_paid, v_receivable_overdue
    FROM public.receivables
    WHERE tenant_id = _tenant_id
      AND status != 'cancelled'
      AND (_date_from IS NULL OR due_date >= _date_from)
      AND (_date_to IS NULL OR due_date <= _date_to);

    -- 4. Expenses
    SELECT COALESCE(SUM(amount), 0) INTO v_expenses_total
    FROM public.driver_expenses
    WHERE tenant_id = _tenant_id
      AND approval_status = 'approved'
      AND (_date_from IS NULL OR expense_at::date >= _date_from)
      AND (_date_to IS NULL OR expense_at::date <= _date_to);

    -- 5. Maintenance
    SELECT COALESCE(SUM(total_cost), 0) INTO v_maintenance_total
    FROM public.maintenance_orders
    WHERE tenant_id = _tenant_id
      AND status IN ('completed', 'closed')
      AND (_date_from IS NULL OR created_at::date >= _date_from)
      AND (_date_to IS NULL OR created_at::date <= _date_to);

    v_outflow := v_expenses_total + v_maintenance_total;

    RETURN jsonb_build_object(
        'revenue', v_revenue,
        'outflow', v_outflow,
        'balance', v_revenue - v_outflow,
        'totalReceivable', v_receivable_total,
        'pendingReceivable', v_receivable_pending,
        'paidReceivable', v_receivable_paid,
        'overdueReceivable', v_receivable_overdue,
        'totalExpenses', v_expenses_total,
        'totalMaintenance', v_maintenance_total,
        'ledgerBalance', v_ledger_balance
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_ledger_entry_v1(_tenant_id uuid, _source_table text, _source_id uuid, _entry_type text, _nature text, _amount numeric, _description text, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id uuid;
BEGIN
    INSERT INTO public.operational_ledger (
        tenant_id, source_table, source_id, entry_type, nature, amount, status, metadata
    )
    VALUES (
        _tenant_id, _source_table, _source_id, _entry_type, _nature::public.ledger_nature, _amount, 'active', 
        _metadata || jsonb_build_object('description', _description)
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_data_consistency_v4(p_tenant_id uuid)
 RETURNS TABLE(severity text, domain text, entity_type text, entity_id text, message text, suggested_action text, metadata jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
        RAISE EXCEPTION 'forbidden';
    END IF;

    -- Vínculos órfãos: Cargas com trip_id sem relação na dispatch_trip_loads
    RETURN QUERY
    SELECT 
        'critical'::text as severity,
        'Logística'::text as domain,
        'load'::text as entity_type,
        l.id::text as entity_id,
        'Carga vinculada a viagem inexistente ou órfã (Load.trip_id set mas dispatch_trip_loads ausente)'::text as message,
        'Remover trip_id órfão ou recriar vínculo canônico'::text as suggested_action,
        jsonb_build_object('trip_id', l.trip_id) as metadata
    FROM public.loads l
    WHERE l.tenant_id = p_tenant_id 
      AND l.trip_id IS NOT NULL 
      AND NOT EXISTS (SELECT 1 FROM public.dispatch_trip_loads dtl WHERE dtl.load_id = l.id);

    -- Estados impossíveis: Viagem concluída com paradas ativas
    RETURN QUERY
    SELECT 
        'critical'::text as severity,
        'Logística'::text as domain,
        'trip'::text as entity_type,
        dt.id::text as entity_id,
        'Viagem concluída possui paradas em estado não-terminal'::text as message,
        'Concluir paradas pendentes da viagem'::text as suggested_action,
        jsonb_build_object('stop_count', (SELECT count(*) FROM public.dispatch_stops ds WHERE ds.dispatch_trip_id = dt.id AND ds.status NOT IN ('completed', 'delivered', 'cancelled', 'skipped', 'refused', 'returned', 'partial_delivery', 'failed'))) as metadata
    FROM public.dispatch_trips dt
    WHERE dt.tenant_id = p_tenant_id 
      AND dt.status = 'completed'
      AND EXISTS (SELECT 1 FROM public.dispatch_stops ds WHERE ds.dispatch_trip_id = dt.id AND ds.status NOT IN ('completed', 'delivered', 'cancelled', 'skipped', 'refused', 'returned', 'partial_delivery', 'failed'));

    -- Duplicidades: Notas fiscais com mesma chave
    RETURN QUERY
    SELECT 
        'warning'::text as severity,
        'Fiscal'::text as domain,
        'fiscal_document'::text as entity_type,
        fd.id::text as entity_id,
        'Chave de acesso duplicada detectada'::text as message,
        'Mesclar ou remover documento duplicado'::text as suggested_action,
        jsonb_build_object('access_key', fd.access_key) as metadata
    FROM public.fiscal_documents fd
    WHERE fd.tenant_id = p_tenant_id
      AND fd.access_key IN (
          SELECT access_key 
          FROM public.fiscal_documents 
          WHERE tenant_id = p_tenant_id 
          GROUP BY access_key 
          HAVING count(*) > 1
      );

    -- RLS / Tenant Leakage (Self-audit)
    RETURN QUERY
    SELECT 
        'critical'::text as severity,
        'Segurança'::text as domain,
        'table'::text as entity_type,
        c.relname::text as entity_id,
        'Tabela no schema public sem RLS habilitada'::text as message,
        'Executar ALTER TABLE ENABLE ROW LEVEL SECURITY'::text as suggested_action,
        '{}'::jsonb as metadata
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'r'
      AND NOT c.relrowsecurity;
END;
$function$;

CREATE OR REPLACE FUNCTION public.link_items_to_load_v2(p_tenant_id uuid, p_load_id uuid, p_item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_item_count int;
BEGIN
    IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
        RAISE EXCEPTION 'Acesso negado';
    END IF;

    -- Validação de existência da carga
    IF NOT EXISTS (SELECT 1 FROM public.loads WHERE id = p_load_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'Carga não encontrada';
    END IF;

    -- Update atômico dos itens (Source of Truth)
    UPDATE public.load_items
    SET load_id = p_load_id,
        updated_at = now()
    WHERE id = ANY(p_item_ids) 
      AND tenant_id = p_tenant_id;
    
    GET DIAGNOSTICS v_item_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'status', 'success',
        'items_linked', v_item_count
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.move_load_items_v3(p_tenant_id uuid, p_source_load_id uuid, p_target_load_id uuid, p_item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
        RAISE EXCEPTION 'Acesso negado';
    END IF;

    UPDATE public.load_items
    SET load_id = p_target_load_id,
        updated_at = now()
    WHERE id = ANY(p_item_ids) 
      AND load_id = p_source_load_id
      AND tenant_id = p_tenant_id;

    RETURN jsonb_build_object('status', 'success');
END;
$function$;

