 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RAISE EXCEPTION 'FEATURE_DISABLED: execute_data_repair_v1 is currently inactive.';
END;
$function$;

CREATE OR REPLACE FUNCTION public.list_employees_v1(p_tenant_id uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_items jsonb;
    v_total int;
BEGIN
    IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
        RAISE EXCEPTION 'Acesso negado';
    END IF;

    SELECT jsonb_agg(t) INTO v_items
    FROM (
        SELECT * FROM public.employees
        WHERE tenant_id = p_tenant_id
          AND (p_search IS NULL OR name ILIKE '%' || p_search || '%' OR doc_cpf ILIKE '%' || p_search || '%')
          AND (p_status IS NULL OR status = p_status)
        ORDER BY name ASC
        LIMIT p_limit OFFSET p_offset
    ) t;

    SELECT count(*) INTO v_total
    FROM public.employees
    WHERE tenant_id = p_tenant_id
      AND (p_search IS NULL OR name ILIKE '%' || p_search || '%' OR doc_cpf ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR status = p_status);

    RETURN jsonb_build_object(
        'items', COALESCE(v_items, '[]'::jsonb),
        'total_count', v_total
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.plan_dispatch_trip_v2(p_tenant_id uuid, p_driver_id uuid, p_vehicle_id uuid, p_route_name text, p_load_ids uuid[], p_stops jsonb, p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_trip_id uuid;
    v_stop record;
    v_stop_id uuid;
    v_doc_id uuid;
    v_load_id uuid;
BEGIN
    IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
        RAISE EXCEPTION 'Acesso negado';
    END IF;

    -- Idempotency check
    IF p_idempotency_key IS NOT NULL THEN
        SELECT id INTO v_trip_id FROM public.dispatch_trips 
        WHERE tenant_id = p_tenant_id AND (metadata->>'idempotency_key' = p_idempotency_key OR CAST(id AS TEXT) = p_idempotency_key);
        IF FOUND THEN
            RETURN v_trip_id;
        END IF;
    END IF;

    -- Validate tenants
    IF NOT EXISTS (SELECT 1 FROM public.drivers WHERE id = p_driver_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'Motorista inválido';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.vehicles WHERE id = p_vehicle_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'Veículo inválido';
    END IF;

    -- 1. Create Trip
    -- Note: We store route_name in metadata if column is missing (fallback)
    INSERT INTO public.dispatch_trips (
        tenant_id, driver_id, vehicle_id, status, planned_start_at, metadata
    ) VALUES (
        p_tenant_id, p_driver_id, p_vehicle_id, 'planned', now(), 
        jsonb_build_object('idempotency_key', p_idempotency_key, 'route_name', p_route_name)
    ) RETURNING id INTO v_trip_id;

    -- 2. Link Loads
    FOREACH v_load_id IN ARRAY p_load_ids
    LOOP
        IF NOT EXISTS (SELECT 1 FROM public.loads WHERE id = v_load_id AND tenant_id = p_tenant_id) THEN
            RAISE EXCEPTION 'Carga % inválida', v_load_id;
        END IF;

        INSERT INTO public.dispatch_trip_loads (trip_id, load_id, tenant_id)
        VALUES (v_trip_id, v_load_id, p_tenant_id);
        
        UPDATE public.loads SET trip_id = v_trip_id, status = 'loaded' WHERE id = v_load_id;
    END LOOP;

    -- 3. Create Stops and link documents
    FOR v_stop IN SELECT * FROM jsonb_to_recordset(p_stops) AS x(destination text, client_id uuid, stop_order int, document_ids uuid[])
    LOOP
        INSERT INTO public.dispatch_stops (
            tenant_id, dispatch_trip_id, destination, client_id, stop_order, status
        ) VALUES (
            p_tenant_id, v_trip_id, v_stop.destination, v_stop.client_id, v_stop.stop_order, 'pending'
        ) RETURNING id INTO v_stop_id;

        IF v_stop.document_ids IS NOT NULL THEN
            FOREACH v_doc_id IN ARRAY v_stop.document_ids
            LOOP
                INSERT INTO public.dispatch_stop_documents (
                    tenant_id, dispatch_stop_id, fiscal_document_id, status
                ) VALUES (
                    p_tenant_id, v_stop_id, v_doc_id, 'pending'
                );
            END LOOP;
        END IF;
    END LOOP;

    -- Audit
    INSERT INTO public.entity_state_audit_log (
        tenant_id, entity_type, entity_id, action, state_after
    ) VALUES (
        p_tenant_id, 'dispatch_trip', v_trip_id, 'create_plan', jsonb_build_object('status', 'planned', 'loads', p_load_ids)
    );

    RETURN v_trip_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_tenant_membership(p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.tenant_memberships
        WHERE user_id = auth.uid()
          AND tenant_id = p_tenant_id
          AND active = true
    ) AND auth.role() != 'service_role' THEN
        RAISE EXCEPTION 'Acesso negado: Usuário não é membro do tenant %', p_tenant_id;
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_load_v1(p_tenant_id uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_driver_id uuid DEFAULT NULL::uuid, p_origin text DEFAULT ''::text, p_destination text DEFAULT ''::text, p_notes text DEFAULT NULL::text, p_operation_type text DEFAULT NULL::text, p_scheduled_load_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_load_id uuid;
    v_load_number text;
BEGIN
    IF p_idempotency_key IS NOT NULL THEN
        IF EXISTS (SELECT 1 FROM public.idempotency_keys WHERE tenant_id = p_tenant_id AND key_value = p_idempotency_key) THEN
            RAISE EXCEPTION 'Duplicate request (idempotency)';
        END IF;
        INSERT INTO public.idempotency_keys (tenant_id, key_value) VALUES (p_tenant_id, p_idempotency_key);
    END IF;

    IF p_vehicle_id IS NOT NULL AND NOT check_resource_ownership(p_tenant_id, p_vehicle_id, 'vehicles') THEN
        RAISE EXCEPTION 'Vehicle does not belong to tenant';
    END IF;
    IF p_driver_id IS NOT NULL AND NOT check_resource_ownership(p_tenant_id, p_driver_id, 'drivers') THEN
        RAISE EXCEPTION 'Driver does not belong to tenant';
    END IF;

    SELECT COALESCE(MAX(load_number::int), 1000) + 1 INTO v_load_number
    FROM public.loads
    WHERE tenant_id = p_tenant_id;

    INSERT INTO public.loads (
        tenant_id, load_number, vehicle_id, driver_id, origin, destination, 
        notes, operation_type, scheduled_load_at, status
    ) VALUES (
        p_tenant_id, v_load_number, p_vehicle_id, p_driver_id, p_origin, p_destination,
        p_notes, p_operation_type, p_scheduled_load_at, 'assembling'
    ) RETURNING id INTO v_load_id;

    INSERT INTO public.entity_state_audit_log (
        tenant_id, entity_type, entity_id, to_status, idempotency_key
    ) VALUES (
        p_tenant_id, 'load', v_load_id, 'assembling', p_idempotency_key
    );

    RETURN v_load_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_load_item_v1(p_tenant_id uuid, p_load_id uuid, p_item_description text, p_quantity numeric, p_pallet_count numeric DEFAULT 0, p_weight_kg numeric DEFAULT 0, p_volume_m3 numeric DEFAULT 0, p_fiscal_document_id uuid DEFAULT NULL::uuid, p_item_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_item_id uuid;
BEGIN
    IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
        RAISE EXCEPTION 'Acesso negado';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.loads WHERE id = p_load_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'Carga não encontrada';
    END IF;

    -- Validate fiscal document tenant
    IF p_fiscal_document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.fiscal_documents WHERE id = p_fiscal_document_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'Documento fiscal inválido';
    END IF;

    IF p_item_id IS NOT NULL THEN
        -- Update
        UPDATE public.load_items SET
            load_id = p_load_id,
            item_description = p_item_description,
            quantity = p_quantity,
            pallet_count = p_pallet_count,
            weight_kg = p_weight_kg,
            volume_m3 = p_volume_m3,
            fiscal_document_id = p_fiscal_document_id,
            updated_at = now()
        WHERE id = p_item_id AND tenant_id = p_tenant_id
        RETURNING id INTO v_item_id;
        
        IF NOT FOUND THEN RAISE EXCEPTION 'Item não encontrado'; END IF;
    ELSE
        -- Insert
        INSERT INTO public.load_items (
            tenant_id, load_id, item_description, quantity, pallet_count, weight_kg, volume_m3, fiscal_document_id
        ) VALUES (
            p_tenant_id, p_load_id, p_item_description, p_quantity, p_pallet_count, p_weight_kg, p_volume_m3, p_fiscal_document_id
        ) RETURNING id INTO v_item_id;
    END IF;

    RETURN v_item_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.execute_data_repair_v1(_tenant_id uuid, _batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
