CREATE OR REPLACE FUNCTION public.check_resource_ownership(p_tenant_id uuid, p_resource_id uuid, p_table_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_exists boolean;
BEGIN
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I WHERE id = $1 AND tenant_id = $2)', p_table_name)
    INTO v_exists
    USING p_resource_id, p_tenant_id;
    RETURN v_exists;
END;
$function$;

CREATE OR REPLACE FUNCTION public.plan_dispatch_trip_v2(p_tenant_id uuid, p_vehicle_id uuid, p_driver_id uuid, p_load_ids uuid[], p_scheduled_start timestamp with time zone DEFAULT now(), p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_trip_id uuid;
    v_load_id uuid;
BEGIN
    IF p_idempotency_key IS NOT NULL THEN
        IF EXISTS (SELECT 1 FROM public.idempotency_keys WHERE tenant_id = p_tenant_id AND key_value = p_idempotency_key) THEN
            RAISE EXCEPTION 'Duplicate request (idempotency)';
        END IF;
        INSERT INTO public.idempotency_keys (tenant_id, key_value) VALUES (p_tenant_id, p_idempotency_key);
    END IF;

    PERFORM 1 FROM public.loads WHERE id = ANY(p_load_ids) AND tenant_id = p_tenant_id FOR UPDATE;

    IF EXISTS (SELECT 1 FROM public.loads WHERE id = ANY(p_load_ids) AND status NOT IN ('assembling', 'ready')) THEN
        RAISE EXCEPTION 'One or more loads are not in valid status for dispatch';
    END IF;

    INSERT INTO public.dispatch_trips (
        tenant_id, vehicle_id, driver_id, status, scheduled_start_at
    ) VALUES (
        p_tenant_id, p_vehicle_id, p_driver_id, 'planned', p_scheduled_start
    ) RETURNING id INTO v_trip_id;

    FOREACH v_load_id IN ARRAY p_load_ids
    LOOP
        INSERT INTO public.dispatch_trip_loads (tenant_id, dispatch_trip_id, load_id)
        VALUES (p_tenant_id, v_trip_id, v_load_id);
        
        UPDATE public.loads SET status = 'ready', trip_id = v_trip_id 
        WHERE id = v_load_id AND tenant_id = p_tenant_id;
    END LOOP;

    INSERT INTO public.entity_state_audit_log (
        tenant_id, entity_type, entity_id, to_status, idempotency_key
    ) VALUES (
        p_tenant_id, 'trip', v_trip_id, 'planned', p_idempotency_key
    );

    RETURN v_trip_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.recalculate_load_totals(p_tenant_id uuid, p_load_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    UPDATE public.loads
    SET 
        total_weight_kg = COALESCE((SELECT SUM(weight_kg) FROM public.load_items WHERE load_id = p_load_id AND tenant_id = p_tenant_id), 0),
        total_volume_m3 = COALESCE((SELECT SUM(volume_m3) FROM public.load_items WHERE load_id = p_load_id AND tenant_id = p_tenant_id), 0),
        total_pallet_count = COALESCE((SELECT SUM(pallet_count) FROM public.load_items WHERE load_id = p_load_id AND tenant_id = p_tenant_id), 0)
    WHERE id = p_load_id AND tenant_id = p_tenant_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_load_item_v1(p_tenant_id uuid, p_load_id uuid, p_item_id uuid DEFAULT NULL::uuid, p_item_description text DEFAULT ''::text, p_quantity numeric DEFAULT 0, p_pallet_count numeric DEFAULT 0, p_weight_kg numeric DEFAULT 0, p_volume_m3 numeric DEFAULT 0, p_fiscal_document_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_item_id uuid;
BEGIN
    -- Ownership check for load
    IF NOT EXISTS (SELECT 1 FROM public.loads WHERE id = p_load_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'Load does not belong to tenant';
    END IF;

    -- Upsert logic
    IF p_item_id IS NULL THEN
        INSERT INTO public.load_items (
            tenant_id, load_id, item_description, quantity, pallet_count, weight_kg, volume_m3, fiscal_document_id
        ) VALUES (
            p_tenant_id, p_load_id, p_item_description, p_quantity, p_pallet_count, p_weight_kg, p_volume_m3, p_fiscal_document_id
        ) RETURNING id INTO v_item_id;
    ELSE
        -- Ownership check for item
        IF NOT EXISTS (SELECT 1 FROM public.load_items WHERE id = p_item_id AND tenant_id = p_tenant_id) THEN
            RAISE EXCEPTION 'Item does not belong to tenant';
        END IF;

        UPDATE public.load_items SET
            item_description = p_item_description,
            quantity = p_quantity,
            pallet_count = p_pallet_count,
            weight_kg = p_weight_kg,
            volume_m3 = p_volume_m3,
            fiscal_document_id = p_fiscal_document_id,
            updated_at = now()
        WHERE id = p_item_id AND tenant_id = p_tenant_id
        RETURNING id INTO v_item_id;
    END IF;

    -- Recalculate totals
    PERFORM public.recalculate_load_totals(p_tenant_id, p_load_id);

    RETURN v_item_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.delete_load_item_v1(p_tenant_id uuid, p_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_load_id uuid;
BEGIN
    -- Get load_id and check ownership
    SELECT load_id INTO v_load_id FROM public.load_items WHERE id = p_item_id AND tenant_id = p_tenant_id;
    
    IF v_load_id IS NULL THEN
        RAISE EXCEPTION 'Item not found or does not belong to tenant';
    END IF;

    DELETE FROM public.load_items WHERE id = p_item_id AND tenant_id = p_tenant_id;

    -- Recalculate totals
    PERFORM public.recalculate_load_totals(p_tenant_id, v_load_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.list_load_control_v1(p_tenant_id uuid, p_filters jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(items jsonb, total_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_search text := p_filters->>'search';
    v_payment_status text[] := ARRAY(SELECT jsonb_array_elements_text(p_filters->'paymentStatus'));
    v_load_number text := p_filters->>'loadNumber';
    v_date_from date := (p_filters->>'loadDateFrom')::date;
    v_date_to date := (p_filters->>'loadDateTo')::date;
BEGIN
    RETURN QUERY
    WITH filtered_loads AS (
        SELECT * FROM public.vw_load_control
        WHERE tenant_id = p_tenant_id
        AND (v_search IS NULL OR load_number ILIKE '%' || v_search || '%' OR external_load_number ILIKE '%' || v_search || '%' OR driver_name ILIKE '%' || v_search || '%')
        AND (v_load_number IS NULL OR load_number = v_load_number OR external_load_number = v_load_number)
        AND (cardinality(v_payment_status) = 0 OR payment_status = ANY(v_payment_status))
        AND (v_date_from IS NULL OR load_date >= v_date_from)
        AND (v_date_to IS NULL OR load_date <= v_date_to)
    )
    SELECT 
        (SELECT jsonb_agg(fl) FROM (SELECT * FROM filtered_loads ORDER BY created_at DESC LIMIT p_limit OFFSET p_offset) fl) as items,
        (SELECT count(*) FROM filtered_loads) as total_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.commit_load_import_v1(p_tenant_id uuid, p_file_name text, p_source_type text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_batch_id uuid;
    v_row jsonb;
    v_load_id uuid;
    v_imported_count integer := 0;
    v_duplicated_count integer := 0;
    v_error_count integer := 0;
    v_errors text[] := ARRAY[]::text[];
BEGIN
    INSERT INTO public.load_import_batches (tenant_id, file_name, source_type, status)
    VALUES (p_tenant_id, p_file_name, p_source_type, 'processing')
    RETURNING id INTO v_batch_id;

    FOR v_row IN SELECT * FROM jsonb_array_elements(p_rows)
    LOOP
        BEGIN
            -- Logic to match/upsert load
            SELECT id INTO v_load_id 
            FROM public.loads 
            WHERE tenant_id = p_tenant_id 
            AND (external_load_number = v_row->>'external_load_number');

            IF v_load_id IS NULL THEN
                INSERT INTO public.loads (
                    tenant_id, 
                    load_number, 
                    external_load_number, 
                    load_date, 
                    arrival_date,
                    gross_cargo_value, 
                    freight_amount, 
                    payment_status,
                    legacy_status_text,
                    expected_payment_date,
                    last_import_batch_id,
                    status
                ) VALUES (
                    p_tenant_id, 
                    COALESCE(v_row->>'load_number', (SELECT COALESCE(MAX(load_number::int), 1000) + 1 FROM public.loads WHERE tenant_id = p_tenant_id)::text),
                    v_row->>'external_load_number',
                    (v_row->>'load_date')::date,
                    (v_row->>'arrival_date')::date,
                    (v_row->>'gross_cargo_value')::numeric,
                    (v_row->>'freight_amount')::numeric,
                    'unpaid',
                    v_row->>'legacy_status_text',
                    (v_row->>'expected_payment_date')::date,
                    v_batch_id,
                    'assembling'
                ) RETURNING id INTO v_load_id;
                v_imported_count := v_imported_count + 1;
            ELSE
                UPDATE public.loads SET
                    load_date = COALESCE((v_row->>'load_date')::date, load_date),
                    arrival_date = COALESCE((v_row->>'arrival_date')::date, arrival_date),
                    gross_cargo_value = COALESCE((v_row->>'gross_cargo_value')::numeric, gross_cargo_value),
                    freight_amount = COALESCE((v_row->>'freight_amount')::numeric, freight_amount),
                    legacy_status_text = COALESCE(v_row->>'legacy_status_text', legacy_status_text),
                    expected_payment_date = COALESCE((v_row->>'expected_payment_date')::date, expected_payment_date),
                    last_import_batch_id = v_batch_id
                WHERE id = v_load_id;
                v_duplicated_count := v_duplicated_count + 1;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_error_count := v_error_count + 1;
            v_errors := array_append(v_errors, SQLERRM);
        END;
    END LOOP;

    UPDATE public.load_import_batches SET
        status = 'completed',
        imported_count = v_imported_count,
        duplicated_count = v_duplicated_count,
        error_count = v_error_count
    WHERE id = v_batch_id;

    RETURN jsonb_build_object(
        'batch_id', v_batch_id,
        'newLoads', v_imported_count,
        'updatedLoads', v_duplicated_count,
        'errors', v_errors
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_employee_v1(p_tenant_id uuid, p_values jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_employee_id uuid;
    v_manager_id uuid;
BEGIN
    IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
        RAISE EXCEPTION 'Acesso negado';
    END IF;

    v_manager_id := (p_values->>'manager_id')::uuid;
    IF v_manager_id IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM public.employees WHERE id = v_manager_id AND tenant_id = p_tenant_id) THEN
            RAISE EXCEPTION 'Gestor não pertence ao mesmo tenant';
        END IF;
    END IF;

    INSERT INTO public.employees (
        tenant_id,
        name,
        doc_cpf,
        doc_rg,
        role_title,
        department,
        branch,
        manager_id,
        cost_center,
        hire_date,
        termination_date,
        status,
        phone,
        email,
        cnh_number,
        cnh_category,
        cnh_expiry,
        medical_exam_expiry,
        driver_id,
        user_id,
        notes,
        version
    ) VALUES (
        p_tenant_id,
        p_values->>'name',
        p_values->>'doc_cpf',
        p_values->>'doc_rg',
        p_values->>'role_title',
        p_values->>'department',
        p_values->>'branch',
        v_manager_id,
        p_values->>'cost_center',
        (p_values->>'hire_date')::date,
        (p_values->>'termination_date')::date,
        COALESCE(p_values->>'status', 'active')::text,
        p_values->>'phone',
        p_values->>'email',
        p_values->>'cnh_number',
        p_values->>'cnh_category',
        (p_values->>'cnh_expiry')::date,
        (p_values->>'medical_exam_expiry')::date,
        (p_values->>'driver_id')::uuid,
        (p_values->>'user_id')::uuid,
        p_values->>'notes',
        1
    ) RETURNING id INTO v_employee_id;

    INSERT INTO public.entity_state_audit_log (
        tenant_id, entity_type, entity_id, to_status, metadata
    ) VALUES (
        p_tenant_id, 'employee', v_employee_id, COALESCE(p_values->>'status', 'active'), 
        jsonb_build_object('action', 'create')
    );

    RETURN v_employee_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_employee_v1(p_tenant_id uuid, p_employee_id uuid, p_values jsonb, p_expected_version integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_old_data jsonb;
    v_new_data jsonb;
    v_operator_id uuid;
    v_allowed_keys text[] := ARRAY[
        'name', 'doc_cpf', 'doc_rg', 'role_title', 'department', 
        'branch', 'manager_id', 'cost_center', 'hire_date', 
        'termination_date', 'status', 'phone', 'email', 
        'cnh_number', 'cnh_category', 'cnh_expiry', 
        'medical_exam_expiry', 'driver_id', 'user_id', 'notes'
    ];
    v_key text;
    v_manager_tenant_id uuid;
    v_driver_tenant_id uuid;
BEGIN
    -- 1. Autorização
    v_operator_id := auth.uid();
    IF NOT EXISTS (
        SELECT 1 FROM public.user_roles
        WHERE user_id = v_operator_id 
          AND (role = 'admin' OR role = 'moderator')
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Operator permissions required' USING ERRCODE = '42501';
    END IF;

    -- 2. Lock e Bloqueio Otimista (Obrigatório)
    IF p_expected_version IS NULL THEN
        RAISE EXCEPTION 'p_expected_version is required for optimistic locking' USING ERRCODE = 'P0004';
    END IF;

    SELECT to_jsonb(e.*) INTO v_old_data
    FROM public.employees e
    WHERE e.id = p_employee_id 
      AND e.tenant_id = p_tenant_id
    FOR UPDATE;

    IF v_old_data IS NULL THEN
        RAISE EXCEPTION 'Employee not found or access denied' USING ERRCODE = 'P0002';
    END IF;

    IF (v_old_data->>'version')::int != p_expected_version THEN
        RAISE EXCEPTION 'Conflict: Employee was modified by another user (expected version %, found %)', 
            p_expected_version, (v_old_data->>'version')::int
            USING ERRCODE = 'P0001';
    END IF;

    -- 3. Validação de Chaves
    FOR v_key IN SELECT jsonb_object_keys(p_values) LOOP
        IF NOT v_key = ANY(v_allowed_keys) THEN
            RAISE EXCEPTION 'Invalid field: %', v_key USING ERRCODE = '42703';
        END IF;
    END LOOP;

    -- 4. Validação Cross-Tenant
    IF p_values ? 'manager_id' AND (p_values->>'manager_id') IS NOT NULL THEN
        SELECT tenant_id INTO v_manager_tenant_id FROM public.employees WHERE id = (p_values->>'manager_id')::uuid;
        IF v_manager_tenant_id IS DISTINCT FROM p_tenant_id THEN
            RAISE EXCEPTION 'Cross-tenant violation: Manager belongs to another tenant' USING ERRCODE = '42501';
        END IF;
    END IF;

    IF p_values ? 'driver_id' AND (p_values->>'driver_id') IS NOT NULL THEN
        SELECT tenant_id INTO v_driver_tenant_id FROM public.drivers WHERE id = (p_values->>'driver_id')::uuid;
        IF v_driver_tenant_id IS DISTINCT FROM p_tenant_id THEN
            RAISE EXCEPTION 'Cross-tenant violation: Driver belongs to another tenant' USING ERRCODE = '42501';
        END IF;
    END IF;

    -- 5. Update Dinâmico
    UPDATE public.employees
    SET
        name = CASE WHEN p_values ? 'name' THEN (p_values->>'name') ELSE name END,
        doc_cpf = CASE WHEN p_values ? 'doc_cpf' THEN (p_values->>'doc_cpf') ELSE doc_cpf END,
        doc_rg = CASE WHEN p_values ? 'doc_rg' THEN (p_values->>'doc_rg') ELSE doc_rg END,
        role_title = CASE WHEN p_values ? 'role_title' THEN (p_values->>'role_title') ELSE role_title END,
        department = CASE WHEN p_values ? 'department' THEN (p_values->>'department') ELSE department END,
        branch = CASE WHEN p_values ? 'branch' THEN (p_values->>'branch') ELSE branch END,
        manager_id = CASE WHEN p_values ? 'manager_id' THEN (p_values->>'manager_id')::uuid ELSE manager_id END,
        cost_center = CASE WHEN p_values ? 'cost_center' THEN (p_values->>'cost_center') ELSE cost_center END,
        hire_date = CASE WHEN p_values ? 'hire_date' THEN (p_values->>'hire_date')::date ELSE hire_date END,
        termination_date = CASE WHEN p_values ? 'termination_date' THEN (p_values->>'termination_date')::date ELSE termination_date END,
        status = CASE WHEN p_values ? 'status' THEN (p_values->>'status')::app_employee_status ELSE status END,
        phone = CASE WHEN p_values ? 'phone' THEN (p_values->>'phone') ELSE phone END,
        email = CASE WHEN p_values ? 'email' THEN (p_values->>'email') ELSE email END,
        cnh_number = CASE WHEN p_values ? 'cnh_number' THEN (p_values->>'cnh_number') ELSE cnh_number END,
        cnh_category = CASE WHEN p_values ? 'cnh_category' THEN (p_values->>'cnh_category') ELSE cnh_category END,
        cnh_expiry = CASE WHEN p_values ? 'cnh_expiry' THEN (p_values->>'cnh_expiry')::date ELSE cnh_expiry END,
        medical_exam_expiry = CASE WHEN p_values ? 'medical_exam_expiry' THEN (p_values->>'medical_exam_expiry')::date ELSE medical_exam_expiry END,
        driver_id = CASE WHEN p_values ? 'driver_id' THEN (p_values->>'driver_id')::uuid ELSE driver_id END,
        user_id = CASE WHEN p_values ? 'user_id' THEN (p_values->>'user_id')::uuid ELSE user_id END,
        notes = CASE WHEN p_values ? 'notes' THEN (p_values->>'notes') ELSE notes END,
        version = version + 1,
        updated_at = now()
    WHERE id = p_employee_id AND tenant_id = p_tenant_id;

    -- 6. Auditoria ( vehicle_events como ledger de auditoria )
    SELECT to_jsonb(e.*) INTO v_new_data FROM public.employees e WHERE e.id = p_employee_id;
    
    INSERT INTO public.vehicle_events (
        tenant_id,
        event_type,
        payload,
        created_by
    ) VALUES (
        p_tenant_id,
        'employee_updated',
        jsonb_build_object(
            'employee_id', p_employee_id,
            'before', v_old_data,
            'after', v_new_data,
            'changed_fields', p_values
        ),
        v_operator_id
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.delete_employee_v1(p_tenant_id uuid, p_employee_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_exists boolean;
BEGIN
    IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
        RAISE EXCEPTION 'Acesso negado';
    END IF;

    SELECT EXISTS (SELECT 1 FROM public.employees WHERE id = p_employee_id AND tenant_id = p_tenant_id)
    INTO v_exists;

    IF NOT v_exists THEN
        RAISE EXCEPTION 'Funcionário não encontrado ou não pertence ao tenant';
    END IF;

    DELETE FROM public.employees WHERE id = p_employee_id AND tenant_id = p_tenant_id;

    INSERT INTO public.entity_state_audit_log (
        tenant_id, entity_type, entity_id, to_status, metadata
    ) VALUES (
        p_tenant_id, 'employee', p_employee_id, 'deleted', 
        jsonb_build_object('action', 'delete')
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.plan_dispatch_trip_v3(p_tenant_id uuid, p_idempotency_key text, p_driver_id uuid, p_vehicle_id uuid, p_route_name text, p_load_ids uuid[], p_stops jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operator_id uuid := auth.uid();
    v_payload_hash text;
    v_existing_result_id uuid;
    v_trip_id uuid;
    v_stop record;
    v_stop_id uuid;
    v_doc_id uuid;
    v_load_id uuid;
    v_found_count int;
BEGIN
    -- 1. Authorization: Require operator/admin linked to tenant
    IF NOT EXISTS (
        SELECT 1 FROM public.tenant_memberships
        WHERE user_id = v_operator_id 
          AND tenant_id = p_tenant_id
          AND role IN ('owner', 'admin', 'operator')
    ) THEN
        RAISE EXCEPTION 'Unauthorized: User is not an operator for this tenant';
    END IF;

    -- 2. Idempotency Check
    v_payload_hash := md5(jsonb_build_object(
        'driver_id', p_driver_id,
        'vehicle_id', p_vehicle_id,
        'route_name', p_route_name,
        'load_ids', p_load_ids,
        'stops', p_stops
    )::text);

    SELECT result_id INTO v_existing_result_id
    FROM public.idempotency_keys
    WHERE tenant_id = p_tenant_id 
      AND operation = 'plan_dispatch_trip'
      AND idempotency_key = p_idempotency_key;

    IF FOUND THEN
        IF EXISTS (
            SELECT 1 FROM public.idempotency_keys
            WHERE tenant_id = p_tenant_id 
              AND operation = 'plan_dispatch_trip'
              AND idempotency_key = p_idempotency_key
              AND payload_hash = v_payload_hash
        ) THEN
            RETURN v_existing_result_id;
        ELSE
            RAISE EXCEPTION 'Idempotency key mismatch: Same key used with different payload';
        END IF;
    END IF;

    -- 3. Locking & Validation
    -- Lock loads and check ownership/quantity
    SELECT count(*) INTO v_found_count
    FROM public.loads
    WHERE id = ANY(p_load_ids) 
      AND tenant_id = p_tenant_id
    FOR UPDATE;

    IF v_found_count != array_length(p_load_ids, 1) THEN
        RAISE EXCEPTION 'Ownership mismatch: One or more loads not found or belong to another tenant';
    END IF;

    -- Validate Vehicle & Driver
    IF NOT EXISTS (SELECT 1 FROM public.vehicles WHERE id = p_vehicle_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'Invalid vehicle for tenant';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.drivers WHERE id = p_driver_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'Invalid driver for tenant';
    END IF;

    -- 4. Create Trip
    INSERT INTO public.dispatch_trips (
        tenant_id, driver_id, vehicle_id, route_name, status, planned_start_at
    ) VALUES (
        p_tenant_id, p_driver_id, p_vehicle_id, p_route_name, 'planned', now()
    ) RETURNING id INTO v_trip_id;

    -- 5. Link Cargas (dispatch_trip_loads)
    FOREACH v_load_id IN ARRAY p_load_ids
    LOOP
        INSERT INTO public.dispatch_trip_loads (tenant_id, dispatch_trip_id, load_id)
        VALUES (p_tenant_id, v_trip_id, v_load_id);
        
        -- Update load status and link
        UPDATE public.loads 
        SET status = 'ready', 
            trip_id = v_trip_id,
            updated_at = now()
        WHERE id = v_load_id AND tenant_id = p_tenant_id;
    END LOOP;

    -- 6. Create Paradas e Vincular Documentos
    FOR v_stop IN SELECT * FROM jsonb_to_recordset(p_stops) AS x(destination text, client_id uuid, stop_order int, fiscal_document_ids uuid[])
    LOOP
        -- Stop ownership check (client_id)
        IF v_stop.client_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.clients WHERE id = v_stop.client_id AND tenant_id = p_tenant_id) THEN
            RAISE EXCEPTION 'Invalid client for tenant at stop %', v_stop.stop_order;
        END IF;

        INSERT INTO public.dispatch_stops (
            tenant_id, dispatch_trip_id, destination, client_id, stop_order, status
        ) VALUES (
            p_tenant_id, v_trip_id, v_stop.destination, v_stop.client_id, v_stop.stop_order, 'pending'
        ) RETURNING id INTO v_stop_id;

        IF v_stop.fiscal_document_ids IS NOT NULL THEN
            FOREACH v_doc_id IN ARRAY v_stop.fiscal_document_ids
            LOOP
                -- Document ownership check
                IF NOT EXISTS (SELECT 1 FROM public.fiscal_documents WHERE id = v_doc_id AND tenant_id = p_tenant_id) THEN
                    RAISE EXCEPTION 'Invalid document for tenant at stop %', v_stop.stop_order;
                END IF;

                INSERT INTO public.dispatch_stop_documents (
                    tenant_id, dispatch_stop_id, fiscal_document_id, status
                ) VALUES (
                    p_tenant_id, v_stop_id, v_doc_id, 'pending'
                );
            END LOOP;
        END IF;
    END LOOP;

    -- 7. Record Idempotency
    INSERT INTO public.idempotency_keys (
        tenant_id, operation, idempotency_key, payload_hash, result_id
    ) VALUES (
        p_tenant_id, 'plan_dispatch_trip', p_idempotency_key, v_payload_hash, v_trip_id
    );

    -- 8. Audit Log
    INSERT INTO public.entity_state_audit_log (
        tenant_id, entity_type, entity_id, to_status, idempotency_key
    ) VALUES (
        p_tenant_id, 'trip', v_trip_id, 'planned', p_idempotency_key
    );

    RETURN v_trip_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_load_item_v2(p_tenant_id uuid, p_load_id uuid, p_item_id uuid DEFAULT NULL::uuid, p_item_description text DEFAULT NULL::text, p_quantity numeric DEFAULT 0, p_pallet_count numeric DEFAULT 0, p_weight_kg numeric DEFAULT 0, p_volume_m3 numeric DEFAULT 0, p_fiscal_document_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operator_id uuid := auth.uid();
    v_actual_item_id uuid := p_item_id;
    v_old_load_id uuid;
BEGIN
    -- 1. Authorization
    IF NOT EXISTS (
        SELECT 1 FROM public.tenant_memberships
        WHERE user_id = v_operator_id 
          AND tenant_id = p_tenant_id
          AND role IN ('owner', 'admin', 'operator')
    ) THEN
        RAISE EXCEPTION 'Unauthorized: User is not an operator for this tenant';
    END IF;

    -- 2. Validate Load Ownership
    IF NOT EXISTS (
        SELECT 1 FROM public.loads 
        WHERE id = p_load_id AND tenant_id = p_tenant_id
    ) THEN
        RAISE EXCEPTION 'Invalid load for tenant';
    END IF;

    -- 3. Validate Fiscal Document (if provided)
    IF p_fiscal_document_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.fiscal_documents
            WHERE id = p_fiscal_document_id AND tenant_id = p_tenant_id
        ) THEN
            RAISE EXCEPTION 'Invalid fiscal document for tenant';
        END IF;
    END IF;

    -- 4. Upsert with atomic ownership validation
    IF v_actual_item_id IS NOT NULL THEN
        -- Update Case: Validate id, tenant, and original load (atomic lock)
        UPDATE public.load_items
        SET 
            item_description = COALESCE(p_item_description, item_description),
            quantity = p_quantity,
            pallet_count = p_pallet_count,
            weight_kg = p_weight_kg,
            volume_m3 = p_volume_m3,
            fiscal_document_id = p_fiscal_document_id,
            updated_at = now()
        WHERE id = v_actual_item_id 
          AND tenant_id = p_tenant_id 
          AND load_id = p_load_id
        RETURNING load_id INTO v_old_load_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Load item not found or does not belong to the specified load/tenant';
        END IF;
    ELSE
        -- Insert Case
        INSERT INTO public.load_items (
            tenant_id,
            load_id,
            item_description,
            quantity,
            pallet_count,
            weight_kg,
            volume_m3,
            fiscal_document_id
        ) VALUES (
            p_tenant_id,
            p_load_id,
            p_item_description,
            p_quantity,
            p_pallet_count,
            p_weight_kg,
            p_volume_m3,
            p_fiscal_document_id
        ) RETURNING id INTO v_actual_item_id;
    END IF;

    -- 5. Atomic Mirroring to fiscal_documents
    -- load_items is SoT, fiscal_documents.load_id is the mirror
    IF p_fiscal_document_id IS NOT NULL THEN
        UPDATE public.fiscal_documents
        SET load_id = p_load_id
        WHERE id = p_fiscal_document_id 
          AND tenant_id = p_tenant_id;
    END IF;

    -- 6. Recalculate Totals (Atomic internally)
    PERFORM public.recalculate_load_totals(p_tenant_id, p_load_id);

    RETURN v_actual_item_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.delete_load_item_v2(p_tenant_id uuid, p_item_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operator_id uuid := auth.uid();
    v_load_id uuid;
    v_fiscal_document_id uuid;
BEGIN
    -- 1. Authorization
    IF NOT EXISTS (
        SELECT 1 FROM public.tenant_memberships
        WHERE user_id = v_operator_id 
          AND tenant_id = p_tenant_id
          AND role IN ('owner', 'admin', 'operator')
    ) THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    -- 2. Find and Lock item (atomic ownership check)
    DELETE FROM public.load_items
    WHERE id = p_item_id AND tenant_id = p_tenant_id
    RETURNING load_id, fiscal_document_id INTO v_load_id, v_fiscal_document_id;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    -- 3. Update mirror (remove load link from doc)
    IF v_fiscal_document_id IS NOT NULL THEN
        UPDATE public.fiscal_documents
        SET load_id = NULL
        WHERE id = v_fiscal_document_id AND tenant_id = p_tenant_id;
    END IF;

    -- 4. Recalculate Totals
    PERFORM public.recalculate_load_totals(p_tenant_id, v_load_id);

    RETURN TRUE;
END;
$function$;

CREATE OR REPLACE FUNCTION public.process_overspeed_alerts(_tenant_id uuid, _vehicle_id uuid, _speed numeric, _captured_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _rule RECORD;
  _limit numeric;
BEGIN
  -- Find enabled overspeed rule for this tenant
  SELECT * INTO _rule 
  FROM public.alert_rules 
  WHERE tenant_id = _tenant_id 
    AND rule_type = 'overspeed' 
    AND enabled = true 
  LIMIT 1;

  IF NOT FOUND THEN RETURN; END IF;

  _limit := (_rule.params->>'speed_limit')::numeric;
  
  IF _speed > _limit THEN
    -- Create event
    INSERT INTO public.events (tenant_id, vehicle_id, event_type, event_at, severity, payload)
    VALUES (_tenant_id, _vehicle_id, 'overspeed', _captured_at, 'warning', 
            jsonb_build_object('speed', _speed, 'limit', _limit));
            
    -- Open/Update alert instance
    INSERT INTO public.alert_instances (tenant_id, rule_id, vehicle_id, status, opened_at)
    VALUES (_tenant_id, _rule.id, _vehicle_id, 'open', _captured_at)
    ON CONFLICT (tenant_id, rule_id, vehicle_id) WHERE status = 'open'
    DO UPDATE SET opened_at = LEAST(alert_instances.opened_at, EXCLUDED.opened_at);
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.process_geofence_alerts(_tenant_id uuid, _vehicle_id uuid, _lat double precision, _lng double precision, _captured_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _point extensions.geometry;
  _fence RECORD;
  _is_inside boolean;
  _was_inside boolean;
BEGIN
  _point := extensions.ST_SetSRID(extensions.ST_Point(_lng, _lat), 4326);

  FOR _fence IN 
    SELECT * FROM public.geofences 
    WHERE tenant_id = _tenant_id AND enabled = true 
  LOOP
    _is_inside := extensions.ST_Within(_point, _fence.geometry);
    
    -- Check previous state from geofence_events
    SELECT (event_type = 'entry') INTO _was_inside
    FROM public.geofence_events
    WHERE tenant_id = _tenant_id 
      AND vehicle_id = _vehicle_id 
      AND geofence_id = _fence.id
    ORDER BY event_at DESC
    LIMIT 1;
    
    _was_inside := COALESCE(_was_inside, false);

    IF _is_inside AND NOT _was_inside THEN
      -- Entry Event
      INSERT INTO public.geofence_events (tenant_id, geofence_id, vehicle_id, event_type, event_at, lat, lng)
      VALUES (_tenant_id, _fence.id, _vehicle_id, 'entry', _captured_at, _lat, _lng);
      
      INSERT INTO public.events (tenant_id, vehicle_id, event_type, event_at, severity, payload)
      VALUES (_tenant_id, _vehicle_id, 'geofence_entry', _captured_at, 'info', 
              jsonb_build_object('geofence_id', _fence.id, 'name', _fence.name));
              
    ELSIF NOT _is_inside AND _was_inside THEN
      -- Exit Event
      INSERT INTO public.geofence_events (tenant_id, geofence_id, vehicle_id, event_type, event_at, lat, lng)
      VALUES (_tenant_id, _fence.id, _vehicle_id, 'exit', _captured_at, _lat, _lng);
      
      INSERT INTO public.events (tenant_id, vehicle_id, event_type, event_at, severity, payload)
      VALUES (_tenant_id, _vehicle_id, 'geofence_exit', _captured_at, 'info', 
              jsonb_build_object('geofence_id', _fence.id, 'name', _fence.name));
    END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.calculate_vehicle_trips_v1(_vehicle_id uuid, _start_at timestamp with time zone, _end_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _trip_count int := 0;
  _tenant_id uuid;
BEGIN
  SELECT tenant_id INTO _tenant_id FROM public.vehicles WHERE id = _vehicle_id;
  
  SELECT count(*) INTO _trip_count FROM public.trips WHERE vehicle_id = _vehicle_id AND start_at >= _start_at;
  
  RETURN jsonb_build_object('trips_analyzed', _trip_count, 'period_start', _start_at, 'period_end', _end_at);
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_load_v1(p_tenant_id uuid, p_load_id uuid, p_changes jsonb, p_expected_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_allowed text[] := ARRAY[
    'vehicle_id','driver_id','origin','destination','notes','operation_type',
    'scheduled_load_at','actual_load_at','load_date','arrival_date','arrival_at',
    'estimated_arrival_at','gate_departure_at','trailer_plate','os_number',
    'external_load_number','control_load_number','supplier_manifest',
    'distribution_manifest','shipment_manifest','origin_manifest',
    'merchandise_value','freight_amount','freight_percent','payment_method',
    'expected_payment_date','payment_date','monitored','dedicated_vehicle',
    'monitor_responsible','driver_type','sm_manager','sm_release',
    'cash_to_receive','pix_to_receive','ciot','status','operational_status'
  ];
  v_key text;
  v_before public.loads;
  v_after public.loads;
  v_sets text[] := '{}';
  v_sql text;
BEGIN
  IF p_tenant_id IS NULL OR p_load_id IS NULL THEN
    RAISE EXCEPTION 'INVALID_ARGUMENTS';
  END IF;
  IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;
  IF p_changes IS NULL OR jsonb_typeof(p_changes) <> 'object' OR p_changes = '{}'::jsonb THEN
    RAISE EXCEPTION 'NO_CHANGES';
  END IF;

  SELECT * INTO v_before FROM public.loads
   WHERE id = p_load_id AND tenant_id = p_tenant_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LOAD_NOT_FOUND';
  END IF;

  IF p_expected_version IS NOT NULL AND v_before.version <> p_expected_version THEN
    RAISE EXCEPTION 'VERSION_CONFLICT: expected %, found %', p_expected_version, v_before.version;
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(p_changes) LOOP
    IF NOT (v_key = ANY(v_allowed)) THEN
      RAISE EXCEPTION 'FIELD_NOT_ALLOWED: %', v_key;
    END IF;
    v_sets := v_sets || format(
      '%I = ($1->>%L)::text::%s',
      v_key, v_key,
      (SELECT format_type(a.atttypid, a.atttypmod)
         FROM pg_attribute a
        WHERE a.attrelid = 'public.loads'::regclass
          AND a.attname = v_key AND a.attnum > 0 AND NOT a.attisdropped)
    );
  END LOOP;

  v_sql := format(
    'UPDATE public.loads SET %s, version = version + 1, updated_at = now() WHERE id = %L AND tenant_id = %L RETURNING *',
    array_to_string(v_sets, ', '), p_load_id, p_tenant_id
  );
  EXECUTE v_sql INTO v_after USING p_changes;

  INSERT INTO public.entity_state_audit_log
    (tenant_id, entity_type, entity_id, from_status, to_status, actor_id, reason, metadata)
  VALUES (
    p_tenant_id, 'load', p_load_id, v_before.status, v_after.status, auth.uid(),
    'update_load_v1',
    jsonb_build_object(
      'changes', p_changes,
      'expected_version', p_expected_version,
      'from_version', v_before.version,
      'to_version', v_after.version
    )
  );

  RETURN jsonb_build_object('id', v_after.id, 'version', v_after.version, 'status', v_after.status);
END
$function$;

CREATE OR REPLACE FUNCTION public.delete_load_v1(p_tenant_id uuid, p_load_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_load public.loads;
  v_active_trip boolean;
BEGIN
  IF p_tenant_id IS NULL OR p_load_id IS NULL THEN
    RAISE EXCEPTION 'INVALID_ARGUMENTS';
  END IF;
  IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;

  SELECT * INTO v_load FROM public.loads
   WHERE id = p_load_id AND tenant_id = p_tenant_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LOAD_NOT_FOUND';
  END IF;

  IF lower(coalesce(v_load.status,'')) IN ('delivered','entregue','in_transit','finished','completed')
     OR lower(coalesce(v_load.operational_status,'')) IN ('delivered','entregue') THEN
    RAISE EXCEPTION 'LOAD_NOT_DELETABLE_STATUS: %', v_load.status;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.dispatch_trip_loads dtl
      JOIN public.dispatch_trips dt ON dt.id = dtl.trip_id
     WHERE dtl.load_id = p_load_id
       AND dt.tenant_id = p_tenant_id
       AND lower(coalesce(dt.status,'')) NOT IN ('cancelled','canceled','draft')
  ) INTO v_active_trip;

  IF v_active_trip OR v_load.trip_id IS NOT NULL THEN
    RAISE EXCEPTION 'LOAD_IN_ACTIVE_TRIP';
  END IF;

  INSERT INTO public.entity_state_audit_log
    (tenant_id, entity_type, entity_id, from_status, to_status, actor_id, reason, metadata)
  VALUES (
    p_tenant_id, 'load', p_load_id, v_load.status, 'deleted', auth.uid(),
    'delete_load_v1',
    jsonb_build_object('load_number', v_load.load_number, 'version', v_load.version)
  );

  DELETE FROM public.loads WHERE id = p_load_id AND tenant_id = p_tenant_id;

  RETURN jsonb_build_object('id', p_load_id, 'deleted', true);
END
$function$;

CREATE OR REPLACE FUNCTION public.audit_operational_congruence_v1(p_tenant_id uuid)
 RETURNS TABLE(severity text, domain text, entity_type text, entity_id uuid, message text, metadata jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_tenant_id IS NULL THEN
    RAISE EXCEPTION 'p_tenant_id is required';
  END IF;

  IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
    RAISE EXCEPTION 'not authorized for tenant %', p_tenant_id USING ERRCODE = '42501';
  END IF;

  -- 1) load_items <-> fiscal_documents.load_id divergence
  RETURN QUERY
  SELECT 'error'::text, 'composition'::text, 'load_item'::text, li.id,
         'Item de carga referencia nota fiscal cujo load_id difere da carga do item'::text,
         jsonb_build_object('load_id', li.load_id, 'fiscal_document_id', li.fiscal_document_id,
                            'fiscal_document_load_id', fd.load_id)
  FROM public.load_items li
  JOIN public.fiscal_documents fd ON fd.id = li.fiscal_document_id
  WHERE li.tenant_id = p_tenant_id
    AND li.fiscal_document_id IS NOT NULL
    AND (fd.load_id IS DISTINCT FROM li.load_id);

  RETURN QUERY
  SELECT 'warning'::text, 'composition'::text, 'fiscal_document'::text, fd.id,
         'Nota fiscal aponta para carga sem item de carga correspondente'::text,
         jsonb_build_object('load_id', fd.load_id, 'access_key', fd.access_key)
  FROM public.fiscal_documents fd
  WHERE fd.tenant_id = p_tenant_id
    AND fd.load_id IS NOT NULL
    AND fd.deleted_at IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.load_items li
      WHERE li.load_id = fd.load_id AND li.fiscal_document_id = fd.id
    );

  -- 2) loads.trip_id <-> dispatch_trip_loads
  RETURN QUERY
  SELECT 'error'::text, 'dispatch'::text, 'load'::text, l.id,
         'Carga possui trip_id sem vínculo correspondente em dispatch_trip_loads'::text,
         jsonb_build_object('trip_id', l.trip_id, 'status', l.status)
  FROM public.loads l
  WHERE l.tenant_id = p_tenant_id
    AND l.trip_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.dispatch_trip_loads dtl
      WHERE dtl.load_id = l.id AND dtl.dispatch_trip_id = l.trip_id
    );

  RETURN QUERY
  SELECT 'warning'::text, 'dispatch'::text, 'dispatch_trip_load'::text, dtl.id,
         'Vínculo de despacho existe mas a carga não referencia esta viagem'::text,
         jsonb_build_object('load_id', dtl.load_id, 'dispatch_trip_id', dtl.dispatch_trip_id,
                            'load_trip_id', l.trip_id)
  FROM public.dispatch_trip_loads dtl
  JOIN public.loads l ON l.id = dtl.load_id
  WHERE dtl.tenant_id = p_tenant_id
    AND l.trip_id IS DISTINCT FROM dtl.dispatch_trip_id;

  -- 3) cross-tenant relations
  RETURN QUERY
  SELECT 'critical'::text, 'tenant'::text, 'load_item'::text, li.id,
         'Item de carga em tenant diferente da carga'::text,
         jsonb_build_object('load_id', li.load_id, 'item_tenant_id', li.tenant_id, 'load_tenant_id', l.tenant_id)
  FROM public.load_items li
  JOIN public.loads l ON l.id = li.load_id
  WHERE (li.tenant_id = p_tenant_id OR l.tenant_id = p_tenant_id)
    AND li.tenant_id IS DISTINCT FROM l.tenant_id;

  RETURN QUERY
  SELECT 'critical'::text, 'tenant'::text, 'load_item'::text, li.id,
         'Item de carga referencia nota fiscal de outro tenant'::text,
         jsonb_build_object('fiscal_document_id', fd.id, 'item_tenant_id', li.tenant_id, 'document_tenant_id', fd.tenant_id)
  FROM public.load_items li
  JOIN public.fiscal_documents fd ON fd.id = li.fiscal_document_id
  WHERE (li.tenant_id = p_tenant_id OR fd.tenant_id = p_tenant_id)
    AND li.tenant_id IS DISTINCT FROM fd.tenant_id;

  RETURN QUERY
  SELECT 'critical'::text, 'tenant'::text, 'dispatch_trip_load'::text, dtl.id,
         'Vínculo de despacho cruza tenants entre viagem e carga'::text,
         jsonb_build_object('dispatch_trip_id', dtl.dispatch_trip_id, 'load_id', dtl.load_id,
                            'link_tenant_id', dtl.tenant_id, 'trip_tenant_id', dt.tenant_id, 'load_tenant_id', l.tenant_id)
  FROM public.dispatch_trip_loads dtl
  JOIN public.dispatch_trips dt ON dt.id = dtl.dispatch_trip_id
  JOIN public.loads l ON l.id = dtl.load_id
  WHERE (dtl.tenant_id = p_tenant_id OR dt.tenant_id = p_tenant_id OR l.tenant_id = p_tenant_id)
    AND (dtl.tenant_id IS DISTINCT FROM dt.tenant_id OR dtl.tenant_id IS DISTINCT FROM l.tenant_id);

  RETURN QUERY
  SELECT 'critical'::text, 'tenant'::text, 'dispatch_stop'::text, ds.id,
         'Parada em tenant diferente da viagem'::text,
         jsonb_build_object('dispatch_trip_id', ds.dispatch_trip_id, 'stop_tenant_id', ds.tenant_id, 'trip_tenant_id', dt.tenant_id)
  FROM public.dispatch_stops ds
  JOIN public.dispatch_trips dt ON dt.id = ds.dispatch_trip_id
  WHERE (ds.tenant_id = p_tenant_id OR dt.tenant_id = p_tenant_id)
    AND ds.tenant_id IS DISTINCT FROM dt.tenant_id;

  -- 4) completed trips with non-terminal stops
  RETURN QUERY
  SELECT 'warning'::text, 'dispatch'::text, 'dispatch_trip'::text, dt.id,
         'Viagem concluída/cancelada possui paradas em estado não terminal'::text,
         jsonb_build_object('trip_status', dt.status, 'pending_stops', cnt.pending_stops)
  FROM public.dispatch_trips dt
  JOIN LATERAL (
    SELECT count(*)::int AS pending_stops
    FROM public.dispatch_stops ds
    WHERE ds.dispatch_trip_id = dt.id
      AND coalesce(ds.status, 'pending') NOT IN ('completed', 'delivered', 'cancelled', 'skipped', 'failed')
  ) cnt ON TRUE
  WHERE dt.tenant_id = p_tenant_id
    AND dt.status IN ('completed', 'finished', 'closed', 'cancelled')
    AND cnt.pending_stops > 0;

  -- 5) incoherent dispatch_stop_documents
  RETURN QUERY
  SELECT 'error'::text, 'dispatch'::text, 'dispatch_stop_document'::text, dsd.id,
         'Documento de parada incoerente (tenant, parada ou carga divergentes)'::text,
         jsonb_build_object('dispatch_stop_id', dsd.dispatch_stop_id, 'load_id', dsd.load_id,
                            'fiscal_document_id', dsd.fiscal_document_id,
                            'stop_tenant_id', ds.tenant_id, 'document_tenant_id', fd.tenant_id,
                            'fiscal_document_load_id', fd.load_id)
  FROM public.dispatch_stop_documents dsd
  LEFT JOIN public.dispatch_stops ds ON ds.id = dsd.dispatch_stop_id
  LEFT JOIN public.fiscal_documents fd ON fd.id = dsd.fiscal_document_id
  WHERE dsd.tenant_id = p_tenant_id
    AND (
      ds.id IS NULL
      OR fd.id IS NULL
      OR ds.tenant_id IS DISTINCT FROM dsd.tenant_id
      OR fd.tenant_id IS DISTINCT FROM dsd.tenant_id
      OR (dsd.load_id IS NOT NULL AND fd.load_id IS NOT NULL AND fd.load_id IS DISTINCT FROM dsd.load_id)
    );

  -- 6) load totals vs items
  RETURN QUERY
  SELECT 'warning'::text, 'composition'::text, 'load'::text, l.id,
         'Totais da carga divergem da soma dos itens'::text,
         jsonb_build_object('total_weight_kg', l.total_weight_kg, 'items_weight_kg', agg.weight_kg,
                            'total_volume_m3', l.total_volume_m3, 'items_volume_m3', agg.volume_m3,
                            'item_count', agg.item_count)
  FROM public.loads l
  JOIN LATERAL (
    SELECT coalesce(sum(li.weight_kg), 0)::numeric AS weight_kg,
           coalesce(sum(li.volume_m3), 0)::numeric AS volume_m3,
           count(*)::int AS item_count
    FROM public.load_items li
    WHERE li.load_id = l.id
  ) agg ON TRUE
  WHERE l.tenant_id = p_tenant_id
    AND agg.item_count > 0
    AND (
      abs(coalesce(l.total_weight_kg, 0) - agg.weight_kg) > 0.01
      OR abs(coalesce(l.total_volume_m3, 0) - agg.volume_m3) > 0.001
    );

  -- 7) duplicated access_key (not null, not deleted)
  RETURN QUERY
  SELECT 'error'::text, 'fiscal'::text, 'fiscal_document'::text, fd.id,
         'Chave de acesso duplicada entre notas fiscais ativas'::text,
         jsonb_build_object('access_key', fd.access_key, 'duplicates', d.total)
  FROM public.fiscal_documents fd
  JOIN (
    SELECT access_key, count(*)::int AS total
    FROM public.fiscal_documents
    WHERE tenant_id = p_tenant_id AND access_key IS NOT NULL AND deleted_at IS NULL
    GROUP BY access_key
    HAVING count(*) > 1
  ) d ON d.access_key = fd.access_key
  WHERE fd.tenant_id = p_tenant_id
    AND fd.access_key IS NOT NULL
    AND fd.deleted_at IS NULL;

  -- 8) public tables without RLS
  RETURN QUERY
  SELECT 'critical'::text, 'security'::text, 'table'::text, NULL::uuid,
         format('Tabela pública %s sem RLS habilitado', c.relname)::text,
         jsonb_build_object('schema', 'public', 'table', c.relname)
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'r'
    AND c.relrowsecurity = false;

  RETURN;
END;
$function$;

