-- -----------------------------------------------------------------------------
-- Primary, unique, check, and exclusion constraints
-- -----------------------------------------------------------------------------

ALTER TABLE ONLY public.alert_instances
    ADD CONSTRAINT alert_instances_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.alert_rules
    ADD CONSTRAINT alert_rules_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.asset_movements
    ADD CONSTRAINT asset_movements_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.assets
    ADD CONSTRAINT assets_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.bank_accounts
    ADD CONSTRAINT bank_accounts_pkey PRIMARY KEY (id),
    ADD CONSTRAINT bank_accounts_account_type_check CHECK (account_type = ANY (ARRAY['checking'::text, 'savings'::text, 'cash'::text, 'company_card'::text, 'pix'::text, 'other'::text]));

ALTER TABLE ONLY public.bank_reconciliation_audit
    ADD CONSTRAINT bank_reconciliation_audit_pkey PRIMARY KEY (id),
    ADD CONSTRAINT bank_reconciliation_audit_action_check CHECK (action = ANY (ARRAY['imported_statement'::text, 'auto_match_run'::text, 'match_suggested'::text, 'match_accepted'::text, 'match_rejected'::text, 'manual_match_created'::text, 'match_reversed'::text, 'transaction_ignored'::text, 'obligation_written_off'::text, 'session_closed'::text, 'session_reopened'::text]));

ALTER TABLE ONLY public.bank_reconciliation_sessions
    ADD CONSTRAINT bank_reconciliation_sessions_pkey PRIMARY KEY (id),
    ADD CONSTRAINT bank_reconciliation_sessions_status_check CHECK (status = ANY (ARRAY['open'::text, 'in_review'::text, 'closed'::text, 'reopened'::text, 'cancelled'::text]));

ALTER TABLE ONLY public.bank_statement_imports
    ADD CONSTRAINT bank_statement_imports_pkey PRIMARY KEY (id),
    ADD CONSTRAINT bank_statement_imports_status_check CHECK (status = ANY (ARRAY['draft'::text, 'imported'::text, 'reconciled'::text, 'closed'::text, 'cancelled'::text]));

ALTER TABLE ONLY public.bank_transactions
    ADD CONSTRAINT bank_transactions_pkey PRIMARY KEY (id),
    ADD CONSTRAINT bank_transactions_transaction_type_check CHECK (transaction_type = ANY (ARRAY['credit'::text, 'debit'::text])),
    ADD CONSTRAINT bank_transactions_reconciliation_status_check CHECK (reconciliation_status = ANY (ARRAY['unmatched'::text, 'suggested'::text, 'matched'::text, 'ignored'::text, 'manual_review'::text]));

ALTER TABLE ONLY public.billing_edi_export_items
    ADD CONSTRAINT billing_edi_export_items_pkey PRIMARY KEY (id),
    ADD CONSTRAINT billing_edi_export_items_status_check CHECK (status = ANY (ARRAY['included'::text, 'skipped'::text, 'error'::text, 'cancelled'::text])),
    ADD CONSTRAINT billing_edi_export_items_validation_status_check CHECK (validation_status = ANY (ARRAY['valid'::text, 'warning'::text, 'error'::text]));

ALTER TABLE ONLY public.billing_edi_exports
    ADD CONSTRAINT billing_edi_exports_pkey PRIMARY KEY (id),
    ADD CONSTRAINT billing_edi_exports_status_check CHECK (status = ANY (ARRAY['draft'::text, 'generated'::text, 'downloaded'::text, 'sent'::text, 'cancelled'::text, 'error'::text]));

ALTER TABLE ONLY public.billing_edi_profiles
    ADD CONSTRAINT billing_edi_profiles_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.checklist_executions
    ADD CONSTRAINT checklist_executions_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.client_invoice_charges
    ADD CONSTRAINT client_invoice_charges_pkey PRIMARY KEY (id),
    ADD CONSTRAINT client_invoice_charges_source_type_check CHECK (source_type = ANY (ARRAY['cte_document'::text, 'nfse_document'::text, 'manual_service'::text]));

ALTER TABLE ONLY public.client_invoice_details
    ADD CONSTRAINT client_invoice_details_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.client_invoice_sequences
    ADD CONSTRAINT client_invoice_sequences_pkey PRIMARY KEY (tenant_id, sequence_year);

ALTER TABLE ONLY public.client_invoices
    ADD CONSTRAINT client_invoices_pkey PRIMARY KEY (id),
    ADD CONSTRAINT client_invoices_status_check CHECK (status = ANY (ARRAY['draft'::text, 'generated'::text, 'sent'::text, 'paid'::text, 'cancelled'::text])),
    ADD CONSTRAINT client_invoices_edi_status_check CHECK (edi_status = ANY (ARRAY['not_generated'::text, 'generated'::text, 'downloaded'::text, 'sent'::text, 'error'::text]));

ALTER TABLE ONLY public.client_occurrence_messages
    ADD CONSTRAINT client_occurrence_messages_pkey PRIMARY KEY (id),
