-- -----------------------------------------------------------------------------
-- Views
-- -----------------------------------------------------------------------------

CREATE OR REPLACE VIEW public.vw_load_composition WITH (security_invoker=true) AS
 SELECT li.id AS item_id,
    li.tenant_id,
    li.load_id,
    li.fiscal_document_id,
    li.order_id,
    li.item_description,
    li.quantity,
    li.pallet_count,
    li.weight_kg,
    li.volume_m3,
    li.status AS item_status,
    fd.invoice_number,
    fd.access_key,
    fd.value AS document_value,
    fd.remitter,
    fd.recipient,
    fd.recipient_city,
    fd.recipient_state,
    o.order_number,
    l.load_number,
    l.status AS load_status
   FROM load_items li
     JOIN loads l ON l.id = li.load_id
     LEFT JOIN fiscal_documents fd ON fd.id = li.fiscal_document_id
     LEFT JOIN orders o ON o.id = li.order_id;

CREATE OR REPLACE VIEW public.vw_load_control WITH (security_invoker=true) AS
 SELECT l.id,
    l.tenant_id,
    l.load_number,
    l.external_load_number,
    l.load_date,
    l.arrival_date,
    l.status,
    l.operational_status,
    l.billing_status,
    l.payment_status,
    l.freight_amount,
    l.received_amount,
    l.freight_percent,
    l.total_weight_kg,
    l.total_volume_m3,
    l.total_pallet_count,
    l.invoice_count,
    l.cte_count,
    l.expected_payment_date,
    l.payment_date,
    l.gross_cargo_value,
    l.client_invoice_id,
    l.receivable_id,
    l.legacy_status_text,
    d.name AS driver_name,
    v.plate,
    l.trip_id,
    l.notes,
    l.created_at,
    l.updated_at
   FROM loads l
     LEFT JOIN drivers d ON l.driver_id = d.id
     LEFT JOIN vehicles v ON l.vehicle_id = v.id;

CREATE OR REPLACE VIEW public.vw_operational_workspace WITH (security_invoker=true) AS
 WITH stop_docs AS (
         SELECT dsd.dispatch_stop_id,
            jsonb_agg(jsonb_build_object('id', fd.id, 'number', fd.invoice_number, 'series', fd.invoice_series, 'value', fd.value, 'weight', fd.weight_kg, 'client', c.trade_name)) AS documents
           FROM dispatch_stop_documents dsd
             JOIN fiscal_documents fd ON fd.id = dsd.fiscal_document_id
             LEFT JOIN clients c ON c.id = fd.client_id
          GROUP BY dsd.dispatch_stop_id
        ), trip_stops AS (
         SELECT ds.dispatch_trip_id,
            jsonb_agg(jsonb_build_object('id', ds.id, 'order', ds.stop_order, 'status', ds.status, 'destination', ds.destination, 'planned_arrival', ds.planned_arrival_at, 'documents', COALESCE(sd.documents, '[]'::jsonb)) ORDER BY ds.stop_order) AS stops
           FROM dispatch_stops ds
             LEFT JOIN stop_docs sd ON sd.dispatch_stop_id = ds.id
          GROUP BY ds.dispatch_trip_id
        ), trip_loads AS (
         SELECT dtl.dispatch_trip_id,
            jsonb_agg(jsonb_build_object('id', l.id, 'number', l.load_number, 'status', l.status, 'weight', l.total_weight_kg, 'volume', l.total_volume_m3)) AS loads
           FROM dispatch_trip_loads dtl
             JOIN loads l ON l.id = dtl.load_id
          GROUP BY dtl.dispatch_trip_id
        )
 SELECT dt.id AS trip_id,
    dt.tenant_id,
    dt.status AS trip_status,
    dt.driver_id,
    dt.vehicle_id,
    dt.planned_start_at,
    dt.actual_start_at,
    v.plate AS vehicle_plate,
    d.name AS driver_name,
    COALESCE(tl.loads, '[]'::jsonb) AS loads,
    COALESCE(ts.stops, '[]'::jsonb) AS stops,
    dt.updated_at
   FROM dispatch_trips dt
     LEFT JOIN vehicles v ON v.id = dt.vehicle_id
     LEFT JOIN drivers d ON d.id = dt.driver_id
     LEFT JOIN trip_stops ts ON ts.dispatch_trip_id = dt.id
     LEFT JOIN trip_loads tl ON tl.dispatch_trip_id = dt.id;

CREATE OR REPLACE VIEW public.vw_unified_logistics_timeline WITH (security_invoker=true) AS
 SELECT oe.id AS event_id,
    oe.tenant_id,
    oe.event_type,
    oe.created_at AS occurred_at,
    oe.payload,
    ds.dispatch_trip_id AS trip_id,
    ds.id AS stop_id,
    ds.destination AS stop_location,
    pod.id AS pod_id,
    pod.receiver_name,
    pod.received_at AS pod_signed_at,
    inc.id AS incident_id,
    inc.status AS incident_status
   FROM operational_events oe
     LEFT JOIN dispatch_stops ds ON ds.id = oe.dispatch_stop_id
     LEFT JOIN proof_of_delivery pod ON pod.id = oe.proof_of_delivery_id
     LEFT JOIN incidents inc ON inc.operational_event_id = oe.id;

